CREATE OR REPLACE FUNCTION public.assign_document_template(p_service_code character varying, p_template_code character varying, p_is_required_expedition boolean DEFAULT true, p_is_required_renewal boolean DEFAULT false)
 RETURNS boolean
 LANGUAGE plpgsql
AS $function$
BEGIN
    INSERT INTO service_document_assignments (
        fiscal_service_id, document_template_id,
        is_required_expedition, is_required_renewal
    )
    SELECT
        fs.id,
        dt.id,
        p_is_required_expedition,
        p_is_required_renewal
    FROM fiscal_services fs, document_templates dt
    WHERE fs.service_code = p_service_code
    AND dt.template_code = p_template_code
    ON CONFLICT (fiscal_service_id, document_template_id) DO NOTHING;

    RETURN FOUND;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.assign_procedure_template(p_service_code character varying, p_template_code character varying, p_applies_to character varying DEFAULT 'both'::character varying)
 RETURNS boolean
 LANGUAGE plpgsql
AS $function$
BEGIN
    INSERT INTO service_procedure_assignments (
        fiscal_service_id, template_id, applies_to
    )
    SELECT
        fs.id,
        pt.id,
        p_applies_to
    FROM fiscal_services fs, procedure_templates pt
    WHERE fs.service_code = p_service_code
    AND pt.template_code = p_template_code
    ON CONFLICT (fiscal_service_id, template_id) DO NOTHING;

    RETURN FOUND;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.audit_role_permissions()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
    IF TG_OP = 'INSERT' THEN
        INSERT INTO permission_audit_log (
            action, table_name, record_id, permission_id, changed_by, new_value
        ) VALUES (
            'INSERT', 'role_permissions',
            NEW.role_id::TEXT || '-' || NEW.permission_id::TEXT,
            NEW.permission_id, NEW.created_by,
            jsonb_build_object('role_id', NEW.role_id, 'permission_id', NEW.permission_id, 'granted', NEW.granted)
        );
    ELSIF TG_OP = 'UPDATE' THEN
        INSERT INTO permission_audit_log (
            action, table_name, record_id, permission_id, changed_by, old_value, new_value
        ) VALUES (
            'UPDATE', 'role_permissions',
            NEW.role_id::TEXT || '-' || NEW.permission_id::TEXT,
            NEW.permission_id, NEW.created_by,
            jsonb_build_object('granted', OLD.granted),
            jsonb_build_object('granted', NEW.granted)
        );
    ELSIF TG_OP = 'DELETE' THEN
        INSERT INTO permission_audit_log (
            action, table_name, record_id, permission_id, changed_by, old_value
        ) VALUES (
            'DELETE', 'role_permissions',
            OLD.role_id::TEXT || '-' || OLD.permission_id::TEXT,
            OLD.permission_id, OLD.created_by,
            jsonb_build_object('role_id', OLD.role_id, 'permission_id', OLD.permission_id, 'granted', OLD.granted)
        );
    END IF;
    RETURN NULL;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.audit_role_permissions_change()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
    IF TG_OP = 'INSERT' THEN
        INSERT INTO audit_logs (
            user_id, action, entity_type, entity_id,
            new_values, ip_address, created_at
        ) VALUES (
            COALESCE(current_setting('app.current_user_id', true)::uuid, '00000000-0000-0000-0000-000000000000'::uuid),
            'PERMISSION_GRANTED',
            'role_permission',
            NEW.role_id::text,
            jsonb_build_object(
                'role_id', NEW.role_id,
                'permission_id', NEW.permission_id,
                'granted', NEW.granted
            ),
            COALESCE(current_setting('app.client_ip', true)::inet, '0.0.0.0'::inet),
            NOW()
        );
        RETURN NEW;
    ELSIF TG_OP = 'DELETE' THEN
        INSERT INTO audit_logs (
            user_id, action, entity_type, entity_id,
            old_values, ip_address, created_at
        ) VALUES (
            COALESCE(current_setting('app.current_user_id', true)::uuid, '00000000-0000-0000-0000-000000000000'::uuid),
            'PERMISSION_REVOKED',
            'role_permission',
            OLD.role_id::text,
            jsonb_build_object(
                'role_id', OLD.role_id,
                'permission_id', OLD.permission_id,
                'granted', OLD.granted
            ),
            COALESCE(current_setting('app.client_ip', true)::inet, '0.0.0.0'::inet),
            NOW()
        );
        RETURN OLD;
    END IF;
    RETURN NULL;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.audit_roles_change()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
    IF TG_OP = 'UPDATE' THEN
        -- Only audit meaningful changes (not menu_config updates which are frequent)
        IF OLD.name != NEW.name OR OLD.code != NEW.code OR OLD.entity_type IS DISTINCT FROM NEW.entity_type
           OR OLD.parent_role_id IS DISTINCT FROM NEW.parent_role_id THEN
            INSERT INTO audit_logs (
                user_id, action, entity_type, entity_id,
                old_values, new_values, ip_address, created_at
            ) VALUES (
                COALESCE(current_setting('app.current_user_id', true)::uuid, '00000000-0000-0000-0000-000000000000'::uuid),
                'ROLE_UPDATED',
                'role',
                NEW.id,
                jsonb_build_object('name', OLD.name, 'code', OLD.code, 'entity_type', OLD.entity_type, 'parent_role_id', OLD.parent_role_id),
                jsonb_build_object('name', NEW.name, 'code', NEW.code, 'entity_type', NEW.entity_type, 'parent_role_id', NEW.parent_role_id),
                COALESCE(current_setting('app.client_ip', true)::inet, '0.0.0.0'::inet),
                NOW()
            );
        END IF;
        RETURN NEW;
    ELSIF TG_OP = 'INSERT' THEN
        INSERT INTO audit_logs (
            user_id, action, entity_type, entity_id,
            new_values, ip_address, created_at
        ) VALUES (
            COALESCE(current_setting('app.current_user_id', true)::uuid, '00000000-0000-0000-0000-000000000000'::uuid),
            'ROLE_CREATED',
            'role',
            NEW.id::text,
            jsonb_build_object('name', NEW.name, 'code', NEW.code, 'entity_type', NEW.entity_type),
            COALESCE(current_setting('app.client_ip', true)::inet, '0.0.0.0'::inet),
            NOW()
        );
        RETURN NEW;
    ELSIF TG_OP = 'DELETE' THEN
        INSERT INTO audit_logs (
            user_id, action, entity_type, entity_id,
            old_values, ip_address, created_at
        ) VALUES (
            COALESCE(current_setting('app.current_user_id', true)::uuid, '00000000-0000-0000-0000-000000000000'::uuid),
            'ROLE_DELETED',
            'role',
            OLD.id::text,
            jsonb_build_object('name', OLD.name, 'code', OLD.code),
            COALESCE(current_setting('app.client_ip', true)::inet, '0.0.0.0'::inet),
            NOW()
        );
        RETURN OLD;
    END IF;
    RETURN NULL;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.audit_user_permissions()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
    IF TG_OP = 'INSERT' THEN
        INSERT INTO permission_audit_log (
            action, table_name, record_id, user_id, permission_id, changed_by, new_value
        ) VALUES (
            'INSERT', 'user_permissions',
            NEW.user_id::TEXT || '-' || NEW.permission_id::TEXT,
            NEW.user_id, NEW.permission_id, NEW.granted_by,
            jsonb_build_object(
                'user_id', NEW.user_id, 'permission_id', NEW.permission_id,
                'granted', NEW.granted, 'expires_at', NEW.expires_at, 'reason', NEW.reason
            )
        );
    ELSIF TG_OP = 'UPDATE' THEN
        INSERT INTO permission_audit_log (
            action, table_name, record_id, user_id, permission_id, changed_by, old_value, new_value
        ) VALUES (
            'UPDATE', 'user_permissions',
            NEW.user_id::TEXT || '-' || NEW.permission_id::TEXT,
            NEW.user_id, NEW.permission_id, NEW.granted_by,
            jsonb_build_object('granted', OLD.granted, 'expires_at', OLD.expires_at),
            jsonb_build_object('granted', NEW.granted, 'expires_at', NEW.expires_at)
        );
    ELSIF TG_OP = 'DELETE' THEN
        INSERT INTO permission_audit_log (
            action, table_name, record_id, user_id, permission_id, changed_by, old_value
        ) VALUES (
            'DELETE', 'user_permissions',
            OLD.user_id::TEXT || '-' || OLD.permission_id::TEXT,
            OLD.user_id, OLD.permission_id, OLD.granted_by,
            jsonb_build_object(
                'user_id', OLD.user_id, 'permission_id', OLD.permission_id,
                'granted', OLD.granted, 'expires_at', OLD.expires_at, 'reason', OLD.reason
            )
        );
    END IF;
    RETURN NULL;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.audit_user_permissions_change()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
        BEGIN
            IF TG_OP = 'INSERT' THEN
                INSERT INTO audit_logs (
                    user_id, action, entity_type, entity_id,
                    new_values, ip_address, created_at
                ) VALUES (
