CREATE OR REPLACE FUNCTION public.auto_generate_sr_reference()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
    IF NEW.reference IS NULL OR NEW.reference = '' THEN
        NEW.reference := generate_service_request_reference(NEW.workflow_code);
    END IF;
    RETURN NEW;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.batch_approve_verificaciones(p_verificacion_ids uuid[], p_agent_id uuid, p_notes text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
DECLARE
    v_id UUID;
    v_result JSONB;
    v_results JSONB[] := ARRAY[]::JSONB[];
    v_success_count INT := 0;
    v_error_count INT := 0;
BEGIN
    FOREACH v_id IN ARRAY p_verificacion_ids
    LOOP
        IF EXISTS (
            SELECT 1 FROM verificacion_funcionario
            WHERE id = v_id
            AND status = 'pendiente'
            AND (verification_data->'validacion_cruzada'->>'validacion_automatica_posible')::boolean = true
        ) THEN
            v_result := process_verificacion_funcionario(
                v_id, p_agent_id, 'aprobar',
                TRUE, TRUE, TRUE, NULL,
                COALESCE(p_notes, 'Aprobacion por lote - validacion cruzada OK')
            );

            IF (v_result->>'success')::boolean THEN
                v_success_count := v_success_count + 1;
            ELSE
                v_error_count := v_error_count + 1;
            END IF;
        ELSE
            v_result := jsonb_build_object(
                'success', false,
                'verificacion_id', v_id,
                'error', 'No es auto-validable o ya procesada'
            );
            v_error_count := v_error_count + 1;
        END IF;

        v_results := array_append(v_results, v_result || jsonb_build_object('verificacion_id', v_id));
    END LOOP;

    RETURN jsonb_build_object(
        'success', v_error_count = 0,
        'total', array_length(p_verificacion_ids, 1),
        'approved', v_success_count,
        'errors', v_error_count,
        'results', to_jsonb(v_results)
    );
END;
$function$
;

