CREATE OR REPLACE FUNCTION public.calculate_next_retry()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
    -- Exponential backoff: 10s * 3^retry_count
    -- Retry 0: 10s
    -- Retry 1: 30s
    -- Retry 2: 90s (1.5min)
    -- Retry 3: 270s (4.5min)
    -- Retry 4: 810s (13.5min)

    IF NEW.status = 'failed' AND NEW.retry_count < NEW.max_retries THEN
        NEW.next_retry_at := NOW() + (INTERVAL '10 seconds' * POWER(3, NEW.retry_count));
    ELSIF NEW.retry_count >= NEW.max_retries THEN
        -- Dead letter queue (échec définitif)
        NEW.status := 'dead_letter';
        NEW.next_retry_at := NULL;
    END IF;

    RETURN NEW;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.calculate_payment_ministry()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
    v_entity_code VARCHAR(50);
    v_ministry_id INTEGER;
    v_is_manual_payment BOOLEAN;
    v_config ministry_validation_config%ROWTYPE;
    v_service_type TEXT;
BEGIN
    -- Check if this is a manual payment (cash/check)
    v_is_manual_payment := NEW.payment_method IN ('cash', 'check');

    -- If no service_request_id, set defaults only for manual payments
    IF NEW.service_request_id IS NULL THEN
        NEW.entity_code := COALESCE(NEW.entity_code, 'UNKNOWN');
        IF v_is_manual_payment THEN
            NEW.requires_agent_validation := COALESCE(NEW.requires_agent_validation, true);
            NEW.auto_approval_eligible := COALESCE(NEW.auto_approval_eligible, false);
            NEW.workflow_status := COALESCE(NEW.workflow_status, 'pending_agent_review');
            NEW.sla_target_date := COALESCE(NEW.sla_target_date, NOW() + INTERVAL '24 hours');
        END IF;
        RETURN NEW;
    END IF;

    -- Get entity_code from service_request (source of truth)
    SELECT sr.entity_code INTO v_entity_code
    FROM service_requests sr
    WHERE sr.id = NEW.service_request_id;

    IF v_entity_code IS NOT NULL THEN
        NEW.entity_code := v_entity_code;

        -- Get ministry_id from entity (if entity has one)
        SELECT e.ministry_id INTO v_ministry_id
        FROM entities e
        WHERE e.code = v_entity_code;

        IF v_ministry_id IS NOT NULL THEN
            NEW.ministry_id := v_ministry_id;
        END IF;
    ELSE
        NEW.entity_code := COALESCE(NEW.entity_code, 'UNKNOWN');
    END IF;

    -- Apply ministry validation config for manual payments (existing logic preserved)
    IF v_is_manual_payment AND NEW.ministry_id IS NOT NULL THEN
        -- Try to get service_type for ministry config lookup
        SELECT fs.service_type INTO v_service_type
        FROM service_requests sr
        LEFT JOIN fiscal_services fs ON fs.id = sr.fiscal_service_id
        WHERE sr.id = NEW.service_request_id;

        IF v_service_type IS NOT NULL THEN
            SELECT * INTO v_config
            FROM ministry_validation_config mvc
            WHERE mvc.ministry_id = NEW.ministry_id
              AND mvc.service_type = v_service_type
              AND mvc.is_active = true;

            IF FOUND THEN
                NEW.auto_approval_eligible := (
                    v_config.auto_approval_enabled = true
                    AND NEW.total_amount <= v_config.auto_approval_max_amount
                );
                NEW.requires_agent_validation := NOT NEW.auto_approval_eligible;
                NEW.sla_target_date := NOW() + (v_config.target_review_hours || ' hours')::INTERVAL;
                NEW.workflow_status := CASE
                    WHEN NEW.auto_approval_eligible THEN 'auto_processing'
                    ELSE 'pending_agent_review'
                END;
                RETURN NEW;
            END IF;
        END IF;
    END IF;

    -- Default behavior ONLY for manual payments if no ministry config found
    IF v_is_manual_payment THEN
        NEW.requires_agent_validation := COALESCE(NEW.requires_agent_validation, true);
        NEW.auto_approval_eligible := COALESCE(NEW.auto_approval_eligible, false);
        NEW.workflow_status := COALESCE(NEW.workflow_status, 'pending_agent_review');
        NEW.sla_target_date := COALESCE(NEW.sla_target_date, NOW() + INTERVAL '24 hours');
    END IF;

    RETURN NEW;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.calculate_processing_duration()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
    -- Calculate duration if assignment is completed and was started
    IF NEW.status IN ('completed', 'reassigned', 'cancelled') AND
       NEW.started_at IS NOT NULL AND
       NEW.completed_at IS NOT NULL THEN
        NEW.processing_duration_hours = EXTRACT(EPOCH FROM (NEW.completed_at - NEW.started_at)) / 3600.0;
    END IF;

    -- Check if deadline was met
    IF NEW.status = 'completed' AND NEW.deadline IS NOT NULL THEN
        NEW.deadline_met = (NEW.completed_at <= NEW.deadline);
    END IF;

    -- Update updated_at timestamp
    NEW.updated_at = NOW();

    RETURN NEW;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.calculate_queue_priority()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
    score INTEGER := 0;
    hours_remaining INTERVAL;
BEGIN
    -- Base: 0 points

    -- +30 si montant > 1M XAF (gros contribuables)
    IF NEW.amount > 1000000 THEN
        score := score + 30;
    END IF;

    -- +20 si SLA < 6h restantes (urgence)
    hours_remaining := NEW.sla_deadline - NOW();
    IF hours_remaining < INTERVAL '6 hours' THEN
        score := score + 20;
    ELSIF hours_remaining < INTERVAL '12 hours' THEN
        score := score + 10;
    END IF;

    -- +15 si retry >= 2 (frustration user)
    IF NEW.retry_count >= 2 THEN
        score := score + 15;
    END IF;

    -- +10 si IVA (volume élevé, traitement prioritaire)
    IF NEW.declaration_type LIKE 'IVA%' OR NEW.declaration_type = 'actual_vat' THEN
        score := score + 10;
    END IF;

    -- +10 si escalated
    IF NEW.escalated = true THEN
        score := score + 10;
    END IF;

    -- Limiter score max à 100
    NEW.priority_score := LEAST(score, 100);

    RETURN NEW;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.check_department_parent()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
    -- Only validate departments
    IF NEW.entity_type = 'department' THEN
        -- Departments must have at least one parent (entity OR ministry)
        IF NEW.parent_entity_id IS NULL AND NEW.ministry_id IS NULL THEN
            RAISE EXCEPTION 'Departments must have a parent_entity_id OR ministry_id';
        END IF;
    END IF;

    RETURN NEW;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.check_duplicate_identifier_usage(p_blind_index bytea, p_identifier_type identifier_type_enum, p_expected_user_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
AS $function$
DECLARE
    v_other_user_id UUID;
BEGIN
    SELECT user_id INTO v_other_user_id
    FROM verified_identifiers
    WHERE blind_index = p_blind_index
      AND identifier_type = p_identifier_type
      AND is_active = TRUE
      AND user_id IS NOT NULL
      AND user_id != p_expected_user_id
    LIMIT 1;

    RETURN v_other_user_id;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.check_verified_identifier(p_blind_index bytea, p_identifier_type identifier_type_enum)
 RETURNS TABLE(id uuid, user_id uuid, source verification_source_enum, verified_at timestamp with time zone, expires_at timestamp with time zone, is_expired boolean)
 LANGUAGE plpgsql
AS $function$
BEGIN
    RETURN QUERY
    SELECT
        vi.id,
        vi.user_id,
        vi.source,
        vi.verified_at,
        vi.expires_at,
        CASE
            WHEN vi.expires_at IS NOT NULL AND vi.expires_at < NOW()
            THEN TRUE
            ELSE FALSE
        END as is_expired
    FROM verified_identifiers vi
    WHERE vi.blind_index = p_blind_index
      AND vi.identifier_type = p_identifier_type
      AND vi.is_active = TRUE
    LIMIT 1;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.cleanup_expired_identifiers()
 RETURNS integer
 LANGUAGE plpgsql
AS $function$
DECLARE
    v_count INTEGER;
BEGIN
    -- Desactiver les identifiants expires depuis plus de 30 jours
    WITH deactivated AS (
        UPDATE verified_identifiers
        SET is_active = FALSE,
            updated_at = NOW()
        WHERE expires_at < NOW() - INTERVAL '30 days'
          AND is_active = TRUE
        RETURNING id
    )
    SELECT COUNT(*) INTO v_count FROM deactivated;

    RETURN v_count;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.cleanup_expired_permissions()
 RETURNS integer
 LANGUAGE plpgsql
AS $function$
DECLARE
    deleted_count INTEGER;
BEGIN
    DELETE FROM user_permissions
    WHERE expires_at IS NOT NULL
    AND expires_at < NOW();

    GET DIAGNOSTICS deleted_count = ROW_COUNT;

    -- Enregistrer dans audit log
    INSERT INTO permission_audit_log (
        action, table_name, record_id, changed_by, changed_at, new_value
    ) VALUES (
        'CLEANUP', 'user_permissions', 'expired', NULL, NOW(),
        jsonb_build_object('deleted_count', deleted_count)
    );

    RETURN deleted_count;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.cleanup_old_gemini_logs(p_retention_days integer DEFAULT 90)
 RETURNS integer
 LANGUAGE plpgsql
AS $function$
DECLARE
    v_deleted INTEGER;
BEGIN
    DELETE FROM gemini_processing_logs
    WHERE created_at < CURRENT_DATE - (p_retention_days || ' days')::INTERVAL;

    GET DIAGNOSTICS v_deleted = ROW_COUNT;

    RAISE NOTICE 'Deleted % old gemini processing logs (older than % days)', v_deleted, p_retention_days;

    RETURN v_deleted;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.cleanup_permission_audit_log(retention_days integer DEFAULT 90)
 RETURNS TABLE(archived_count bigint, remaining_count bigint)
 LANGUAGE plpgsql
AS $function$
        DECLARE
            v_archived BIGINT;
            v_remaining BIGINT;
        BEGIN
            WITH moved AS (
                DELETE FROM permission_audit_log
                WHERE changed_at < NOW() - MAKE_INTERVAL(days => retention_days)
                RETURNING *
            )
            INSERT INTO permission_audit_log_archive
            SELECT * FROM moved;

            GET DIAGNOSTICS v_archived = ROW_COUNT;
            SELECT COUNT(*) INTO v_remaining FROM permission_audit_log;
            RETURN QUERY SELECT v_archived, v_remaining;
        END;
        $function$
;

CREATE OR REPLACE FUNCTION public.company_search_query(search_text text)
 RETURNS tsquery
 LANGUAGE sql
 IMMUTABLE PARALLEL SAFE STRICT
AS $function$
            SELECT CASE
                WHEN TRIM(search_text) = '' THEN ''::tsquery
                ELSE (
                    SELECT string_agg(lexeme || ':*', ' & ')::tsquery
                    FROM unnest(string_to_array(TRIM(search_text), ' ')) AS lexeme
                    WHERE lexeme != ''
                )
            END
        $function$
;

CREATE OR REPLACE FUNCTION public.confirm_appointment_hold(p_service_request_id uuid)
 RETURNS TABLE(success boolean, appointment_date date, appointment_time time without time zone, location_id uuid, error_message text)
 LANGUAGE plpgsql
AS $function$
DECLARE
    v_hold RECORD;
BEGIN
    -- Find active hold
    SELECT * INTO v_hold
    FROM appointment_holds
    WHERE service_request_id = p_service_request_id
      AND status = 'held'
      AND expires_at > NOW()
    FOR UPDATE;

    IF NOT FOUND THEN
        RETURN QUERY SELECT FALSE, NULL::DATE, NULL::TIME, NULL::UUID,
            'No active hold found or hold expired'::TEXT;
        RETURN;
    END IF;

    -- Confirm the hold
    UPDATE appointment_holds
    SET status = 'confirmed', confirmed_at = NOW(), updated_at = NOW()
    WHERE id = v_hold.id;

    -- Create permanent reservation (WAS MISSING since migration 030)
    INSERT INTO appointment_reservations (
        service_request_id,
        entity_location_id,
        appointment_date,
        appointment_time,
        status
    ) VALUES (
        p_service_request_id,
        v_hold.entity_location_id,
        v_hold.appointment_date,
        v_hold.appointment_time,
        'scheduled'
    );

    -- Update service_request with appointment details
    UPDATE service_requests
    SET
        cita_date = v_hold.appointment_date,
        cita_time = v_hold.appointment_time,
        entity_location_id = v_hold.entity_location_id,
        updated_at = NOW()
    WHERE id = p_service_request_id;

    RETURN QUERY SELECT TRUE, v_hold.appointment_date, v_hold.appointment_time,
        v_hold.entity_location_id, NULL::TEXT;
END;
$function$
;

