CREATE OR REPLACE FUNCTION public.deactivate_verified_identifier(p_blind_index bytea, p_identifier_type identifier_type_enum)
 RETURNS uuid
 LANGUAGE plpgsql
AS $function$
DECLARE
    v_id UUID;
BEGIN
    UPDATE verified_identifiers
    SET is_active = FALSE,
        updated_at = NOW()
    WHERE blind_index = p_blind_index
      AND identifier_type = p_identifier_type
      AND is_active = TRUE
    RETURNING id INTO v_id;

    RETURN v_id;
