CREATE OR REPLACE FUNCTION public.detect_duplicate_payments()
 RETURNS TABLE(payment_id_1 uuid, payment_id_2 uuid, service_request_id_1 uuid, service_request_id_2 uuid, service_request_ref_1 character varying, service_request_ref_2 character varying, user_id uuid, amount numeric, time_diff interval)
 LANGUAGE plpgsql
AS $function$
BEGIN
    RETURN QUERY
    SELECT
        sp1.id as payment_id_1,
        sp2.id as payment_id_2,
        sp1.service_request_id as service_request_id_1,
        sp2.service_request_id as service_request_id_2,
        sr1.reference as service_request_ref_1,
        sr2.reference as service_request_ref_2,
        sp1.user_id,
        sp1.total_amount as amount,
        sp2.created_at - sp1.created_at as time_diff
    FROM service_payments sp1
    JOIN service_payments sp2
        ON sp1.user_id = sp2.user_id
        AND sp1.total_amount = sp2.total_amount
        AND sp1.id < sp2.id
        AND sp2.created_at - sp1.created_at < INTERVAL '24 hours'
    LEFT JOIN service_requests sr1 ON sr1.id = sp1.service_request_id
    LEFT JOIN service_requests sr2 ON sr2.id = sp2.service_request_id
    WHERE sp1.workflow_status NOT IN ('cancelled_by_user', 'cancelled_by_agent')
      AND sp2.workflow_status NOT IN ('cancelled_by_user', 'cancelled_by_agent')
      AND NOT EXISTS (
          SELECT 1 FROM payment_anomalies pa
          WHERE pa.entity_id IN (sp1.id, sp2.id)
            AND pa.anomaly_type = 'duplicate_suspected'
            AND pa.status NOT IN ('resolved', 'false_positive')
      );
END;
$function$
;

CREATE OR REPLACE FUNCTION public.evaluate_document_condition(p_condition_type document_condition_type_enum, p_condition_value jsonb, p_context jsonb)
 RETURNS boolean
 LANGUAGE plpgsql
 IMMUTABLE
AS $function$
DECLARE
    v_age INTEGER;
    v_threshold INTEGER;
    v_nationality VARCHAR;
BEGIN
    -- Toujours = TRUE
    IF p_condition_type = 'always' THEN
        RETURN TRUE;
    END IF;

    -- Extraire du contexte
    v_age := (p_context->>'age')::INTEGER;
    v_nationality := p_context->>'nationality';

    CASE p_condition_type
        WHEN 'age_less_than' THEN
            v_threshold := (p_condition_value->>'value')::INTEGER;
            RETURN v_age IS NOT NULL AND v_age < v_threshold;

        WHEN 'age_greater_than' THEN
            v_threshold := (p_condition_value->>'value')::INTEGER;
            RETURN v_age IS NOT NULL AND v_age >= v_threshold;

        WHEN 'is_minor' THEN
            RETURN v_age IS NOT NULL AND v_age < 18;

        WHEN 'is_adult' THEN
            RETURN v_age IS NULL OR v_age >= 18;

        WHEN 'is_renewal' THEN
            RETURN COALESCE((p_context->>'solicitud_type')::TEXT, '') = 'renovacion';

        WHEN 'is_new' THEN
            RETURN COALESCE((p_context->>'solicitud_type')::TEXT, 'expedicion') = 'expedicion';

        WHEN 'is_duplicate' THEN
            RETURN COALESCE((p_context->>'solicitud_type')::TEXT, '') = 'duplicado';

        WHEN 'has_previous' THEN
            RETURN COALESCE((p_context->>'has_previous_document')::BOOLEAN, FALSE);

        WHEN 'is_foreign' THEN
            RETURN v_nationality IS NOT NULL AND v_nationality != 'GQ' AND v_nationality != 'GNQ';

        WHEN 'is_national' THEN
            RETURN v_nationality IS NULL OR v_nationality IN ('GQ', 'GNQ');

        WHEN 'custom' THEN
            -- Conditions custom évaluées par le backend
            RETURN TRUE;

        ELSE
            RETURN TRUE;
    END CASE;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.fiscal_services_search_vector_update()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  NEW.search_vector :=
    setweight(to_tsvector('spanish', COALESCE(NEW.name_es, '')), 'A') ||
    setweight(to_tsvector('spanish', COALESCE(NEW.description_es, '')), 'B');
  RETURN NEW;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.flag_embedding_update()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
    -- Flag for update if relevant fields changed
    IF (TG_OP = 'INSERT') OR
       (OLD.name_es IS DISTINCT FROM NEW.name_es) OR
       (OLD.description_es IS DISTINCT FROM NEW.description_es) OR
       (OLD.category_id IS DISTINCT FROM NEW.category_id) THEN
        NEW.needs_embedding_update = TRUE;
    END IF;

    RETURN NEW;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.fn_audit_service_bundle_items()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
    v_changed_by UUID;
    v_batch_id UUID;
BEGIN
    -- Try to get user and batch from session variables
    BEGIN
        v_changed_by := current_setting('app.current_user_id', true)::UUID;
    EXCEPTION WHEN OTHERS THEN
        v_changed_by := NULL;
    END;
    BEGIN
        v_batch_id := current_setting('app.audit_batch_id', true)::UUID;
    EXCEPTION WHEN OTHERS THEN
        v_batch_id := NULL;
    END;

    IF TG_OP = 'INSERT' THEN
        INSERT INTO service_bundle_item_audit
            (item_id, bundle_id, fiscal_service_id, zone_id, fee_type,
             action, new_amount, new_values, changed_by, batch_id)
        VALUES
            (NEW.id, NEW.bundle_id, NEW.fiscal_service_id, NEW.zone_id, NEW.fee_type,
             'INSERT', NEW.amount,
             jsonb_build_object(
                 'ministry_id', NEW.ministry_id,
                 'is_fixed_across_zones', NEW.is_fixed_across_zones,
                 'display_order', NEW.display_order,
                 'is_active', NEW.is_active
             ),
             v_changed_by, v_batch_id);
        RETURN NEW;

    ELSIF TG_OP = 'UPDATE' THEN
        -- Audit if amount, is_active, fee_type, ministry_id, or is_fixed_across_zones changed
        IF NEW.amount IS DISTINCT FROM OLD.amount
           OR NEW.is_active IS DISTINCT FROM OLD.is_active
           OR NEW.fee_type IS DISTINCT FROM OLD.fee_type
           OR NEW.ministry_id IS DISTINCT FROM OLD.ministry_id
           OR NEW.is_fixed_across_zones IS DISTINCT FROM OLD.is_fixed_across_zones THEN

            INSERT INTO service_bundle_item_audit
                (item_id, bundle_id, fiscal_service_id, zone_id, fee_type,
                 action, old_amount, new_amount, old_values, new_values, changed_by, batch_id)
            VALUES
                (NEW.id, NEW.bundle_id, NEW.fiscal_service_id, NEW.zone_id, NEW.fee_type,
                 'UPDATE', OLD.amount, NEW.amount,
                 jsonb_build_object(
                     'ministry_id', OLD.ministry_id,
                     'is_fixed_across_zones', OLD.is_fixed_across_zones,
                     'is_active', OLD.is_active,
                     'fee_type', OLD.fee_type
                 ),
                 jsonb_build_object(
                     'ministry_id', NEW.ministry_id,
                     'is_fixed_across_zones', NEW.is_fixed_across_zones,
                     'is_active', NEW.is_active,
                     'fee_type', NEW.fee_type
                 ),
                 v_changed_by, v_batch_id);
        END IF;
        RETURN NEW;

    ELSIF TG_OP = 'DELETE' THEN
        INSERT INTO service_bundle_item_audit
            (item_id, bundle_id, fiscal_service_id, zone_id, fee_type,
             action, old_amount, old_values, changed_by, batch_id)
        VALUES
            (OLD.id, OLD.bundle_id, OLD.fiscal_service_id, OLD.zone_id, OLD.fee_type,
             'DELETE', OLD.amount,
             jsonb_build_object(
                 'ministry_id', OLD.ministry_id,
                 'is_fixed_across_zones', OLD.is_fixed_across_zones,
                 'is_active', OLD.is_active
             ),
             v_changed_by, v_batch_id);
        RETURN OLD;
    END IF;

    RETURN NULL;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.fn_auto_recompute_on_config_change()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
    BEGIN
        PERFORM recompute_effective_configs(NULL);
        RETURN NULL;
    END;
    $function$
;

CREATE OR REPLACE FUNCTION public.fn_auto_set_submitted_at()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF NEW.status = 'SUBMITTED' AND (OLD.status IS NULL OR OLD.status != 'SUBMITTED') THEN
    IF NEW.submitted_at IS NULL THEN
      NEW.submitted_at := NOW();
    END IF;
  END IF;
  RETURN NEW;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.fn_enforce_bundle_sr_integrity()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
    IF NEW.workflow_code IN ('BUNDLE_PAYMENT', 'FIELD_INSPECTION') THEN
        IF NEW.commercial_license_id IS NULL THEN
            RAISE EXCEPTION
                'service_request with workflow_code % must have commercial_license_id (bundle integrity)',
                NEW.workflow_code
                USING ERRCODE = 'check_violation';
        END IF;
        IF NEW.fiscal_year IS NULL THEN
            RAISE EXCEPTION
                'service_request with workflow_code % must have fiscal_year (bundle integrity)',
                NEW.workflow_code
                USING ERRCODE = 'check_violation';
        END IF;
        IF NEW.source NOT IN ('citizen_wizard', 'field_inspection') THEN
            RAISE EXCEPTION
                'bundle service_request source must be citizen_wizard or field_inspection, got %',
                NEW.source
                USING ERRCODE = 'check_violation';
        END IF;
    END IF;
    -- Non-bundle workflows: no constraint (trigger is no-op)
    RETURN NEW;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.fn_resolve_workflow_code()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
    v_base_code VARCHAR(100);
    v_resolution_key VARCHAR(100);
    v_resolved_code VARCHAR(100);
BEGIN
    -- Only act if workflow_code is a base code (has children in valid_workflow_codes)
    SELECT code INTO v_base_code
    FROM valid_workflow_codes
    WHERE code = NEW.workflow_code
      AND base_code IS NULL
      AND EXISTS (
          SELECT 1 FROM valid_workflow_codes vc2
          WHERE vc2.base_code = NEW.workflow_code
      );

    -- Not a base code with children → nothing to do
    IF v_base_code IS NULL THEN
        RETURN NEW;
    END IF;

    -- Extract resolution key from form_data (priority: sub_type > motivo > solicitud_type)
    v_resolution_key := UPPER(COALESCE(
        NULLIF(TRIM(NEW.form_data->>'sub_type'), ''),
        NULLIF(TRIM(NEW.form_data->>'motivo'), ''),
        NULLIF(TRIM(NEW.form_data->>'solicitud_type'), '')
    ));

    IF v_resolution_key IS NULL THEN
        -- No key available, keep base code (legitimate for primera expedicion)
        RETURN NEW;
    END IF;

    -- Look up resolved code
    SELECT code INTO v_resolved_code
    FROM valid_workflow_codes
    WHERE base_code = v_base_code
      AND resolution_key = v_resolution_key
      AND is_active = TRUE;

    IF v_resolved_code IS NOT NULL THEN
        -- Auto-resolve
        NEW.workflow_code := v_resolved_code;
        RAISE LOG 'fn_resolve_workflow_code: % → % (key=%)',
                   v_base_code, v_resolved_code, v_resolution_key;
    END IF;

    -- If no match found, keep original (may be a valid base code like PASAPORTE_NUEVO for EXPEDICION)
    RETURN NEW;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.fn_sync_license_service_request_id()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
    IF NEW.commercial_license_id IS NOT NULL THEN
        UPDATE commercial_licenses
            SET service_request_id = NEW.id,
                updated_at = NOW()
            WHERE id = NEW.commercial_license_id
              AND (service_request_id IS NULL OR service_request_id = NEW.id);
    END IF;
    RETURN NEW;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.generate_batch_reference()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
    year_str TEXT := TO_CHAR(NOW(), 'YYYY');
    seq_num INT;
BEGIN
    -- Advisory lock prevents concurrent triggers from reading same MAX
    -- Lock key: hash of 'batch_ref' (stable across restarts)
    PERFORM pg_advisory_xact_lock(hashtext('batch_reference_gen'));

    SELECT COALESCE(MAX(CAST(SUBSTRING(reference FROM 'LOT-' || year_str || '-(\d+)') AS INT)), 0) + 1
    INTO seq_num FROM batch_requests WHERE reference LIKE 'LOT-' || year_str || '-%';

    NEW.reference := 'LOT-' || year_str || '-' || LPAD(seq_num::TEXT, 5, '0');
    RETURN NEW;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.generate_export_filename(p_export_type export_type_enum, p_period_start date, p_period_end date, p_format character varying)
 RETURNS character varying
 LANGUAGE plpgsql
AS $function$
DECLARE
    v_prefix VARCHAR;
    v_timestamp VARCHAR;
BEGIN
    -- Prefix selon type
    v_prefix := CASE p_export_type
        WHEN 'sage_x3' THEN 'SAGE_TRS'
        WHEN 'ministry_report' THEN 'RPT_MIN'
        WHEN 'bank_central' THEN 'BEAC'
        WHEN 'audit_report' THEN 'AUDIT'
        WHEN 'reconciliation' THEN 'RECON'
        ELSE 'EXPORT'
    END;

    v_timestamp := TO_CHAR(NOW(), 'YYYYMMDD_HH24MI');

    RETURN v_prefix || '_' ||
           TO_CHAR(p_period_start, 'YYYYMMDD') || '_' ||
           TO_CHAR(p_period_end, 'YYYYMMDD') || '_' ||
           v_timestamp || '.' || p_format;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.generate_idempotency_key(p_user_id uuid, p_amount numeric, p_timestamp timestamp with time zone)
 RETURNS character varying
 LANGUAGE plpgsql
AS $function$
BEGIN
    RETURN encode(
        digest(
            p_user_id::TEXT || p_amount::TEXT || p_timestamp::TEXT,
            'sha256'
        ),
        'hex'
    );
END;
$function$
;

CREATE OR REPLACE FUNCTION public.generate_payment_installments(p_payment_plan_id uuid)
 RETURNS void
 LANGUAGE plpgsql
AS $function$
DECLARE
    v_plan RECORD;
    v_installment_number INTEGER;
    v_due_date DATE;
BEGIN
    -- Récupère le plan de paiement
    SELECT * INTO v_plan FROM payment_plans WHERE id = p_payment_plan_id;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Payment plan % not found', p_payment_plan_id;
    END IF;

    -- Génère les acomptes
    FOR v_installment_number IN 1..v_plan.number_of_installments LOOP
        -- Calcule la date d'échéance
        IF v_plan.installment_frequency = 'monthly' THEN
            v_due_date := v_plan.first_installment_due_date + ((v_installment_number - 1) || ' months')::INTERVAL;
        ELSIF v_plan.installment_frequency = 'quarterly' THEN
            v_due_date := v_plan.first_installment_due_date + ((v_installment_number - 1) * 3 || ' months')::INTERVAL;
        ELSE
            -- Custom: ajoute 30 jours par défaut
            v_due_date := v_plan.first_installment_due_date + ((v_installment_number - 1) * 30 || ' days')::INTERVAL;
        END IF;

        -- Insère l'acompte
        INSERT INTO payment_installments (
            payment_plan_id,
            installment_number,
            amount_due,
            due_date
        ) VALUES (
            p_payment_plan_id,
            v_installment_number,
            v_plan.installment_amount,
            v_due_date
        );
    END LOOP;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.generate_service_request_reference(p_workflow_code character varying)
 RETURNS character varying
 LANGUAGE plpgsql
AS $function$
DECLARE
    v_prefix VARCHAR(10);
    v_year VARCHAR(4);
    v_sequence INTEGER;
    v_reference VARCHAR(50);
    v_code_upper VARCHAR(100);
BEGIN
    -- BUG-A FIX: Advisory lock pour sérialiser les appels concurrents
    -- Key stable = hashtext d'une chaîne connue (reproducible across restarts)
    PERFORM pg_advisory_xact_lock(hashtext('service_request_reference_gen'));

    v_code_upper := UPPER(p_workflow_code);

    -- BUG-B FIX: Matching UPPERCASE explicite
    -- BUG-C FIX: Ajout BUNDLE_PAYMENT (LIC) et FIELD_INSPECTION (FLD)
    v_prefix := CASE
        WHEN v_code_upper LIKE 'RESIDENCIA%' THEN 'RES'
        WHEN v_code_upper LIKE 'PASAPORTE%' THEN 'PAS'
        WHEN v_code_upper LIKE 'FP_CARNET_FUNCIONARIO%' THEN 'CFN'
        WHEN v_code_upper LIKE 'CONDUCIR%' THEN 'CON'
        WHEN v_code_upper LIKE 'VEHICULO%' THEN 'VHC'
        WHEN v_code_upper LIKE 'CONTRATO%' THEN 'CTR'
        WHEN v_code_upper LIKE 'FP_VERIFICACION%' THEN 'VER'
        WHEN v_code_upper LIKE 'FP_PROMOCION%' THEN 'PRO'
        WHEN v_code_upper LIKE 'FP_CERTIFICADO%' THEN 'CER'
        WHEN v_code_upper LIKE 'FP_PERMISO%' THEN 'PER'
        WHEN v_code_upper LIKE 'PRORROGA%'
             OR v_code_upper LIKE 'PERMANENCIA%'
             OR v_code_upper LIKE 'SALIDA%' THEN 'VIS'
        WHEN v_code_upper = 'BUNDLE_PAYMENT' THEN 'LIC'
        WHEN v_code_upper = 'FIELD_INSPECTION' THEN 'FLD'
        ELSE 'SRV'
    END;

    v_year := TO_CHAR(NOW(), 'YYYY');

    -- Next sequence number for this prefix+year
    -- SPLIT_PART(ref, '-', 3) = 'NNNNN' part of 'PREFIX-YYYY-NNNNN'
    SELECT COALESCE(MAX(
        CAST(NULLIF(SPLIT_PART(reference, '-', 3), '') AS INTEGER)
    ), 0) + 1
    INTO v_sequence
    FROM service_requests
    WHERE reference LIKE v_prefix || '-' || v_year || '-%';

    v_reference := v_prefix || '-' || v_year || '-' || LPAD(v_sequence::TEXT, 5, '0');

    RETURN v_reference;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.get_agent_available_workflows(p_agent_profile_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
AS $function$
DECLARE
    v_agent RECORD;
    v_workflows JSONB;
BEGIN
    -- Get agent profile
    SELECT id, entity_id, specializations
    INTO v_agent
    FROM agent_profiles
    WHERE id = p_agent_profile_id AND is_active = true;

    IF NOT FOUND THEN
        RETURN '[]'::jsonb;
    END IF;

    -- If agent has explicit specializations, use them
    IF v_agent.specializations IS NOT NULL AND jsonb_array_length(v_agent.specializations) > 0 THEN
        RETURN v_agent.specializations;
    END IF;

    -- Otherwise, inherit from entity
    IF v_agent.entity_id IS NOT NULL THEN
        RETURN get_entity_workflows(v_agent.entity_id);
    END IF;

    -- No entity assigned, return empty
    RETURN '[]'::jsonb;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.get_available_slots_v2(p_entity_code character varying, p_location_name character varying, p_from_date date, p_limit integer DEFAULT 6)
 RETURNS TABLE(slot_date date, slot_time time without time zone, location_name character varying, location_address text, slots_remaining integer)
 LANGUAGE plpgsql
AS $function$
DECLARE
    v_current_date DATE := p_from_date;
    v_max_search_days INTEGER := 60;
    v_day_count INTEGER := 0;
    v_slots_found INTEGER := 0;
    v_slot RECORD;
    v_location_ids UUID[];
BEGIN
    -- Pre-fetch entity_location IDs for this entity+location combo
    SELECT array_agg(el.id) INTO v_location_ids
    FROM entity_locations el
    WHERE el.entity_code = p_entity_code
    AND el.location_name = p_location_name
    AND el.is_active = TRUE;

    IF v_location_ids IS NULL THEN
        RETURN;
    END IF;

    WHILE v_day_count < v_max_search_days AND v_slots_found < p_limit LOOP
        IF EXTRACT(DOW FROM v_current_date)::INTEGER IN (0, 6) THEN
            v_current_date := v_current_date + INTERVAL '1 day';
            v_day_count := v_day_count + 1;
            CONTINUE;
        END IF;

        IF is_appointment_date_blocked(p_entity_code, v_current_date) THEN
            v_current_date := v_current_date + INTERVAL '1 day';
            v_day_count := v_day_count + 1;
            CONTINUE;
        END IF;

        FOR v_slot IN (
            SELECT
                v_current_date as slot_date,
                sc.start_time as slot_time,
                el.location_name,
                el.location_address,
                sc.max_appointments_per_slot - COALESCE(res.cnt, 0) - COALESCE(holds.cnt, 0) as slots_remaining
            FROM appointment_slot_configs sc
            INNER JOIN entity_locations el ON el.id = sc.entity_location_id
            LEFT JOIN (
                SELECT ar.appointment_time, COUNT(*) as cnt
                FROM appointment_reservations ar
                WHERE ar.entity_location_id = ANY(v_location_ids)
                AND ar.appointment_date = v_current_date
                AND ar.status IN ('scheduled', 'confirmed')
                GROUP BY ar.appointment_time
            ) res ON sc.start_time = res.appointment_time
            LEFT JOIN (
                SELECT ah.appointment_time, COUNT(*) as cnt
                FROM appointment_holds ah
                WHERE ah.entity_location_id = ANY(v_location_ids)
                AND ah.appointment_date = v_current_date
                AND ah.status = 'held'
                AND ah.expires_at > NOW()
                GROUP BY ah.appointment_time
            ) holds ON sc.start_time = holds.appointment_time
            WHERE sc.entity_location_id = ANY(v_location_ids)
            AND sc.is_active = TRUE
            AND sc.day_of_week = (EXTRACT(DOW FROM v_current_date)::INTEGER + 6) % 7
            AND (sc.max_appointments_per_slot - COALESCE(res.cnt, 0) - COALESCE(holds.cnt, 0)) > 0
            ORDER BY sc.start_time
        )
        LOOP
            IF v_slots_found < p_limit THEN
                slot_date := v_slot.slot_date;
                slot_time := v_slot.slot_time;
                location_name := v_slot.location_name;
                location_address := v_slot.location_address;
                slots_remaining := v_slot.slots_remaining;
                v_slots_found := v_slots_found + 1;
                RETURN NEXT;
            END IF;
        END LOOP;

        v_current_date := v_current_date + INTERVAL '1 day';
        v_day_count := v_day_count + 1;
    END LOOP;

    RETURN;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.get_available_slots_v3(p_entity_location_id uuid, p_from_date date, p_limit integer DEFAULT 20)
 RETURNS TABLE(slot_date date, slot_time time without time zone, location_name character varying, location_address text, city character varying, slots_remaining integer)
 LANGUAGE plpgsql
AS $function$
DECLARE
    v_entity_code VARCHAR(50);
BEGIN
    -- Resolve entity_code once (needed for blocked dates check)
    SELECT el.entity_code INTO v_entity_code
    FROM entity_locations el
    WHERE el.id = p_entity_location_id AND el.is_active = TRUE;

    IF v_entity_code IS NULL THEN
        RETURN;
    END IF;

    RETURN QUERY
    WITH date_range AS (
        SELECT d::date AS dt
        FROM generate_series(
            p_from_date,
            p_from_date + INTERVAL '59 days',
            INTERVAL '1 day'
        ) AS d
        WHERE EXTRACT(DOW FROM d)::INTEGER NOT IN (0, 6)  -- skip weekends
    ),
    -- Generate individual time slots from each config's range
    time_slots AS (
        SELECT
            dr.dt,
            (sc.start_time + (gs.n * sc.slot_duration_minutes) * INTERVAL '1 minute')::TIME AS t_slot,
            sc.id AS config_id,
            sc.max_appointments_per_slot,
            el.location_name AS loc_name,
            el.location_address AS loc_address,
            el.city AS loc_city
        FROM date_range dr
        CROSS JOIN appointment_slot_configs sc
        INNER JOIN entity_locations el ON el.id = sc.entity_location_id
        CROSS JOIN LATERAL generate_series(
            0,
            GREATEST(0, (EXTRACT(EPOCH FROM (sc.end_time - sc.start_time))::INTEGER / (sc.slot_duration_minutes * 60)) - 1)
        ) AS gs(n)
        WHERE sc.entity_location_id = p_entity_location_id
        AND sc.is_active = TRUE
        AND sc.day_of_week = (EXTRACT(DOW FROM dr.dt)::INTEGER + 6) % 7
        AND NOT is_appointment_date_blocked(v_entity_code, dr.dt)
    )
    SELECT
        ts.dt AS slot_date,
        ts.t_slot AS slot_time,
        ts.loc_name AS location_name,
        ts.loc_address AS location_address,
        ts.loc_city AS city,
        (ts.max_appointments_per_slot - COALESCE(res.cnt, 0) - COALESCE(holds.cnt, 0))::INTEGER AS slots_remaining
    FROM time_slots ts
    -- Count confirmed reservations per (date, time)
    LEFT JOIN LATERAL (
        SELECT COUNT(*)::INTEGER AS cnt
        FROM appointment_reservations ar
        WHERE ar.entity_location_id = p_entity_location_id
        AND ar.appointment_date = ts.dt
        AND ar.appointment_time = ts.t_slot
        AND ar.status IN ('scheduled', 'confirmed')
    ) res ON TRUE
    -- Count active holds per (date, time)
    LEFT JOIN LATERAL (
        SELECT COUNT(*)::INTEGER AS cnt
        FROM appointment_holds ah
        WHERE ah.entity_location_id = p_entity_location_id
        AND ah.appointment_date = ts.dt
        AND ah.appointment_time = ts.t_slot
        AND ah.status = 'held'
        AND ah.expires_at > NOW()
    ) holds ON TRUE
    WHERE (ts.max_appointments_per_slot - COALESCE(res.cnt, 0) - COALESCE(holds.cnt, 0)) > 0
    ORDER BY ts.dt, ts.t_slot
    LIMIT p_limit;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.get_entity_locations(p_entity_code character varying)
 RETURNS TABLE(id uuid, city character varying, region character varying, location_name character varying, location_address text, phone character varying, is_main_office boolean)
 LANGUAGE plpgsql
AS $function$
BEGIN
    RETURN QUERY
    SELECT
        el.id,
        el.city,
        el.region,
        el.location_name,
        el.location_address,
        el.phone,
        el.is_main_office
    FROM entity_locations el
    WHERE el.entity_code = p_entity_code
      AND el.is_active = TRUE
    ORDER BY el.is_main_office DESC, el.city;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.get_entity_translation(p_entity_type translatable_entity_type, p_entity_code character varying, p_field_name character varying DEFAULT 'name'::character varying, p_language character varying DEFAULT 'fr'::character varying)
 RETURNS text
 LANGUAGE sql
 STABLE
AS $function$
    SELECT translation_text
    FROM entity_translations
    WHERE entity_type = p_entity_type
      AND entity_code = p_entity_code
      AND field_name = p_field_name
      AND language_code = p_language;
$function$
;

CREATE OR REPLACE FUNCTION public.get_entity_workflows(p_entity_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
AS $function$
DECLARE
    v_entity RECORD;
    v_workflows JSONB;
BEGIN
    -- Get the entity
    SELECT id, code, workflow_codes, parent_entity_id, entity_type
    INTO v_entity
    FROM entities
    WHERE id = p_entity_id AND is_active = true;

    IF NOT FOUND THEN
        RETURN '[]'::jsonb;
    END IF;

    -- Check if entity has workflow_codes defined
    IF v_entity.workflow_codes IS NOT NULL AND jsonb_array_length(v_entity.workflow_codes) > 0 THEN
        RETURN v_entity.workflow_codes;
    END IF;

    -- If department, try to inherit from parent
    IF v_entity.entity_type = 'department' AND v_entity.parent_entity_id IS NOT NULL THEN
        SELECT workflow_codes INTO v_workflows
        FROM entities
        WHERE id = v_entity.parent_entity_id AND is_active = true;

        IF v_workflows IS NOT NULL AND jsonb_array_length(v_workflows) > 0 THEN
            RETURN v_workflows;
        END IF;
    END IF;

    -- Fallback: get all workflows matching entity_code
    SELECT jsonb_agg(code ORDER BY display_order)
    INTO v_workflows
    FROM workflows
    WHERE entity_code = v_entity.code AND is_active = true;

    RETURN COALESCE(v_workflows, '[]'::jsonb);
END;
$function$
;

CREATE OR REPLACE FUNCTION public.get_next_available_slot(p_entity_code character varying, p_target_date date, p_workflow_code character varying DEFAULT NULL::character varying)
 RETURNS TABLE(slot_date date, slot_time time without time zone, location_name character varying, location_address text)
 LANGUAGE plpgsql
AS $function$
DECLARE
    v_current_date DATE := p_target_date;
    v_max_search_days INTEGER := 60;  -- Search up to 60 days ahead
    v_day_count INTEGER := 0;
BEGIN
    WHILE v_day_count < v_max_search_days LOOP
        -- Skip blocked dates
        IF NOT is_appointment_date_blocked(p_entity_code, v_current_date) THEN
            -- Check for available slot on this day
            RETURN QUERY
            SELECT
                v_current_date as slot_date,
                asc_config.start_time as slot_time,
                asc_config.location_name,
                asc_config.location_address
            FROM appointment_slot_configs asc_config
            LEFT JOIN (
                SELECT appointment_time, COUNT(*) as cnt
                FROM appointment_reservations
                WHERE entity_code = p_entity_code
                AND appointment_date = v_current_date
                AND status IN ('scheduled', 'confirmed')
                GROUP BY appointment_time
            ) res ON asc_config.start_time = res.appointment_time
            WHERE asc_config.entity_code = p_entity_code
            AND asc_config.is_active = TRUE
            AND asc_config.day_of_week = EXTRACT(DOW FROM v_current_date)::INTEGER
            AND COALESCE(res.cnt, 0) < asc_config.max_appointments_per_slot
            ORDER BY asc_config.start_time
            LIMIT 1;

            -- If we found a slot, exit
            IF FOUND THEN
                RETURN;
            END IF;
        END IF;

        v_current_date := v_current_date + INTERVAL '1 day';
        v_day_count := v_day_count + 1;
    END LOOP;

    -- No slot found within search range
    RETURN;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.get_pending_notification_retries(p_limit integer DEFAULT 100)
 RETURNS TABLE(id uuid, channel character varying, template_code character varying, recipient_email character varying, recipient_phone character varying, template_variables jsonb, retry_count integer)
 LANGUAGE plpgsql
AS $function$
BEGIN
    RETURN QUERY
    SELECT
        nl.id,
        nl.channel,
        nl.template_code,
        nl.recipient_email,
        nl.recipient_phone,
        nl.template_variables,
        nl.retry_count
    FROM notification_log nl
    WHERE nl.status = 'failed'
      AND nl.retry_count < 3
      AND nl.next_retry_at <= NOW()
    ORDER BY nl.next_retry_at
    LIMIT p_limit;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.get_pending_verifications(p_limit integer DEFAULT 10)
 RETURNS TABLE(queue_id uuid, service_request_id uuid, retry_count integer, partial_results jsonb)
 LANGUAGE plpgsql
AS $function$
BEGIN
    RETURN QUERY
    SELECT
        vq.id AS queue_id,
        vq.service_request_id,
        vq.retry_count,
        vq.partial_results
    FROM verification_queue vq
    WHERE vq.status IN ('pending', 'failed')
      AND vq.retry_count < vq.max_retries
      AND vq.next_retry_at <= NOW()
    ORDER BY vq.next_retry_at ASC
    LIMIT p_limit
    FOR UPDATE SKIP LOCKED;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.get_rule_value(p_rule_code character varying)
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
DECLARE
    v_value JSONB;
BEGIN
    SELECT rule_value INTO v_value
    FROM system_rules
    WHERE rule_code = p_rule_code
      AND is_active = TRUE
      AND effective_from <= CURRENT_DATE
      AND (effective_until IS NULL OR effective_until >= CURRENT_DATE)
    ORDER BY effective_from DESC
    LIMIT 1;

    RETURN v_value;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.get_translation(p_category character varying, p_key_code character varying, p_lang character varying DEFAULT 'es'::character varying, p_context character varying DEFAULT NULL::character varying)
 RETURNS text
 LANGUAGE plpgsql
 STABLE
AS $function$
DECLARE
    v_translation TEXT;
BEGIN
    -- Essayer la langue demandée
    EXECUTE format('SELECT %I FROM translations WHERE category = $1 AND key_code = $2 AND ($3 IS NULL OR context = $3)',
                   p_lang)
    INTO v_translation
    USING p_category, p_key_code, p_context;

    -- Fallback ES si pas trouvé
    IF v_translation IS NULL THEN
        SELECT es INTO v_translation
        FROM translations
        WHERE category = p_category
          AND key_code = p_key_code
          AND (p_context IS NULL OR context = p_context);
    END IF;

    -- Fallback ultime: retourner key_code
    RETURN COALESCE(v_translation, p_key_code);
END;
$function$
;

CREATE OR REPLACE FUNCTION public.get_translation_unified(p_category character varying, p_key character varying, p_language character varying DEFAULT 'es'::character varying)
 RETURNS text
 LANGUAGE plpgsql
 STABLE
AS $function$
DECLARE
    v_translation TEXT;
    v_entity_type translatable_entity_type;
BEGIN
    -- Cas 1: Si category = 'enum' → Lire depuis translations
    IF p_category = 'enum' OR p_category LIKE 'ui.%' OR p_category LIKE 'form.%' OR p_category LIKE 'system.%' THEN
        -- Utiliser la fonction get_translation() de la table translations
        SELECT get_translation(p_category, p_key, p_language) INTO v_translation;
        RETURN v_translation;
    END IF;

    -- Cas 2: Si category = entity type → Lire depuis entity_translations
    BEGIN
        v_entity_type := p_category::translatable_entity_type;

        SELECT translation_text INTO v_translation
        FROM entity_translations
        WHERE entity_type = v_entity_type
          AND entity_code = p_key
          AND language_code = p_language
          AND field_name = 'name';  -- Par défaut, retourner le nom

        RETURN v_translation;
    EXCEPTION
        WHEN invalid_text_representation THEN
            -- p_category n'est pas un translatable_entity_type valide
            RETURN NULL;
    END;

    -- Fallback
    RETURN NULL;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.get_translations(p_entity_type translatable_entity_type, p_entity_code character varying, p_language_code character varying)
 RETURNS jsonb
 LANGUAGE sql
 STABLE
AS $function$
    SELECT jsonb_object_agg(field_name, translation_text)
    FROM entity_translations
    WHERE entity_type = p_entity_type
    AND entity_code = p_entity_code
    AND language_code = p_language_code;
$function$
;

CREATE OR REPLACE FUNCTION public.get_workflow_required_documents(p_workflow_code character varying, p_context jsonb DEFAULT '{}'::jsonb)
 RETURNS TABLE(document_code character varying, document_name_es character varying, is_required boolean, instructions_es text, condition_type document_condition_type_enum, extraction_schema_key character varying, display_order integer)
 LANGUAGE plpgsql
 STABLE
AS $function$
BEGIN
    RETURN QUERY
    SELECT
        wdr.document_code,
        wdr.document_name_es,
        wdr.is_required,
        wdr.instructions_es,
        wdr.condition_type,
        wdr.extraction_schema_key,
        wdr.display_order
    FROM workflow_document_requirements wdr
    WHERE wdr.workflow_code = p_workflow_code
      AND wdr.is_active = TRUE
      AND evaluate_document_condition(wdr.condition_type, wdr.condition_value, p_context)
    ORDER BY wdr.display_order;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.get_workflow_tariff_total(p_workflow_code character varying, p_solicitud_type character varying DEFAULT 'expedicion'::character varying)
 RETURNS TABLE(tariff_type character varying, base_amount numeric, percentage_rate numeric, supplements jsonb, supplements_total numeric, total_amount numeric, currency character varying)
 LANGUAGE plpgsql
 STABLE
AS $function$
DECLARE
    v_tariff_type VARCHAR(20);
    v_base NUMERIC(12,2);
    v_percentage NUMERIC(5,2);
    v_supplements JSONB;
    v_supplements_total NUMERIC(12,2);
BEGIN
    -- 1. Récupérer le tarif de base avec type
    SELECT wt.tariff_type, wt.amount, wt.percentage_rate
    INTO v_tariff_type, v_base, v_percentage
    FROM workflow_tariffs wt
    WHERE wt.workflow_code = p_workflow_code
      AND wt.solicitud_type = p_solicitud_type
      AND wt.is_active = TRUE
      AND wt.effective_from <= CURRENT_DATE
      AND (wt.effective_to IS NULL OR wt.effective_to > CURRENT_DATE)
    ORDER BY wt.effective_from DESC
    LIMIT 1;

    v_tariff_type := COALESCE(v_tariff_type, 'FIXED');
    v_base := COALESCE(v_base, 0);

    -- 2. Récupérer les suppléments configurés
    SELECT
        jsonb_agg(
            jsonb_build_object(
                'code', ts.code,
                'name', ts.name_es,
                'unit_price', ts.amount,
                'quantity', wsc.quantity_per_request,
                'subtotal', ts.amount * wsc.quantity_per_request
            )
        ),
        COALESCE(SUM(ts.amount * wsc.quantity_per_request), 0)
    INTO v_supplements, v_supplements_total
    FROM workflow_supplement_config wsc
    JOIN tariff_supplements ts ON ts.code = wsc.supplement_code
    WHERE wsc.workflow_code = p_workflow_code
      AND wsc.is_active = TRUE
      AND ts.is_active = TRUE
      AND ts.effective_from <= CURRENT_DATE
      AND (ts.effective_to IS NULL OR ts.effective_to > CURRENT_DATE);

    v_supplements := COALESCE(v_supplements, '[]'::JSONB);
    v_supplements_total := COALESCE(v_supplements_total, 0);

    -- 3. Retourner le résultat
    RETURN QUERY SELECT
        v_tariff_type AS tariff_type,
        v_base AS base_amount,
        v_percentage AS percentage_rate,
        v_supplements AS supplements,
        v_supplements_total AS supplements_total,
        (v_base + v_supplements_total) AS total_amount,
        'XAF'::VARCHAR(3) AS currency;
END;
$function$
;

