CREATE OR REPLACE FUNCTION public.is_appointment_date_blocked(p_entity_code character varying, p_date date)
 RETURNS boolean
 LANGUAGE plpgsql
AS $function$
DECLARE
    v_is_blocked BOOLEAN;
BEGIN
    SELECT EXISTS (
        SELECT 1 FROM appointment_blocked_dates
        WHERE (entity_code IS NULL OR entity_code = p_entity_code)
        AND (
            blocked_date = p_date
            OR (is_recurring AND EXTRACT(MONTH FROM blocked_date) = EXTRACT(MONTH FROM p_date)
                AND EXTRACT(DAY FROM blocked_date) = EXTRACT(DAY FROM p_date))
        )
    ) INTO v_is_blocked;

    RETURN v_is_blocked;
END;
$function$
;

