CREATE OR REPLACE FUNCTION public.log_gemini_processing(p_service_request_id uuid, p_document_id uuid, p_user_id uuid, p_document_code character varying, p_mime_type character varying, p_file_size integer, p_processor character varying, p_gemini_model character varying, p_document_type character varying, p_document_category character varying, p_classification_confidence numeric, p_extraction_result jsonb, p_extraction_confidence numeric, p_fields_extracted integer, p_fields_missing integer, p_risk_score numeric, p_risk_level character varying, p_risk_factors jsonb, p_coherence_valid boolean, p_recommendation character varying, p_is_match boolean, p_processing_time_ms integer, p_gemini_latency_ms integer, p_used_fallback boolean, p_fallback_reason character varying, p_has_error boolean, p_error_type character varying, p_error_message text, p_workflow_code character varying, p_input_tokens integer DEFAULT NULL::integer, p_output_tokens integer DEFAULT NULL::integer)
 RETURNS uuid
 LANGUAGE plpgsql
AS $function$
DECLARE
    v_log_id UUID;
BEGIN
    INSERT INTO gemini_processing_logs (
        service_request_id, document_id, user_id,
        document_code, mime_type, file_size_bytes,
        processor, gemini_model,
        document_type_detected, document_category,
        classification_confidence, extraction_result, extraction_confidence,
        fields_extracted, fields_missing,
        risk_score, risk_level, risk_factors, coherence_valid,
        recommendation, is_match,
        processing_time_ms, gemini_latency_ms,
        used_fallback, fallback_reason,
        has_error, error_type, error_message,
        workflow_code,
        input_tokens, output_tokens,
        total_tokens
    ) VALUES (
        p_service_request_id, p_document_id, p_user_id,
        p_document_code, p_mime_type, p_file_size,
        p_processor, p_gemini_model,
        p_document_type, p_document_category,
        p_classification_confidence, p_extraction_result, p_extraction_confidence,
        p_fields_extracted, p_fields_missing,
        p_risk_score, p_risk_level, p_risk_factors, p_coherence_valid,
        p_recommendation, p_is_match,
        p_processing_time_ms, p_gemini_latency_ms,
        p_used_fallback, p_fallback_reason,
        p_has_error, p_error_type, p_error_message,
        p_workflow_code,
        p_input_tokens, p_output_tokens,
        COALESCE(p_input_tokens, 0) + COALESCE(p_output_tokens, 0)
    )
    RETURNING id INTO v_log_id;

    RETURN v_log_id;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.log_notification(p_service_request_id uuid, p_user_id uuid, p_channel character varying, p_template_code character varying, p_recipient character varying, p_subject character varying, p_content_preview character varying, p_trigger_event character varying, p_template_variables jsonb DEFAULT '{}'::jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
AS $function$
DECLARE
    v_log_id UUID;
BEGIN
    INSERT INTO notification_log (
        service_request_id,
