CREATE OR REPLACE FUNCTION public.notify_rbac_change()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
    payload TEXT;
BEGIN
    IF TG_TABLE_NAME = 'role_permissions' THEN
        -- Role permission changed â†’ invalidate all users with that role
        payload := json_build_object(
            'table', TG_TABLE_NAME,
            'op', TG_OP,
            'role_id', COALESCE(NEW.role_id, OLD.role_id)
        )::text;
    ELSIF TG_TABLE_NAME = 'user_permissions' THEN
        -- User permission changed â†’ invalidate that user
        payload := json_build_object(
            'table', TG_TABLE_NAME,
            'op', TG_OP,
            'user_id', COALESCE(NEW.user_id, OLD.user_id)
        )::text;
    ELSIF TG_TABLE_NAME = 'roles' THEN
        -- Role changed â†’ invalidate users with that role
        payload := json_build_object(
            'table', TG_TABLE_NAME,
            'op', TG_OP,
            'role_id', COALESCE(NEW.id, OLD.id)
        )::text;
    ELSIF TG_TABLE_NAME = 'users' THEN
        -- User role_id changed â†’ invalidate that user
        IF TG_OP = 'UPDATE' AND OLD.role_id IS DISTINCT FROM NEW.role_id THEN
            payload := json_build_object(
                'table', TG_TABLE_NAME,
                'op', 'ROLE_CHANGE',
                'user_id', NEW.id,
                'old_role_id', OLD.role_id,
                'new_role_id', NEW.role_id
            )::text;
        ELSE
            RETURN COALESCE(NEW, OLD);
        END IF;
    END IF;

    -- NOTIFY channel 'rbac_changes' with JSON payload
    PERFORM pg_notify('rbac_changes', payload);

    RETURN COALESCE(NEW, OLD);
END;
$function$
;

CREATE OR REPLACE FUNCTION public.prepare_service_text_for_embedding(p_service_id integer)
 RETURNS text
 LANGUAGE plpgsql
AS $function$
DECLARE
    v_text TEXT;
    v_keywords TEXT;
    v_category TEXT;
    v_sector TEXT;
    v_ministry TEXT;
BEGIN
    -- Build comprehensive text combining all relevant fields
    SELECT
        format('Servicio: %s | Código: %s | Descripción: %s | Categoría: %s | Sector: %s | Ministerio: %s | Palabras clave: %s',
            fs.name_es,
            fs.service_code,
            COALESCE(fs.description_es, ''),
            COALESCE(c.name_es, ''),
            COALESCE(s.name_es, ''),
            COALESCE(m.name_es, ''),
            COALESCE(
                (
                    SELECT string_agg(sk.keyword, ', ' ORDER BY sk.weight DESC)
                    FROM service_keywords sk
                    WHERE sk.fiscal_service_id = fs.id
                      AND sk.language_code = 'es'
                ),
                ''
            )
        )
    INTO v_text
    FROM fiscal_services fs
    LEFT JOIN categories c ON fs.category_id = c.id
    LEFT JOIN sectors s ON c.sector_id = s.id
    LEFT JOIN ministries m ON c.ministry_id = m.id
    WHERE fs.id = p_service_id;

    RETURN v_text;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.process_verificacion_funcionario(p_verificacion_id uuid, p_agent_id uuid, p_action character varying, p_matricula_existe boolean DEFAULT false, p_nombre_coincide boolean DEFAULT false, p_dip_coincide boolean DEFAULT false, p_rejection_reason text DEFAULT NULL::text, p_notes text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
DECLARE
    v_verificacion RECORD;
    v_user_id UUID;
    v_matricula VARCHAR(50);
    v_verification_data JSONB;
BEGIN
    SELECT * INTO v_verificacion
    FROM verificacion_funcionario
    WHERE id = p_verificacion_id;

    IF NOT FOUND THEN
        RETURN jsonb_build_object('success', false, 'error', 'Verificacion no encontrada');
    END IF;

    IF v_verificacion.status != 'pendiente' THEN
        RETURN jsonb_build_object('success', false, 'error', 'Verificacion ya procesada');
    END IF;

    v_user_id := v_verificacion.user_id;
    v_matricula := v_verificacion.matricula;
    v_verification_data := v_verificacion.verification_data;

    IF p_action = 'aprobar' THEN
        IF NOT p_matricula_existe OR NOT p_nombre_coincide THEN
            RETURN jsonb_build_object(
                'success', false,
                'error', 'Debe verificar matricula y nombre para aprobar'
            );
        END IF;

        UPDATE verificacion_funcionario
        SET status = 'aprobado',
            processed_by = p_agent_id,
            processed_at = NOW(),
            verificacion_matricula_existe = p_matricula_existe,
            verificacion_nombre_coincide = p_nombre_coincide,
            verificacion_dip_coincide = p_dip_coincide,
            notes = p_notes,
            verification_data = v_verification_data || jsonb_build_object(
                'procesamiento_agente', jsonb_build_object(
                    'agent_id', p_agent_id,
                    'action', 'aprobar',
                    'processed_at', NOW(),
                    'checklist', jsonb_build_object(
                        'matricula_existe', p_matricula_existe,
                        'nombre_coincide', p_nombre_coincide,
                        'dip_coincide', p_dip_coincide
                    ),
                    'notes', p_notes
                )
            )
        WHERE id = p_verificacion_id;

        UPDATE users
        SET matricula_funcionario = v_matricula,
            funcionario_verified_at = NOW(),
            funcionario_verified_by = p_agent_id
        WHERE id = v_user_id;

        RETURN jsonb_build_object(
            'success', true,
            'status', 'aprobado',
            'user_id', v_user_id,
            'matricula', v_matricula,
            'message', 'Usuario verificado como funcionario.'
        );

    ELSIF p_action = 'rechazar' THEN
        IF p_rejection_reason IS NULL OR p_rejection_reason = '' THEN
            RETURN jsonb_build_object(
                'success', false,
                'error', 'Debe proporcionar motivo de rechazo'
            );
        END IF;

        UPDATE verificacion_funcionario
        SET status = 'rechazado',
            processed_by = p_agent_id,
            processed_at = NOW(),
            verificacion_matricula_existe = p_matricula_existe,
            verificacion_nombre_coincide = p_nombre_coincide,
            verificacion_dip_coincide = p_dip_coincide,
            rejection_reason = p_rejection_reason,
            notes = p_notes,
            verification_data = v_verification_data || jsonb_build_object(
                'procesamiento_agente', jsonb_build_object(
                    'agent_id', p_agent_id,
                    'action', 'rechazar',
                    'processed_at', NOW(),
                    'rejection_reason', p_rejection_reason,
                    'notes', p_notes
                )
            )
        WHERE id = p_verificacion_id;

        RETURN jsonb_build_object(
            'success', true,
            'status', 'rechazado',
            'user_id', v_user_id,
            'reason', p_rejection_reason
        );

    ELSE
        RETURN jsonb_build_object('success', false, 'error', 'Accion invalida');
    END IF;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.queue_verification(p_request_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
AS $function$
DECLARE
    v_queue_id UUID;
BEGIN
    -- Insert into queue (or update if exists)
    INSERT INTO verification_queue (service_request_id, status, retry_count, next_retry_at)
    VALUES (p_request_id, 'pending', 0, NOW())
    ON CONFLICT (service_request_id) DO UPDATE SET
        status = 'pending',
        retry_count = 0,
        next_retry_at = NOW(),
        error_message = NULL,
        started_at = NULL,
        completed_at = NULL
    RETURNING id INTO v_queue_id;

    -- Update service_request status
    UPDATE service_requests
    SET verification_status = 'in_progress',
        updated_at = NOW()
    WHERE id = p_request_id;

    RETURN v_queue_id;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.recompute_effective_configs(p_bundle_id uuid DEFAULT NULL::uuid)
 RETURNS integer
 LANGUAGE plpgsql
AS $function$
    DECLARE
        v_affected INTEGER := 0;
    BEGIN
        UPDATE service_bundle_items sbi SET
            effective_penalty = (
                SELECT fcr.config FROM fiscal_config_rules fcr
                WHERE fcr.config_type = 'penalty'
                  AND fcr.is_enabled = true
                  AND (fcr.bundle_id = sbi.bundle_id OR fcr.bundle_id IS NULL)
                  AND (fcr.fee_type = sbi.fee_type OR fcr.fee_type IS NULL)
                  AND (fcr.ministry_id = sbi.ministry_id OR fcr.ministry_id IS NULL)
                  AND (fcr.item_id = sbi.id OR fcr.item_id IS NULL)
                  AND fcr.effective_from <= CURRENT_DATE
                  AND (fcr.effective_to IS NULL OR fcr.effective_to >= CURRENT_DATE)
                ORDER BY fcr.specificity DESC
                LIMIT 1
            ),
            effective_deadline = (
                SELECT fcr.config FROM fiscal_config_rules fcr
                WHERE fcr.config_type = 'deadline'
                  AND fcr.is_enabled = true
                  AND (fcr.bundle_id = sbi.bundle_id OR fcr.bundle_id IS NULL)
                  AND (fcr.fee_type = sbi.fee_type OR fcr.fee_type IS NULL)
                  AND (fcr.ministry_id = sbi.ministry_id OR fcr.ministry_id IS NULL)
                  AND (fcr.item_id = sbi.id OR fcr.item_id IS NULL)
                  AND fcr.effective_from <= CURRENT_DATE
                  AND (fcr.effective_to IS NULL OR fcr.effective_to >= CURRENT_DATE)
                ORDER BY fcr.specificity DESC
                LIMIT 1
            ),
            config_resolved_at = NOW()
        WHERE (p_bundle_id IS NULL OR sbi.bundle_id = p_bundle_id)
          AND sbi.is_active = true;

        GET DIAGNOSTICS v_affected = ROW_COUNT;
        RETURN v_affected;
    END;
    $function$
;

