CREATE OR REPLACE FUNCTION public.search_fiscal_services_semantic(p_query_embedding vector, p_limit integer DEFAULT 10, p_similarity_threshold double precision DEFAULT 0.7, p_category_id integer DEFAULT NULL::integer, p_service_type service_type_enum DEFAULT NULL::service_type_enum)
 RETURNS TABLE(service_id integer, service_code character varying, name_es character varying, description_es text, category_name character varying, sector_name character varying, ministry_name character varying, similarity_score double precision, tasa_expedicion numeric, processing_time_days integer)
 LANGUAGE plpgsql
AS $function$
BEGIN
    RETURN QUERY
    SELECT
        fs.id,
        fs.service_code,
        fs.name_es,
        fs.description_es,
        c.name_es as category_name,
        s.name_es as sector_name,
        m.name_es as ministry_name,
        (1 - (fs.embedding <-> p_query_embedding))::FLOAT as similarity_score,
        fs.tasa_expedicion,
        fs.processing_time_days
    FROM fiscal_services fs
    LEFT JOIN categories c ON fs.category_id = c.id
    LEFT JOIN sectors s ON c.sector_id = s.id
    LEFT JOIN ministries m ON c.ministry_id = m.id
    WHERE fs.status = 'active'
      AND fs.embedding IS NOT NULL
      AND (1 - (fs.embedding <-> p_query_embedding)) >= p_similarity_threshold
      AND (p_category_id IS NULL OR fs.category_id = p_category_id)
      AND (p_service_type IS NULL OR fs.service_type = p_service_type)
    ORDER BY fs.embedding <-> p_query_embedding
    LIMIT p_limit;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.search_legislacion_documents_semantic(query_embedding vector, _limit integer DEFAULT 5, similarity_threshold double precision DEFAULT 0.7)
 RETURNS TABLE(id uuid, document_name text, page_number integer, chunk_id text, content text, similarity double precision)
 LANGUAGE plpgsql
AS $function$
BEGIN
    RETURN QUERY
    SELECT
        ld.id,
        ld.document_name,
        ld.page_number,
        ld.chunk_id,
        ld.content,
        (ld.embedding <=> query_embedding) AS similarity
    FROM
        legislacion_documents ld
    WHERE
        ld.embedding IS NOT NULL
        AND (ld.embedding <=> query_embedding) < (1 - similarity_threshold) -- Distance is 1 - similarity for L2
    ORDER BY
        similarity
    LIMIT _limit;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.set_limit(real)
 RETURNS real
 LANGUAGE c
 STRICT
AS '$libdir/pg_trgm', $function$set_limit$function$
;

CREATE OR REPLACE FUNCTION public.set_updated_at_company_creation_drafts()
 RETURNS trigger
