CREATE OR REPLACE FUNCTION public.update_capacity_percentage()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
    -- Calculate capacity percentage
    IF NEW.max_concurrent_assignments > 0 THEN
        NEW.capacity_percentage = (NEW.current_assignments::DECIMAL / NEW.max_concurrent_assignments) * 100.0;
    ELSE
        NEW.capacity_percentage = 0.0;
    END IF;

    -- Auto-update workload_status based on capacity and availability
    IF NEW.availability != 'available' THEN
        NEW.workload_status = 'unavailable';
    ELSIF NEW.capacity_percentage >= 90 THEN
        NEW.workload_status = 'overloaded';
    ELSIF NEW.capacity_percentage >= 70 THEN
        NEW.workload_status = 'busy';
    ELSIF NEW.capacity_percentage >= 30 THEN
        NEW.workload_status = 'normal';
    ELSE
        NEW.workload_status = 'available';
    END IF;

    -- Update timestamp
    NEW.last_updated_at = NOW();

    RETURN NEW;
END;
$function$
;

