CREATE OR REPLACE FUNCTION public.upsert_verified_identifier(p_blind_index bytea, p_encrypted_value bytea, p_identifier_type identifier_type_enum, p_source verification_source_enum, p_user_id uuid DEFAULT NULL::uuid, p_verified_by uuid DEFAULT NULL::uuid, p_expires_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_encrypted_metadata bytea DEFAULT NULL::bytea, p_verification_request_id uuid DEFAULT NULL::uuid)
 RETURNS TABLE(id uuid, is_new boolean)
 LANGUAGE plpgsql
AS $function$
DECLARE
    v_id UUID;
    v_is_new BOOLEAN;
BEGIN
    INSERT INTO verified_identifiers (
        blind_index,
        encrypted_value,
        identifier_type,
        source,
        user_id,
        verified_by,
        expires_at,
        encrypted_metadata,
        verification_request_id
    ) VALUES (
        p_blind_index,
        p_encrypted_value,
        p_identifier_type,
        p_source,
        p_user_id,
        p_verified_by,
        p_expires_at,
        p_encrypted_metadata,
        p_verification_request_id
    )
    ON CONFLICT (blind_index, identifier_type)
    DO UPDATE SET
        verified_at = NOW(),
        source = EXCLUDED.source,
        user_id = COALESCE(EXCLUDED.user_id, verified_identifiers.user_id),
        verified_by = EXCLUDED.verified_by,
        expires_at = EXCLUDED.expires_at,
        encrypted_metadata = COALESCE(EXCLUDED.encrypted_metadata, verified_identifiers.encrypted_metadata),
        verification_request_id = COALESCE(EXCLUDED.verification_request_id, verified_identifiers.verification_request_id),
        is_active = TRUE,
        updated_at = NOW()
    RETURNING verified_identifiers.id, (xmax = 0)
    INTO v_id, v_is_new;

    RETURN QUERY SELECT v_id, v_is_new;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.validate_agent_assignment()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
    v_entity_ministry_id INTEGER;
    v_entity_has_ministry BOOLEAN;
BEGIN
    v_entity_has_ministry := FALSE;

    -- If agent is assigned to an entity, get the entity's ministry (if any)
    IF NEW.entity_id IS NOT NULL THEN
        SELECT e.ministry_id INTO v_entity_ministry_id
        FROM entities e
        WHERE e.id = NEW.entity_id;

        v_entity_has_ministry := v_entity_ministry_id IS NOT NULL;

        -- Auto-populate ministry_id from entity's parent ministry
        IF v_entity_has_ministry THEN
            IF NEW.ministry_id IS NULL THEN
                -- Inherit ministry from entity
                NEW.ministry_id := v_entity_ministry_id;
            ELSIF NEW.ministry_id != v_entity_ministry_id THEN
                -- If ministry_id is explicitly set, it must match entity's ministry
                RAISE EXCEPTION 'Agent ministry_id (%) must match entity ministry_id (%)',
                    NEW.ministry_id, v_entity_ministry_id;
            END IF;
        END IF;
    END IF;

    -- Validate based on agent_type
    IF NEW.agent_type = 'entity_agent' THEN
        -- entity_agent MUST have an entity_id
        IF NEW.entity_id IS NULL THEN
            RAISE EXCEPTION 'entity_agent must have entity_id set';
        END IF;
        -- REMOVED: The constraint preventing entity_agent on entities with ministry
        -- entity_agents CAN work for entities that have a parent ministry
        -- The ministry_id is inherited automatically for filtering purposes

    ELSIF NEW.agent_type = 'ministry_agent' THEN
        -- ministry_agent works for a ministry, either:
        -- 1. Directly (ministry_id set, no entity_id), OR
        -- 2. Via an entity that belongs to a ministry (entity_id set, ministry inherited)
        IF NEW.ministry_id IS NULL THEN
            RAISE EXCEPTION 'ministry_agent must be linked to a ministry (directly or via entity)';
        END IF;
    END IF;

    RETURN NEW;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.validate_entity_workflow_codes()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
    v_code TEXT;
    v_invalid_codes TEXT[];
BEGIN
    -- Skip if workflow_codes is NULL or empty
    IF NEW.workflow_codes IS NULL OR jsonb_array_length(NEW.workflow_codes) = 0 THEN
        RETURN NEW;
    END IF;

    -- Check each workflow code exists in workflows table OR is a valid WorkflowCode enum
    -- We check against workflows table (which contains both predefined and generic workflows)
    SELECT array_agg(code)
    INTO v_invalid_codes
    FROM (
        SELECT jsonb_array_elements_text(NEW.workflow_codes) as code
    ) codes
    WHERE code NOT IN (SELECT w.code FROM workflows w WHERE w.is_active = true);

    IF array_length(v_invalid_codes, 1) > 0 THEN
        RAISE EXCEPTION 'Invalid workflow codes: %. Codes must exist in workflows table.',
            array_to_string(v_invalid_codes, ', ');
    END IF;

    RETURN NEW;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.validate_fiscal_service_montants()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
    tolerance_pct NUMERIC := 0.01; -- 1% tolerance
BEGIN
    -- If both montants exist, check coherence
    IF NEW.montant_chiffre IS NOT NULL AND NEW.montant_lettre IS NOT NULL THEN
        -- Store warning in review_notes if incoherent
        -- Note: This is a soft validation, doesn't block insert
        -- Actual montant parsing from text would be in application layer
        IF NEW.review_notes IS NULL THEN
            NEW.review_notes := '';
        END IF;
    END IF;

    RETURN NEW;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.validate_menu_config(config jsonb)
 RETURNS boolean
 LANGUAGE plpgsql
AS $function$
BEGIN
    IF config IS NULL THEN
        RETURN TRUE;
    END IF;

    IF NOT (config ? 'version') THEN
        RAISE EXCEPTION 'menu_config must have "version" field';
    END IF;

    IF NOT (config ? 'menus') THEN
        RAISE EXCEPTION 'menu_config must have "menus" array';
    END IF;

    IF jsonb_typeof(config->'menus') != 'array' THEN
        RAISE EXCEPTION 'menu_config.menus must be an array';
    END IF;

    RETURN TRUE;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.validate_workflow_documents(p_workflow_code character varying, p_uploaded_codes text[], p_context jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
AS $function$
DECLARE
    v_required_codes TEXT[];
    v_missing_codes TEXT[];
    v_missing_docs JSONB;
BEGIN
    -- Récupérer les codes requis
    SELECT ARRAY_AGG(document_code)
    INTO v_required_codes
    FROM get_workflow_required_documents(p_workflow_code, p_context)
    WHERE is_required = TRUE;

    IF v_required_codes IS NULL THEN
        RETURN jsonb_build_object('valid', TRUE, 'missing', '[]'::JSONB);
    END IF;

    -- Trouver les manquants
    SELECT ARRAY_AGG(code)
    INTO v_missing_codes
    FROM UNNEST(v_required_codes) AS code
    WHERE code != ALL(p_uploaded_codes);

    IF v_missing_codes IS NULL OR ARRAY_LENGTH(v_missing_codes, 1) = 0 THEN
        RETURN jsonb_build_object('valid', TRUE, 'missing', '[]'::JSONB);
    END IF;

    -- Construire la liste des manquants
    SELECT jsonb_agg(
        jsonb_build_object(
            'code', wdr.document_code,
            'name_es', wdr.document_name_es
        )
    )
    INTO v_missing_docs
    FROM workflow_document_requirements wdr
    WHERE wdr.workflow_code = p_workflow_code
      AND wdr.document_code = ANY(v_missing_codes);

    RETURN jsonb_build_object(
        'valid', FALSE,
        'missing', COALESCE(v_missing_docs, '[]'::JSONB)
    );
END;
$function$
;

