-- ---------- 13. Views ----------
CREATE OR REPLACE VIEW "public"."v_active_assignments" AS
 SELECT a.id AS assignment_id,
    a.item_id,
    a.item_type,
    a.agent_profile_id,
    ap.user_id AS agent_user_id,
    u.full_name AS agent_name,
    u.email AS agent_email,
    ap.ministry_id,
    m.ministry_code,
    ap.entity_id,
    e.code AS entity_code,
    a.status AS assignment_status,
    a.priority_level,
    a.assigned_at,
    a.deadline,
    round(EXTRACT(epoch FROM now() - a.assigned_at) / 3600::numeric, 2) AS hours_since_assigned,
        CASE
            WHEN a.deadline IS NOT NULL AND now() > a.deadline THEN true
            ELSE false
        END AS is_overdue,
        CASE
            WHEN a.deadline IS NOT NULL THEN round(EXTRACT(epoch FROM a.deadline - now()) / 3600::numeric, 2)
            ELSE NULL::numeric
        END AS hours_until_deadline
   FROM assignments a
     JOIN agent_profiles ap ON a.agent_profile_id = ap.id
     JOIN users u ON ap.user_id = u.id
     LEFT JOIN ministries m ON ap.ministry_id = m.id
     LEFT JOIN entities e ON ap.entity_id = e.id
  WHERE a.status = ANY (ARRAY['assigned'::assignment_status_enum, 'in_progress'::assignment_status_enum, 'pending_review'::assignment_status_enum]);;

CREATE OR REPLACE VIEW "public"."v_active_declaration_assignments" AS
 SELECT a.id AS assignment_id,
    a.item_id AS declaration_id,
    a.item_type AS declaration_type,
    a.agent_profile_id,
    ap.user_id AS agent_user_id,
    u.full_name AS agent_name,
    u.email AS agent_email,
    ap.ministry_id,
    m.ministry_code,
    ap.entity_id,
    e.code AS entity_code,
    a.status AS assignment_status,
    a.priority_level AS assignment_priority,
    a.assigned_at,
    a.deadline AS assignment_deadline,
    td.declaration_number AS declaration_reference,
    td.status AS declaration_status,
    td.calculated_tax,
    td.net_tax_due,
    taxpayer.full_name AS taxpayer_name,
    round(EXTRACT(epoch FROM now() - a.assigned_at) / 3600::numeric, 2) AS hours_since_assigned,
        CASE
            WHEN a.deadline IS NOT NULL AND now() > a.deadline THEN true
            ELSE false
        END AS is_overdue,
        CASE
            WHEN a.deadline IS NOT NULL THEN round(EXTRACT(epoch FROM a.deadline - now()) / 3600::numeric, 2)
            ELSE NULL::numeric
        END AS hours_until_deadline
   FROM assignments a
     JOIN agent_profiles ap ON a.agent_profile_id = ap.id
     JOIN users u ON ap.user_id = u.id
     JOIN tax_declarations td ON a.item_id = td.id
     JOIN users taxpayer ON td.user_id = taxpayer.id
     LEFT JOIN ministries m ON ap.ministry_id = m.id
     LEFT JOIN entities e ON ap.entity_id = e.id
  WHERE a.status = ANY (ARRAY['assigned'::assignment_status_enum, 'in_progress'::assignment_status_enum, 'pending_review'::assignment_status_enum]);;

CREATE OR REPLACE VIEW "public"."v_active_service_request_assignments" AS
 SELECT a.id AS assignment_id,
    a.item_id AS service_request_id,
    a.item_type AS workflow_code,
    a.agent_profile_id,
    ap.user_id AS agent_user_id,
    u.full_name AS agent_name,
    u.email AS agent_email,
    ap.ministry_id,
    m.ministry_code,
    ap.entity_id,
    e.code AS entity_code,
    a.status AS assignment_status,
    a.priority_level AS assignment_priority,
    a.assigned_at,
    a.deadline AS assignment_deadline,
    sr.reference AS service_request_reference,
    sr.solicitud_type,
    sr.status AS service_request_status,
    sr.priority AS service_request_priority,
    sr.total_amount,
    sr.payment_status,
    sr.cita_date,
    sr.cita_time,
    req_user.full_name AS requester_name,
    round(EXTRACT(epoch FROM now() - a.assigned_at) / 3600::numeric, 2) AS hours_since_assigned,
        CASE
            WHEN a.deadline IS NOT NULL AND now() > a.deadline THEN true
            ELSE false
        END AS is_overdue,
        CASE
            WHEN a.deadline IS NOT NULL THEN round(EXTRACT(epoch FROM a.deadline - now()) / 3600::numeric, 2)
            ELSE NULL::numeric
        END AS hours_until_deadline
   FROM assignments a
     JOIN agent_profiles ap ON a.agent_profile_id = ap.id
     JOIN users u ON ap.user_id = u.id
     JOIN service_requests sr ON a.item_id = sr.id
     JOIN users req_user ON sr.user_id = req_user.id
     LEFT JOIN ministries m ON ap.ministry_id = m.id
     LEFT JOIN entities e ON ap.entity_id = e.id
  WHERE a.status = ANY (ARRAY['assigned'::assignment_status_enum, 'in_progress'::assignment_status_enum, 'pending_review'::assignment_status_enum]);;

CREATE OR REPLACE VIEW "public"."v_active_service_requests_enriched" AS
 SELECT sr.assignment_id,
    sr.service_request_id,
    sr.workflow_code,
    sr.service_request_reference,
    sr.solicitud_type,
    sr.service_request_status,
    sr.service_request_priority,
    sr.payment_status,
    sr.total_amount,
    sr.cita_date,
    sr.cita_time,
    sr.requester_name,
    sr.agent_profile_id,
    sr.agent_user_id,
    sr.agent_name,
    sr.agent_email,
    ap.agent_type,
    ap.is_supervisor,
    sr.entity_id,
    sr.entity_code,
    e.name AS entity_name,
    e.entity_type::text AS entity_type,
    e.workflow_codes ? 'BUNDLE_PAYMENT'::text AS is_oms,
    el.id AS entity_location_id,
    el.city AS location_city,
    el.region AS location_region,
    el.location_name,
    sr.ministry_id,
    sr.ministry_code,
    sr.assignment_status,
    sr.assignment_priority,
    sr.assigned_at,
    sr.assignment_deadline,
    sr.hours_since_assigned,
    sr.is_overdue,
    sr.hours_until_deadline,
        CASE
            WHEN sr.hours_since_assigned IS NULL THEN 'unknown'::text
            WHEN sr.hours_since_assigned < 24::numeric THEN '0-24h'::text
            WHEN sr.hours_since_assigned < 72::numeric THEN '24-72h'::text
            WHEN sr.hours_since_assigned < 168::numeric THEN '3-7d'::text
            WHEN sr.hours_since_assigned < 720::numeric THEN '7-30d'::text
            ELSE '30d+'::text
        END AS age_bucket
   FROM v_active_service_request_assignments sr
     LEFT JOIN agent_profiles ap ON ap.id = sr.agent_profile_id
     LEFT JOIN entities e ON e.id = sr.entity_id
     LEFT JOIN entity_locations el ON el.id = ap.entity_location_id;;

CREATE OR REPLACE VIEW "public"."v_agent_assignment_history" AS
 SELECT a.id AS assignment_id,
    a.item_id,
    a.item_type,
    a.agent_profile_id,
    ap.user_id AS agent_user_id,
    u.full_name AS agent_name,
    ap.ministry_id,
    m.ministry_code,
    ap.entity_id,
    e.code AS entity_code,
    a.status AS assignment_status,
    a.priority_level,
    a.assignment_method,
    a.assigned_at,
    a.completed_at,
    a.deadline,
    a.notes,
        CASE
            WHEN a.completed_at IS NOT NULL THEN round(EXTRACT(epoch FROM a.completed_at - a.assigned_at) / 3600::numeric, 2)
            ELSE NULL::numeric
        END AS total_hours
   FROM assignments a
     JOIN agent_profiles ap ON a.agent_profile_id = ap.id
     JOIN users u ON ap.user_id = u.id
     LEFT JOIN ministries m ON ap.ministry_id = m.id
     LEFT JOIN entities e ON ap.entity_id = e.id;;

CREATE OR REPLACE VIEW "public"."v_agent_entity_summary" AS
 SELECT e.id AS entity_id,
    e.code AS entity_code,
    e.name AS entity_name,
    e.entity_type,
    m.id AS ministry_id,
    m.ministry_code,
    m.name_es AS ministry_name,
    count(DISTINCT ap.id) AS total_agents,
    count(DISTINCT ap.id) FILTER (WHERE ap.is_active = true) AS active_agents,
    count(DISTINCT ap.id) FILTER (WHERE ap.is_active = true AND (aw.availability = 'available'::agent_availability_enum OR aw.availability IS NULL)) AS available_agents,
    count(DISTINCT ap.id) FILTER (WHERE ap.is_supervisor = true) AS supervisor_count,
    round(COALESCE(avg(aw.capacity_percentage), 0::numeric), 2) AS avg_capacity,
    COALESCE(sum(aw.max_concurrent_assignments - aw.current_assignments) FILTER (WHERE ap.is_active = true AND aw.availability = 'available'::agent_availability_enum), 0::bigint) AS available_capacity
   FROM entities e
     LEFT JOIN ministries m ON e.ministry_id = m.id
     LEFT JOIN agent_profiles ap ON e.id = ap.entity_id
     LEFT JOIN agent_workloads aw ON ap.id = aw.agent_profile_id
  GROUP BY e.id, e.code, e.name, e.entity_type, m.id, m.ministry_code, m.name_es;;

CREATE OR REPLACE VIEW "public"."v_agent_performance_rankings" AS
 SELECT ap.id AS agent_profile_id,
    ap.user_id,
    u.full_name,
    u.email,
    ap.ministry_id,
    m.ministry_code,
    m.name_es AS ministry_name,
    ap.entity_id,
    e.code AS entity_code,
    e.name AS entity_name,
    ap.agent_type,
    ap.is_supervisor,
    COALESCE(aps.current_month_processed, 0) AS current_month_processed,
    COALESCE(aps.current_month_approved, 0) AS current_month_approved,
    COALESCE(aps.current_month_rejected, 0) AS current_month_rejected,
    COALESCE(aps.current_month_escalated, 0) AS current_month_escalated,
    COALESCE(aps.sla_respect_percentage, 0::numeric) AS sla_respect_percentage,
    aps.avg_processing_minutes,
    COALESCE(aw.quality_score_avg, 0::numeric) AS quality_score_avg,
    COALESCE(aw.success_rate, 0::numeric) AS success_rate,
    round(COALESCE(aps.sla_respect_percentage, 0::numeric) * 0.30 + COALESCE(aw.quality_score_avg, 0::numeric) * 0.30 + COALESCE(aw.success_rate, 0::numeric) * 0.20 + LEAST(COALESCE(aps.current_month_processed, 0)::numeric / 10.0, 20::numeric) * 0.20, 2) AS performance_score,
        CASE
            WHEN COALESCE(aps.sla_respect_percentage, 0::numeric) >= 90::numeric AND COALESCE(aw.quality_score_avg, 0::numeric) >= 85::numeric THEN 'EXCELLENT'::text
            WHEN COALESCE(aps.sla_respect_percentage, 0::numeric) >= 75::numeric AND COALESCE(aw.quality_score_avg, 0::numeric) >= 70::numeric THEN 'GOOD'::text
            WHEN COALESCE(aps.sla_respect_percentage, 0::numeric) >= 60::numeric THEN 'AVERAGE'::text
            ELSE 'NEEDS_IMPROVEMENT'::text
        END AS performance_tier,
    rank() OVER (ORDER BY (COALESCE(aps.sla_respect_percentage, 0::numeric)) DESC, (COALESCE(aps.current_month_processed, 0)) DESC) AS overall_rank,
    rank() OVER (PARTITION BY ap.ministry_id ORDER BY (COALESCE(aps.sla_respect_percentage, 0::numeric)) DESC, (COALESCE(aps.current_month_processed, 0)) DESC) AS ministry_rank
   FROM agent_profiles ap
     JOIN users u ON ap.user_id = u.id
     LEFT JOIN ministries m ON ap.ministry_id = m.id
     LEFT JOIN entities e ON ap.entity_id = e.id
     LEFT JOIN agent_performance_stats aps ON ap.id = aps.agent_profile_id
     LEFT JOIN agent_workloads aw ON ap.id = aw.agent_profile_id
  WHERE ap.is_active = true;;

CREATE OR REPLACE VIEW "public"."v_agent_performance_summary" AS
 SELECT aps.agent_profile_id,
    ap.user_id,
    ap.agent_type,
    ap.is_supervisor,
    ap.ministry_id,
    ap.entity_id,
    u.full_name AS agent_name,
    e.code AS entity_code,
    e.name AS entity_name,
    m.name_es AS ministry_name,
    aps.current_month_processed,
    aps.current_month_approved,
    aps.current_month_rejected,
    aps.current_month_escalated,
    aps.avg_processing_minutes,
    aps.sla_respected_count,
    aps.sla_missed_count,
    aps.sla_respect_percentage,
        CASE
            WHEN aps.current_month_processed > 0 THEN round(aps.current_month_approved::numeric / aps.current_month_processed::numeric * 100::numeric, 2)
            ELSE 0::numeric
        END AS approval_rate,
        CASE
            WHEN aps.current_month_processed > 0 THEN round(aps.current_month_rejected::numeric / aps.current_month_processed::numeric * 100::numeric, 2)
            ELSE 0::numeric
        END AS rejection_rate,
        CASE
            WHEN aps.current_month_processed > 0 THEN round(aps.current_month_escalated::numeric / aps.current_month_processed::numeric * 100::numeric, 2)
            ELSE 0::numeric
        END AS escalation_rate,
    aps.stats_period_start,
    aps.stats_period_end,
    aps.last_action_at,
    aps.updated_at
   FROM agent_performance_stats aps
     JOIN agent_profiles ap ON aps.agent_profile_id = ap.id
     JOIN users u ON ap.user_id = u.id
     LEFT JOIN entities e ON ap.entity_id = e.id
     LEFT JOIN ministries m ON ap.ministry_id = m.id
  WHERE ap.is_active = true;;

CREATE OR REPLACE VIEW "public"."v_agent_work_queue_priority" AS
 SELECT awq.id AS queue_id,
    awq.item_type,
    awq.item_id,
    awq.entity_code,
    e.name AS entity_name,
    awq.ministry_id,
    m.name_es AS ministry_name,
    awq.declaration_type,
    awq.amount AS calculated_tax,
    awq.priority_score AS priority,
    awq.sla_deadline,
    awq.sla_status,
    awq.status AS queue_status,
    awq.assigned_to AS assigned_user_id,
    ap.id AS agent_profile_id,
    u.full_name AS agent_name,
    awq.escalated,
    awq.escalation_reason,
    awq.created_at,
    EXTRACT(epoch FROM now() - awq.created_at) / 3600::numeric AS hours_in_queue,
        CASE
            WHEN awq.sla_deadline IS NOT NULL AND now() > awq.sla_deadline THEN true
            ELSE false
        END AS is_overdue,
        CASE
            WHEN awq.sla_deadline IS NOT NULL THEN EXTRACT(epoch FROM awq.sla_deadline - now()) / 3600::numeric
            ELSE NULL::numeric
        END AS hours_until_deadline
   FROM agent_work_queue awq
     LEFT JOIN entities e ON awq.entity_code = e.code::text
     LEFT JOIN ministries m ON awq.ministry_id = m.id
     LEFT JOIN users u ON awq.assigned_to = u.id
     LEFT JOIN agent_profiles ap ON ap.user_id = u.id AND ap.is_active = true
  WHERE awq.status::text = ANY (ARRAY['pending'::character varying, 'in_progress'::character varying, 'assigned'::character varying]::text[])
  ORDER BY awq.priority_score DESC, awq.created_at;;

CREATE OR REPLACE VIEW "public"."v_agent_workload_enriched" AS
 SELECT w.report_date,
    w.agent_profile_id,
    w.agent_name,
    ap.agent_type,
    ap.is_supervisor,
    ap.is_active AS agent_is_active,
    e.id AS entity_id,
    e.code AS entity_code,
    e.name AS entity_name,
    e.entity_type::text AS entity_type,
    e.workflow_codes ? 'BUNDLE_PAYMENT'::text AS is_oms,
    el.id AS entity_location_id,
    el.city AS location_city,
    el.region AS location_region,
    el.location_name,
    el.is_main_office,
    ap.ministry_id,
    w.approved,
    w.rejected,
    w.total_actions,
    w.avg_duration_seconds,
    w.min_duration_seconds,
    w.max_duration_seconds,
    w.p50_duration_seconds
   FROM mv_agent_daily_workload w
     LEFT JOIN agent_profiles ap ON ap.id = w.agent_profile_id
     LEFT JOIN entities e ON e.id = ap.entity_id
     LEFT JOIN entity_locations el ON el.id = ap.entity_location_id;;

CREATE OR REPLACE VIEW "public"."v_agent_workload_summary" AS
 SELECT aw.id AS workload_id,
    aw.agent_profile_id,
    ap.user_id,
    ap.agent_type,
    ap.is_supervisor,
    ap.ministry_id,
    ap.entity_id,
    ap.entity_location_id,
    u.full_name AS agent_name,
    u.email AS agent_email,
    e.code AS entity_code,
    e.name AS entity_name,
    m.name_es AS ministry_name,
    aw.current_assignments,
    aw.pending_declarations,
    aw.in_progress_declarations,
    aw.max_concurrent_assignments,
    aw.capacity_percentage,
    aw.workload_status,
    aw.availability,
    aw.availability_reason,
    aw.unavailable_until,
    aw.avg_processing_time_hours,
    aw.avg_daily_completions,
    aw.completion_rate_7d,
    aw.quality_score_avg,
    aw.success_rate,
    aw.deadline_compliance_rate,
    aw.last_assignment_at,
    aw.last_completion_at,
    aw.last_updated_at,
        CASE
            WHEN aw.capacity_percentage >= 100::numeric THEN 'OVERLOADED'::text
            WHEN aw.capacity_percentage >= 80::numeric THEN 'HIGH'::text
            WHEN aw.capacity_percentage >= 50::numeric THEN 'MEDIUM'::text
            ELSE 'LOW'::text
        END AS load_level,
    aw.max_concurrent_assignments - aw.current_assignments AS available_capacity
   FROM agent_workloads aw
     JOIN agent_profiles ap ON aw.agent_profile_id = ap.id
     JOIN users u ON ap.user_id = u.id
     LEFT JOIN entities e ON ap.entity_id = e.id
     LEFT JOIN ministries m ON ap.ministry_id = m.id
  WHERE ap.is_active = true;;

CREATE OR REPLACE VIEW "public"."v_agents_workload_dashboard" AS
 SELECT ap.id AS agent_profile_id,
    ap.user_id,
    u.email,
    u.full_name,
    ap.agent_type,
    ap.is_supervisor,
    ap.ministry_id,
    m.ministry_code,
    m.name_es AS ministry_name,
    ap.entity_id,
    ap.entity_location_id,
    e.code AS entity_code,
    e.name AS entity_name,
    ap.is_active,
    COALESCE(aw.current_assignments, 0) AS current_assignments,
    COALESCE(aw.pending_declarations, 0) AS pending_declarations,
    COALESCE(aw.in_progress_declarations, 0) AS in_progress_declarations,
    COALESCE(aw.max_concurrent_assignments, 20) AS max_concurrent_assignments,
    COALESCE(aw.capacity_percentage, 0::numeric) AS capacity_percentage,
    COALESCE(aw.workload_status::text, 'available'::text) AS workload_status,
    COALESCE(aw.availability::text, 'available'::text) AS availability,
    aw.quality_score_avg,
    aw.success_rate,
    aw.avg_daily_completions,
    aw.last_assignment_at,
    aw.last_completion_at,
        CASE
            WHEN COALESCE(aw.capacity_percentage, 0::numeric) >= 100::numeric THEN 'FULL'::text
            WHEN COALESCE(aw.capacity_percentage, 0::numeric) >= 80::numeric THEN 'HIGH'::text
            WHEN COALESCE(aw.capacity_percentage, 0::numeric) >= 50::numeric THEN 'MEDIUM'::text
            ELSE 'LOW'::text
        END AS load_level,
    COALESCE(aps.current_month_processed, 0) AS current_month_processed,
    COALESCE(aps.current_month_approved, 0) AS current_month_approved,
    COALESCE(aps.current_month_rejected, 0) AS current_month_rejected,
    aps.sla_respect_percentage,
        CASE
            WHEN m.ministry_code::text = 'DGI'::text THEN 'dgi'::text
            WHEN m.ministry_code::text = 'TESORO'::text THEN 'treasury'::text
            WHEN ap.agent_type::text = 'entity_agent'::text THEN 'entity'::text
            ELSE 'ministry'::text
        END AS agent_category
   FROM agent_profiles ap
     JOIN users u ON ap.user_id = u.id
     LEFT JOIN ministries m ON ap.ministry_id = m.id
     LEFT JOIN entities e ON ap.entity_id = e.id
     LEFT JOIN agent_workloads aw ON ap.id = aw.agent_profile_id
     LEFT JOIN agent_performance_stats aps ON ap.id = aps.agent_profile_id;;

CREATE OR REPLACE VIEW "public"."v_ai_cost_daily" AS
 SELECT date_trunc('day'::text, "timestamp")::date AS day,
    feature,
    model_name,
    count(*) AS call_count,
    sum(input_tokens) AS input_tokens,
    sum(output_tokens) AS output_tokens,
    sum(total_tokens) AS total_tokens,
    sum(cost_xaf) AS cost_xaf,
    percentile_cont(0.50::double precision) WITHIN GROUP (ORDER BY (latency_ms::double precision)) AS p50_latency_ms,
    percentile_cont(0.95::double precision) WITHIN GROUP (ORDER BY (latency_ms::double precision)) AS p95_latency_ms,
    percentile_cont(0.99::double precision) WITHIN GROUP (ORDER BY (latency_ms::double precision)) AS p99_latency_ms,
    sum((status = 'success'::text)::integer) AS success_count,
    sum((status <> 'success'::text)::integer) AS error_count,
    sum((status = 'rate_limited'::text)::integer) AS rate_limited_count,
    sum((status = 'json_parse_error'::text)::integer) AS json_error_count,
    sum((status = 'timeout'::text)::integer) AS timeout_count
   FROM ai_call_metrics
  WHERE "timestamp" > (now() - '90 days'::interval)
  GROUP BY (date_trunc('day'::text, "timestamp")::date), feature, model_name
  ORDER BY (date_trunc('day'::text, "timestamp")::date) DESC, (sum(cost_xaf)) DESC;;

CREATE OR REPLACE VIEW "public"."v_ai_cost_hourly" AS
 SELECT date_trunc('hour'::text, "timestamp") AS hour,
    feature,
    count(*) AS call_count,
    sum(cost_xaf) AS cost_xaf,
    percentile_cont(0.95::double precision) WITHIN GROUP (ORDER BY (latency_ms::double precision)) AS p95_latency_ms,
    sum((status <> 'success'::text)::integer) AS error_count
   FROM ai_call_metrics
  WHERE "timestamp" > (now() - '7 days'::interval)
  GROUP BY (date_trunc('hour'::text, "timestamp")), feature
  ORDER BY (date_trunc('hour'::text, "timestamp")) DESC;;

CREATE OR REPLACE VIEW "public"."v_anomaly_summary" AS
 SELECT anomaly_type,
    severity,
    status,
    count(*) AS count,
    sum(COALESCE(affected_amount, difference_amount, 0::numeric)) AS total_affected,
    min(detected_at) AS oldest_detected,
    max(detected_at) AS newest_detected
   FROM payment_anomalies
  GROUP BY anomaly_type, severity, status;;

CREATE OR REPLACE VIEW "public"."v_appointments_by_city" AS
 SELECT COALESCE(el.city, 'Non specifie'::character varying) AS city,
    COALESCE(el.region, 'Non specifie'::character varying) AS region,
    count(*) AS total_appointments,
    count(*) FILTER (WHERE ah.status = 'confirmed'::appointment_hold_status) AS confirmed,
    count(*) FILTER (WHERE ah.status = 'held'::appointment_hold_status) AS pending,
    count(*) FILTER (WHERE ah.status = 'expired'::appointment_hold_status) AS expired,
    count(*) FILTER (WHERE ah.status = 'fallback'::appointment_hold_status) AS without_appointment
   FROM appointment_holds ah
     LEFT JOIN entity_locations el ON ah.entity_location_id = el.id
  GROUP BY el.city, el.region;;

CREATE OR REPLACE VIEW "public"."v_assignments_with_profiles" AS
 SELECT a.id,
    a.item_id,
    a.item_type,
    a.agent_profile_id,
    a.assigned_by_profile_id,
    a.assignment_method,
    a.status,
    a.notes,
    a.auto_assignment_score,
    a.score_breakdown,
    a.rule_applied_id,
    a.assigned_at,
    a.started_at,
    a.completed_at,
    a.processing_duration_hours,
    a.deadline,
    a.deadline_met,
    a.priority_level,
    a.reassigned_to_profile_id,
    a.reassigned_at,
    a.reassignment_reason,
    a.reassignment_notes,
    a.validation_status,
    a.quality_score,
    a.created_at,
    a.updated_at,
    ap.agent_type,
    ap.is_supervisor AS agent_is_supervisor,
    ap.ministry_id AS agent_ministry_id,
    ap.entity_id AS agent_entity_id,
    ap.user_id AS agent_user_id,
    u.full_name AS agent_full_name,
    u.email AS agent_email,
    abp.agent_type AS assigned_by_agent_type,
    abp.is_supervisor AS assigned_by_is_supervisor,
    abp.user_id AS assigned_by_user_id,
    abu.full_name AS assigned_by_full_name,
    abu.email AS assigned_by_email,
    rtp.agent_type AS reassigned_to_agent_type,
    rtp.is_supervisor AS reassigned_to_is_supervisor,
    rtp.user_id AS reassigned_to_user_id,
    rtu.full_name AS reassigned_to_full_name,
    m.name_es AS agent_ministry_name,
    e.name AS agent_entity_name
   FROM assignments a
     JOIN agent_profiles ap ON a.agent_profile_id = ap.id
     JOIN users u ON ap.user_id = u.id
     LEFT JOIN agent_profiles abp ON a.assigned_by_profile_id = abp.id
     LEFT JOIN users abu ON abp.user_id = abu.id
     LEFT JOIN agent_profiles rtp ON a.reassigned_to_profile_id = rtp.id
     LEFT JOIN users rtu ON rtp.user_id = rtu.id
     LEFT JOIN ministries m ON ap.ministry_id = m.id
     LEFT JOIN entities e ON ap.entity_id = e.id;;

CREATE OR REPLACE VIEW "public"."v_available_agents" AS
 SELECT ap.id AS agent_profile_id,
    ap.user_id,
    u.email,
    u.full_name,
    u.first_name,
    u.last_name,
    u.role AS user_role,
    ap.agent_type,
    ap.is_supervisor,
    ap.entity_id,
    ap.entity_location_id,
    e.code AS entity_code,
    e.name AS entity_name,
    ap.ministry_id,
    m.ministry_code,
    m.name_es AS ministry_name,
    ap.can_approve_unlimited,
    ap.max_approval_amount,
    ap.can_escalate,
    ap.can_assign_tasks,
    ap.specializations,
    ap.is_active,
    aw.current_assignments,
    aw.max_concurrent_assignments,
    aw.capacity_percentage,
    aw.workload_status,
    aw.availability,
    aw.quality_score_avg,
    aw.last_assignment_at,
        CASE
            WHEN m.ministry_code::text = 'DGI'::text THEN 'dgi'::text
            WHEN m.ministry_code::text = 'TESORO'::text THEN 'treasury'::text
            WHEN ap.agent_type::text = 'entity_agent'::text THEN 'entity'::text
            ELSE 'ministry'::text
        END AS agent_category
   FROM agent_profiles ap
     JOIN users u ON ap.user_id = u.id
     LEFT JOIN entities e ON ap.entity_id = e.id
     LEFT JOIN ministries m ON ap.ministry_id = m.id
     LEFT JOIN agent_workloads aw ON ap.id = aw.agent_profile_id
  WHERE ap.is_active = true AND (aw.availability = 'available'::agent_availability_enum OR aw.availability IS NULL) AND (aw.workload_status <> 'overloaded'::workload_status_enum OR aw.workload_status IS NULL);;

CREATE OR REPLACE VIEW "public"."v_available_agents_by_ministry" AS
 SELECT m.id AS ministry_id,
    m.ministry_code,
    m.name_es AS ministry_name,
    count(DISTINCT ap.id) AS total_agents,
    count(DISTINCT ap.id) FILTER (WHERE ap.is_active = true) AS active_agents,
    count(DISTINCT ap.id) FILTER (WHERE ap.is_active = true AND (aw.availability = 'available'::agent_availability_enum OR aw.availability IS NULL)) AS available_agents,
    count(DISTINCT ap.id) FILTER (WHERE ap.is_supervisor = true) AS supervisor_count,
    round(COALESCE(avg(aw.capacity_percentage), 0::numeric), 2) AS avg_capacity,
    COALESCE(sum(aw.max_concurrent_assignments - aw.current_assignments) FILTER (WHERE ap.is_active = true AND aw.availability = 'available'::agent_availability_enum), 0::bigint) AS available_capacity
   FROM ministries m
     LEFT JOIN agent_profiles ap ON m.id = ap.ministry_id
     LEFT JOIN agent_workloads aw ON ap.id = aw.agent_profile_id
  GROUP BY m.id, m.ministry_code, m.name_es;;

CREATE OR REPLACE VIEW "public"."v_available_workflow_codes" AS
 SELECT code,
    name_es,
    category,
    entity_code,
    workflow_type,
    is_generic,
        CASE
            WHEN is_generic = false THEN 'predefined'::text
            ELSE 'generic'::text
        END AS source_type,
    is_active
   FROM workflows w
  WHERE is_active = true
  ORDER BY entity_code, display_order;;

CREATE OR REPLACE VIEW "public"."v_chatbot_feedback_stats" AS
 SELECT count(*) AS total_feedback,
    count(*) FILTER (WHERE rating >= 4) AS positive_count,
    count(*) FILTER (WHERE rating <= 2) AS negative_count,
    round(avg(rating), 2) AS avg_rating,
    count(DISTINCT conversation_id) AS unique_conversations,
    count(*) FILTER (WHERE created_at >= (now() - '24:00:00'::interval)) AS feedback_last_24h,
    count(*) FILTER (WHERE created_at >= (now() - '7 days'::interval)) AS feedback_last_7d
   FROM chatbot_feedback;;

CREATE OR REPLACE VIEW "public"."v_declaration_assignments" AS
 SELECT a.id AS assignment_id,
    a.item_id AS declaration_id,
    a.item_type AS declaration_type,
    a.agent_profile_id,
    a.assigned_by_profile_id,
    a.assignment_method,
    a.status AS assignment_status,
    a.notes AS assignment_notes,
    a.priority_level AS assignment_priority,
    a.assigned_at,
    a.started_at,
    a.completed_at AS assignment_completed_at,
    a.deadline AS assignment_deadline,
    a.deadline_met,
    a.reassigned_to_profile_id,
    a.reassigned_at,
    a.reassignment_reason,
    a.quality_score,
    ap.agent_type,
    ap.is_supervisor AS agent_is_supervisor,
    ap.ministry_id AS agent_ministry_id,
    ap.entity_id AS agent_entity_id,
    ap.user_id AS agent_user_id,
    u.full_name AS agent_full_name,
    u.email AS agent_email,
    td.declaration_number AS declaration_reference,
    td.user_id AS taxpayer_user_id,
    taxpayer.full_name AS taxpayer_name,
    taxpayer.email AS taxpayer_email,
    td.fiscal_year,
    td.fiscal_period,
    td.status AS declaration_status,
    td.calculated_tax,
    td.net_tax_due,
    td.submitted_at AS declaration_submitted_at,
    td.processed_at AS declaration_processed_at,
    m.name_es AS agent_ministry_name,
    e.name AS agent_entity_name
   FROM assignments a
     JOIN agent_profiles ap ON a.agent_profile_id = ap.id
     JOIN users u ON ap.user_id = u.id
     JOIN tax_declarations td ON a.item_id = td.id
     JOIN users taxpayer ON td.user_id = taxpayer.id
     LEFT JOIN ministries m ON ap.ministry_id = m.id
     LEFT JOIN entities e ON ap.entity_id = e.id;;

CREATE OR REPLACE VIEW "public"."v_declaration_statistics_by_type" AS
 WITH declaration_payments AS (
         SELECT d.id,
            d.declaration_type,
            d.status,
            d.calculated_tax,
            d.net_tax_due,
            d.processed_at,
            d.submitted_at,
            d.created_at,
            COALESCE(( SELECT sum(p.amount) AS sum
                   FROM payments p
                  WHERE p.tax_declaration_id = d.id AND p.status = 'completed'::payment_status_enum), 0::numeric) AS amount_paid
           FROM tax_declarations d
        )
 SELECT declaration_type,
    count(*) AS total_count,
    count(
        CASE
            WHEN status = 'draft'::declaration_status_enum THEN 1
            ELSE NULL::integer
        END) AS draft_count,
    count(
        CASE
            WHEN status = 'submitted'::declaration_status_enum THEN 1
            ELSE NULL::integer
        END) AS submitted_count,
    count(
        CASE
            WHEN status = 'processing'::declaration_status_enum THEN 1
            ELSE NULL::integer
        END) AS processing_count,
    count(
        CASE
            WHEN status = 'accepted'::declaration_status_enum THEN 1
            ELSE NULL::integer
        END) AS accepted_count,
    count(
        CASE
            WHEN status = 'rejected'::declaration_status_enum THEN 1
            ELSE NULL::integer
        END) AS rejected_count,
    sum(calculated_tax) AS total_tax_calculated,
    sum(net_tax_due) AS total_net_tax_due,
    sum(amount_paid) AS total_amount_paid,
    sum(net_tax_due - amount_paid) AS total_amount_due,
    avg(calculated_tax) AS avg_tax_per_declaration,
    avg(EXTRACT(epoch FROM processed_at - submitted_at) / 3600::numeric) AS avg_processing_hours,
    count(
        CASE
            WHEN date_trunc('month'::text, created_at) = date_trunc('month'::text, now()) THEN 1
            ELSE NULL::integer
        END) AS count_current_month,
    sum(
        CASE
            WHEN date_trunc('month'::text, created_at) = date_trunc('month'::text, now()) THEN calculated_tax
            ELSE 0::numeric
        END) AS revenue_current_month
   FROM declaration_payments
  GROUP BY declaration_type
  ORDER BY (count(*)) DESC;;

CREATE OR REPLACE VIEW "public"."v_declarations_pending_review" AS
 SELECT d.id,
    d.declaration_type,
    d.user_id,
    u.full_name AS user_name,
    u.email AS user_email,
    d.taxable_base,
    d.calculated_tax,
    d.submitted_at,
    d.created_at,
        CASE
            WHEN d.calculated_tax >= 10000000::numeric THEN 'HIGH'::text
            WHEN d.calculated_tax >= 1000000::numeric THEN 'MEDIUM'::text
            ELSE 'LOW'::text
        END AS priority,
    EXTRACT(day FROM now() - d.submitted_at) AS days_waiting,
        CASE
            WHEN EXTRACT(hour FROM now() - d.submitted_at) > 24::numeric THEN 'OVERDUE'::text
            WHEN EXTRACT(hour FROM now() - d.submitted_at) > 20::numeric THEN 'AT_RISK'::text
            ELSE 'ON_TIME'::text
        END AS sla_status,
        CASE
            WHEN (EXISTS ( SELECT 1
               FROM assignments a
              WHERE a.item_id = d.id AND (a.status = ANY (ARRAY['assigned'::assignment_status_enum, 'in_progress'::assignment_status_enum, 'pending_review'::assignment_status_enum])))) THEN true
            ELSE false
        END AS has_active_assignment
   FROM tax_declarations d
     JOIN users u ON d.user_id = u.id
  WHERE d.status = ANY (ARRAY['submitted'::declaration_status_enum, 'processing'::declaration_status_enum])
  ORDER BY (
        CASE
            WHEN d.calculated_tax >= 10000000::numeric THEN 1
            WHEN d.calculated_tax >= 1000000::numeric THEN 2
            ELSE 3
        END), d.submitted_at;;

CREATE OR REPLACE VIEW "public"."v_declarations_with_payments" AS
 SELECT d.id AS declaration_id,
    d.declaration_type,
    d.user_id,
    u.full_name AS user_name,
    d.fiscal_year,
    d.fiscal_period,
    d.calculated_tax,
    d.net_tax_due,
    COALESCE(( SELECT sum(p2.amount) AS sum
           FROM payments p2
          WHERE p2.tax_declaration_id = d.id AND p2.status = 'completed'::payment_status_enum), 0::numeric) AS amount_paid,
    d.net_tax_due - COALESCE(( SELECT sum(p2.amount) AS sum
           FROM payments p2
          WHERE p2.tax_declaration_id = d.id AND p2.status = 'completed'::payment_status_enum), 0::numeric) AS amount_due,
        CASE
            WHEN (d.net_tax_due - COALESCE(( SELECT sum(p2.amount) AS sum
               FROM payments p2
              WHERE p2.tax_declaration_id = d.id AND p2.status = 'completed'::payment_status_enum), 0::numeric)) <= 0::numeric THEN 'FULLY_PAID'::text
            WHEN COALESCE(( SELECT sum(p2.amount) AS sum
               FROM payments p2
              WHERE p2.tax_declaration_id = d.id AND p2.status = 'completed'::payment_status_enum), 0::numeric) > 0::numeric THEN 'PARTIALLY_PAID'::text
            ELSE 'UNPAID'::text
        END AS payment_status,
    p.id AS payment_id,
    p.payment_method,
    p.amount AS payment_amount,
    p.bank_reference,
    p.paid_at,
    p.status AS payment_status_detail,
    bt.id AS bank_transaction_id,
    bt.bank_code,
    bt.bank_reference AS bank_confirmed_reference,
    bt.bank_transaction_date,
    bt.reconciled_at,
    bt.reconciled_by,
    pp.id AS payment_plan_id,
    pp.number_of_installments,
    pp.status AS payment_plan_status,
    ( SELECT count(*) AS count
           FROM payment_installments pi
          WHERE pi.payment_plan_id = pp.id AND pi.paid_at IS NOT NULL) AS installments_paid,
    ( SELECT min(pi.due_date) AS min
           FROM payment_installments pi
          WHERE pi.payment_plan_id = pp.id AND pi.paid_at IS NULL) AS next_due_date
   FROM tax_declarations d
     JOIN users u ON d.user_id = u.id
     LEFT JOIN payments p ON d.id = p.tax_declaration_id
     LEFT JOIN bank_transactions bt ON p.bank_transaction_id = bt.id
     LEFT JOIN payment_plans pp ON d.id = pp.tax_declaration_id
  WHERE d.calculated_tax > 0::numeric
  ORDER BY d.created_at DESC;;

CREATE OR REPLACE VIEW "public"."v_embedding_status" AS
 SELECT count(*) FILTER (WHERE embedding IS NOT NULL) AS total_with_embeddings,
    count(*) FILTER (WHERE embedding IS NULL) AS total_without_embeddings,
    count(*) FILTER (WHERE needs_embedding_update = true) AS total_needs_update,
    count(*) AS total_services,
    round(100.0 * count(*) FILTER (WHERE embedding IS NOT NULL)::numeric / NULLIF(count(*), 0)::numeric, 2) AS coverage_percentage,
    max(embedding_generated_at) AS last_embedding_generated,
    min(embedding_generated_at) FILTER (WHERE embedding IS NOT NULL) AS first_embedding_generated
   FROM fiscal_services
  WHERE status = 'active'::service_status_enum;;

CREATE OR REPLACE VIEW "public"."v_entities_browse" AS
 SELECT id AS entity_id,
    code AS entity_code,
    name AS entity_name,
    entity_type::text AS entity_type,
    workflow_codes ? 'BUNDLE_PAYMENT'::text AS is_oms,
    ministry_id,
    parent_entity_id,
    workflow_codes,
    is_active AS entity_is_active
   FROM entities e
  WHERE is_active = true;;

CREATE OR REPLACE VIEW "public"."v_entities_with_workflows" AS
 SELECT e.id,
    e.code,
    e.name,
    e.description,
    e.entity_type,
    e.parent_entity_id,
    pe.code AS parent_entity_code,
    pe.name AS parent_entity_name,
    e.ministry_id,
    m.name_es AS ministry_name,
    e.workflow_codes AS direct_workflow_codes,
    get_entity_workflows(e.id) AS resolved_workflow_codes,
    jsonb_array_length(get_entity_workflows(e.id)) AS workflow_count,
    e.is_active,
    e.created_at,
    e.updated_at
   FROM entities e
     LEFT JOIN entities pe ON pe.id = e.parent_entity_id
     LEFT JOIN ministries m ON m.id = e.ministry_id
  WHERE e.is_active = true;;

CREATE OR REPLACE VIEW "public"."v_entity_default_roles" AS
 SELECT e.id AS entity_id,
    e.code AS entity_code,
    e.name AS entity_name,
    e.entity_type,
    m.ministry_code,
    m.name_es AS ministry_name,
        CASE e.code
            WHEN 'CNEDOGE_PASAPORTE'::text THEN 'agent_cnedoge_pasaporte'::text
            WHEN 'CNEDOGE_RESIDENCIA'::text THEN 'agent_cnedoge_residencia'::text
            WHEN 'ONRC'::text THEN 'agent_onrc'::text
            WHEN 'OFIVE'::text THEN 'agent_ofive'::text
            WHEN 'DGT'::text THEN 'agent_dgt_permiso'::text
            WHEN 'TESORO'::text THEN 'agent_tesoro_validation'::text
            ELSE NULL::text
        END AS default_role_code,
    r.id AS default_role_id,
    r.name AS default_role_name
   FROM entities e
     LEFT JOIN ministries m ON e.ministry_id = m.id
     LEFT JOIN roles r ON r.code::text =
        CASE e.code
            WHEN 'CNEDOGE_PASAPORTE'::text THEN 'agent_cnedoge_pasaporte'::text
            WHEN 'CNEDOGE_RESIDENCIA'::text THEN 'agent_cnedoge_residencia'::text
            WHEN 'ONRC'::text THEN 'agent_onrc'::text
            WHEN 'OFIVE'::text THEN 'agent_ofive'::text
            WHEN 'DGT'::text THEN 'agent_dgt_permiso'::text
            WHEN 'TESORO'::text THEN 'agent_tesoro_validation'::text
            ELSE NULL::text
        END
  WHERE e.is_active = true
  ORDER BY e.entity_type, e.code;;

CREATE OR REPLACE VIEW "public"."v_entity_locations" AS
 SELECT id,
    entity_code,
    city,
    region,
    location_name,
    location_address,
    phone,
    email,
    is_main_office,
    is_active,
    operating_hours
   FROM entity_locations
  WHERE is_active = true
  ORDER BY entity_code, is_main_office DESC, city;;

CREATE OR REPLACE VIEW "public"."v_entity_locations_browse" AS
 SELECT el.id AS entity_location_id,
    el.entity_code,
    e.name AS entity_name,
    el.location_name,
    el.city,
    el.region,
    el.is_main_office,
    el.is_active AS location_is_active
   FROM entity_locations el
     LEFT JOIN entities e ON e.id = el.entity_id
  WHERE el.is_active = true;;

CREATE OR REPLACE VIEW "public"."v_field_inspections_enriched" AS
 SELECT fi.id,
    fi.inspection_date,
    fi.status,
    fi.result,
    fi.activity_conforme,
    fi.activity_declared,
    fi.activity_observed,
    fi.unpaid_obligations_count,
    fi.unpaid_obligations_amount,
    fi.total_obligations_count,
    fi.mise_en_demeure_issued,
    fi.mise_en_demeure_deadline,
    fi.seal_applied,
    fi.seal_reason,
    fi.seal_proposed_at,
    fi.seal_approved_at,
    fi.seal_approved_by,
    fi.payment_collected,
    fi.payment_amount,
    fi.payment_receipt_number,
    jsonb_array_length(COALESCE(fi.photos, '[]'::jsonb)) AS photos_count,
    fi.gps_latitude,
    fi.gps_longitude,
    fi.gps_accuracy,
    fi.duration_minutes,
    fi.agent_id,
    u.full_name AS agent_full_name,
    u.email AS agent_email,
    fi.agent_profile_id,
    ap.agent_type,
    fi.entity_id,
    e.code AS entity_code,
    e.name AS entity_name,
    fi.entity_location_id,
    el.city AS location_city,
    el.region AS location_region,
    el.location_name,
    fi.zone_id,
    fi.mission_id,
    fi.license_id,
    fi.company_id,
    fi.created_at,
    fi.updated_at
   FROM field_inspections fi
     LEFT JOIN users u ON u.id = fi.agent_id
     LEFT JOIN agent_profiles ap ON ap.id = fi.agent_profile_id
     LEFT JOIN entities e ON e.id = fi.entity_id
     LEFT JOIN entity_locations el ON el.id = fi.entity_location_id;;

CREATE OR REPLACE VIEW "public"."v_gemini_errors" AS
 SELECT id,
    created_at,
    document_category,
    document_type_detected,
    workflow_code,
    processor,
    error_type,
    error_message,
    error_details,
    processing_time_ms,
    used_fallback,
    fallback_reason
   FROM gemini_processing_logs
  WHERE has_error = true
  ORDER BY created_at DESC;;

CREATE OR REPLACE VIEW "public"."v_gemini_processing_stats" AS
 SELECT date(created_at) AS date,
    document_category,
    processor,
    count(*) AS total_processings,
    count(*) FILTER (WHERE is_match = true) AS successful_matches,
    count(*) FILTER (WHERE has_error = true) AS errors,
    count(*) FILTER (WHERE used_fallback = true) AS fallbacks,
    avg(processing_time_ms) AS avg_processing_time_ms,
    avg(gemini_latency_ms) AS avg_gemini_latency_ms,
    avg(classification_confidence) AS avg_classification_confidence,
    avg(extraction_confidence) AS avg_extraction_confidence,
    avg(risk_score) AS avg_risk_score,
    count(*) FILTER (WHERE recommendation::text = 'auto_approve'::text) AS auto_approvals,
    count(*) FILTER (WHERE recommendation::text = 'manual_review'::text) AS manual_reviews,
    count(*) FILTER (WHERE recommendation::text = 'reject'::text) AS rejections,
    sum(total_tokens) AS total_tokens_used
   FROM gemini_processing_logs
  WHERE created_at >= (CURRENT_DATE - '30 days'::interval)
  GROUP BY (date(created_at)), document_category, processor
  ORDER BY (date(created_at)) DESC, document_category;;

CREATE OR REPLACE VIEW "public"."v_kpi_summary" AS
 SELECT 'today'::text AS period,
    sum(mv_treasury_daily_kpis.total_amount) AS total_collected,
    sum(mv_treasury_daily_kpis.completed_count) AS total_transactions,
    avg(mv_treasury_daily_kpis.avg_amount) AS avg_transaction,
    sum(mv_treasury_daily_kpis.sla_breached_count) AS sla_breaches
   FROM mv_treasury_daily_kpis
  WHERE mv_treasury_daily_kpis.report_date = CURRENT_DATE
UNION ALL
 SELECT 'week'::text AS period,
    sum(mv_treasury_daily_kpis.total_amount) AS total_collected,
    sum(mv_treasury_daily_kpis.completed_count) AS total_transactions,
    avg(mv_treasury_daily_kpis.avg_amount) AS avg_transaction,
    sum(mv_treasury_daily_kpis.sla_breached_count) AS sla_breaches
   FROM mv_treasury_daily_kpis
  WHERE mv_treasury_daily_kpis.report_date >= date_trunc('week'::text, CURRENT_DATE::timestamp with time zone)
UNION ALL
 SELECT 'month'::text AS period,
    sum(mv_treasury_daily_kpis.total_amount) AS total_collected,
    sum(mv_treasury_daily_kpis.completed_count) AS total_transactions,
    avg(mv_treasury_daily_kpis.avg_amount) AS avg_transaction,
    sum(mv_treasury_daily_kpis.sla_breached_count) AS sla_breaches
   FROM mv_treasury_daily_kpis
  WHERE mv_treasury_daily_kpis.report_date >= date_trunc('month'::text, CURRENT_DATE::timestamp with time zone)
UNION ALL
 SELECT 'year'::text AS period,
    sum(mv_treasury_daily_kpis.total_amount) AS total_collected,
    sum(mv_treasury_daily_kpis.completed_count) AS total_transactions,
    avg(mv_treasury_daily_kpis.avg_amount) AS avg_transaction,
    sum(mv_treasury_daily_kpis.sla_breached_count) AS sla_breaches
   FROM mv_treasury_daily_kpis
  WHERE mv_treasury_daily_kpis.report_date >= date_trunc('year'::text, CURRENT_DATE::timestamp with time zone);;

CREATE OR REPLACE VIEW "public"."v_legislacion_embedding_status" AS
 SELECT document_name,
    count(*) AS total_chunks,
    count(
        CASE
            WHEN embedding IS NOT NULL THEN 1
            ELSE NULL::integer
        END) AS embedded_chunks,
    count(
        CASE
            WHEN needs_embedding_update = true THEN 1
            ELSE NULL::integer
        END) AS chunks_needing_update,
    min(embedding_generated_at) AS first_embedding_at,
    max(embedding_generated_at) AS last_embedding_at,
    count(
        CASE
            WHEN embedding IS NOT NULL THEN 1
            ELSE NULL::integer
        END)::numeric * 100.0 / count(*)::numeric AS embedding_coverage_percent
   FROM legislacion_documents
  GROUP BY document_name
  ORDER BY document_name;;

CREATE OR REPLACE VIEW "public"."v_notification_statistics" AS
 SELECT date(created_at) AS date,
    channel,
    count(*) AS total_sent,
    count(*) FILTER (WHERE status::text = 'delivered'::text) AS delivered,
    count(*) FILTER (WHERE status::text = 'failed'::text) AS failed,
    count(*) FILTER (WHERE status::text = 'bounced'::text) AS bounced,
    count(*) FILTER (WHERE status::text = 'opened'::text) AS opened,
    count(*) FILTER (WHERE status::text = 'clicked'::text) AS clicked,
    round(count(*) FILTER (WHERE status::text = 'delivered'::text)::numeric / NULLIF(count(*) FILTER (WHERE status::text = ANY (ARRAY['sent'::character varying, 'delivered'::character varying, 'opened'::character varying, 'clicked'::character varying]::text[])), 0)::numeric * 100::numeric, 2) AS delivery_rate_percent
   FROM notification_log
  WHERE created_at >= (CURRENT_DATE - '30 days'::interval)
  GROUP BY (date(created_at)), channel
  ORDER BY (date(created_at)) DESC, channel;;

CREATE OR REPLACE VIEW "public"."v_obligation_routing" AS
 SELECT e.id AS entity_id,
    e.code AS entity_code,
    e.name AS entity_name,
    e.ministry_id,
    el.id AS entity_location_id,
    el.city,
    el.city_id,
    el.region,
        CASE
            WHEN e.code::text = ANY (ARRAY['TESORO'::character varying, 'AYUNTAMIENTO'::character varying, 'CAMARA_COMERCIO'::character varying]::text[]) THEN 'payment_validator'::text
            ELSE 'post_payment_processor'::text
        END AS routing_role,
        CASE
            WHEN e.code::text = 'AYUNTAMIENTO'::text THEN 'municipal'::text
            WHEN e.code::text = 'CAMARA_COMERCIO'::text THEN 'chamber'::text
            ELSE 'tesoro'::text
        END AS validates_fee_type
   FROM entities e
     JOIN entity_locations el ON el.entity_id = e.id AND el.is_active = true
  WHERE e.code::text = ANY (ARRAY['TESORO'::character varying, 'AYUNTAMIENTO'::character varying, 'CAMARA_COMERCIO'::character varying, 'MIN_HACIENDA'::character varying, 'MIN_COMERCIO'::character varying, 'MIN_INFORMACION'::character varying, 'MIN_TURISMO'::character varying, 'MIN_AGRICULTURA'::character varying, 'MIN_ELECTRICIDAD'::character varying]::text[]);;

CREATE OR REPLACE VIEW "public"."v_overprivileged_users_detection" AS
 WITH role_averages AS (
         SELECT r.code AS role_code,
            count(DISTINCT rp.permission_id) AS role_perm_count,
            count(DISTINCT
                CASE
                    WHEN p.is_critical THEN p.id
                    ELSE NULL::uuid
                END) AS role_critical_count
           FROM roles r
             LEFT JOIN role_permissions rp ON rp.role_id = r.id
             LEFT JOIN permissions p ON p.id = rp.permission_id
          GROUP BY r.code
        ), user_totals AS (
         SELECT u.id AS user_id,
            u.email,
            COALESCE((u.first_name::text || ' '::text) || u.last_name::text, u.email::text) AS full_name,
            u.role::text AS role,
            r.code AS role_code,
            count(DISTINCT rp.permission_id) AS from_role,
            ( SELECT count(*) AS count
                   FROM user_permissions up
                  WHERE up.user_id = u.id AND up.granted = true AND (up.expires_at IS NULL OR up.expires_at >= now())) AS from_user_grants,
            ( SELECT count(*) AS count
                   FROM user_permissions up
                  WHERE up.user_id = u.id AND up.granted = false AND (up.expires_at IS NULL OR up.expires_at >= now())) AS from_user_denies,
            count(DISTINCT
                CASE
                    WHEN p.is_critical THEN p.id
                    ELSE NULL::uuid
                END) AS critical_from_role,
            ( SELECT count(*) AS count
                   FROM user_permissions up
                     JOIN permissions p2 ON p2.id = up.permission_id
                  WHERE up.user_id = u.id AND up.granted = true AND p2.is_critical AND (up.expires_at IS NULL OR up.expires_at >= now())) AS critical_from_user
           FROM users u
             LEFT JOIN roles r ON r.id = u.role_id
             LEFT JOIN role_permissions rp ON rp.role_id = r.id
             LEFT JOIN permissions p ON p.id = rp.permission_id
          WHERE u.status::text <> 'deactivated'::text
          GROUP BY u.id, u.email, u.first_name, u.last_name, u.role, r.code
        )
 SELECT ut.user_id,
    ut.email,
    ut.full_name,
    ut.role,
    ut.role_code,
    ut.from_role AS role_permissions,
    ut.from_user_grants AS user_grants,
    ut.from_user_denies AS user_denies,
    ut.from_role + ut.from_user_grants - ut.from_user_denies AS total_permissions,
    ut.critical_from_role + ut.critical_from_user AS total_critical,
    ut.from_user_grants + ut.critical_from_user * 5 +
        CASE
            WHEN ra.role_perm_count > 0 AND (ut.from_role + ut.from_user_grants)::numeric > (ra.role_perm_count::numeric * 1.5) THEN 10
            ELSE 0
        END +
        CASE
            WHEN (ut.critical_from_role + ut.critical_from_user) > 10 THEN 15
            ELSE 0
        END AS risk_score,
        CASE
            WHEN (ut.from_user_grants + ut.critical_from_user * 5 +
            CASE
                WHEN ra.role_perm_count > 0 AND (ut.from_role + ut.from_user_grants)::numeric > (ra.role_perm_count::numeric * 1.5) THEN 10
                ELSE 0
            END +
            CASE
                WHEN (ut.critical_from_role + ut.critical_from_user) > 10 THEN 15
                ELSE 0
            END) >= 50 THEN 'CRITICAL'::text
            WHEN (ut.from_user_grants + ut.critical_from_user * 5 +
            CASE
                WHEN ra.role_perm_count > 0 AND (ut.from_role + ut.from_user_grants)::numeric > (ra.role_perm_count::numeric * 1.5) THEN 10
                ELSE 0
            END +
            CASE
                WHEN (ut.critical_from_role + ut.critical_from_user) > 10 THEN 15
                ELSE 0
            END) >= 30 THEN 'HIGH'::text
            WHEN (ut.from_user_grants + ut.critical_from_user * 5 +
            CASE
                WHEN ra.role_perm_count > 0 AND (ut.from_role + ut.from_user_grants)::numeric > (ra.role_perm_count::numeric * 1.5) THEN 10
                ELSE 0
            END +
            CASE
                WHEN (ut.critical_from_role + ut.critical_from_user) > 10 THEN 15
                ELSE 0
            END) >= 20 THEN 'MEDIUM'::text
            ELSE 'LOW'::text
        END AS risk_level,
        CASE
            WHEN ut.from_user_grants > 10 THEN 'Review user-specific grants — consider creating a dedicated role'::text
            WHEN ut.critical_from_user > 3 THEN 'Excessive critical permissions via user grants — audit immediately'::text
            WHEN ra.role_perm_count > 0 AND (ut.from_role + ut.from_user_grants)::numeric > (ra.role_perm_count::numeric * 1.5) THEN 'User has 50%+ more permissions than role baseline — review grants'::text
            ELSE 'Within acceptable range'::text
        END AS recommendation
   FROM user_totals ut
     LEFT JOIN role_averages ra ON ra.role_code::text = ut.role_code::text;;

CREATE OR REPLACE VIEW "public"."v_pending_escalations" AS
 SELECT sp.id AS payment_id,
    sp.payment_reference,
    sp.service_request_id,
    sr.reference AS service_request_reference,
    sp.total_amount,
    sp.workflow_status,
    sp.escalation_level,
    sp.escalation_reason,
    sp.escalated_at,
    sp.escalated_to_agent_id AS escalated_to_agent_profile_id,
    supervisor.full_name AS escalated_to_name,
    supervisor.email AS escalated_to_email,
    sp.assigned_agent_id AS original_agent_profile_id,
    original_agent.full_name AS original_agent_name,
    ap_escalated.ministry_id,
    m.ministry_code,
    m.name_es AS ministry_name,
    round(EXTRACT(epoch FROM now() - sp.escalated_at) / 3600::numeric, 2) AS hours_since_escalation,
        CASE
            WHEN sp.escalation_level::text = 'critical'::text THEN 1
            WHEN sp.escalation_level::text = 'high'::text THEN 2
            WHEN sp.escalation_level::text = 'medium'::text THEN 3
            ELSE 4
        END AS priority_order
   FROM service_payments sp
     LEFT JOIN service_requests sr ON sp.service_request_id = sr.id
     LEFT JOIN agent_profiles ap_escalated ON ap_escalated.id = sp.escalated_to_agent_id
     LEFT JOIN users supervisor ON ap_escalated.user_id = supervisor.id
     LEFT JOIN agent_profiles ap_original ON ap_original.id = sp.assigned_agent_id
     LEFT JOIN users original_agent ON ap_original.user_id = original_agent.id
     LEFT JOIN ministries m ON ap_escalated.ministry_id = m.id
  WHERE (sp.workflow_status = ANY (ARRAY['escalated_supervisor'::payment_workflow_status, 'supervisor_reviewing'::payment_workflow_status])) AND sp.escalated_at IS NOT NULL
  ORDER BY (
        CASE
            WHEN sp.escalation_level::text = 'critical'::text THEN 1
            WHEN sp.escalation_level::text = 'high'::text THEN 2
            WHEN sp.escalation_level::text = 'medium'::text THEN 3
            ELSE 4
        END), sp.escalated_at;;

CREATE OR REPLACE VIEW "public"."v_pending_payment_validations" AS
 SELECT sp.id AS payment_id,
    sp.payment_reference,
    sp.service_request_id,
    sr.reference AS request_reference,
    sr.workflow_code,
    sp.user_id,
    u.full_name AS user_name,
    u.email AS user_email,
    sp.payment_method,
    sp.total_amount,
    sp.currency,
    sp.workflow_status,
    sp.assigned_agent_id AS assigned_agent_profile_id,
    assigned_ap.user_id AS assigned_to_user_id,
    assigned_user.full_name AS assigned_to_name,
    sp.batch_id,
    br.reference AS batch_reference,
    br.total_items AS batch_total_items,
    sp.escalated_to_agent_id,
    sp.escalation_level,
    sp.escalation_reason,
    sp.escalated_at,
    sp.sla_escalated,
    sp.created_at,
    EXTRACT(epoch FROM now() - sp.created_at) / 3600::numeric AS hours_waiting
   FROM service_payments sp
     LEFT JOIN service_requests sr ON sp.service_request_id = sr.id
     LEFT JOIN users u ON sp.user_id = u.id
     LEFT JOIN agent_profiles assigned_ap ON sp.assigned_agent_id = assigned_ap.id
     LEFT JOIN users assigned_user ON assigned_ap.user_id = assigned_user.id
     LEFT JOIN batch_requests br ON sp.batch_id = br.id
  WHERE sp.requires_agent_validation = true
  ORDER BY sp.created_at;;

CREATE OR REPLACE VIEW "public"."v_permission_grants_audit" AS
 SELECT pal.id,
    pal.user_id AS target_user_id,
    u.email AS target_email,
    u.role AS target_role,
    pal.permission_id,
    p.name AS permission_name,
    p.resource AS permission_resource,
    p.action AS permission_action,
    p.module_name,
    pal.action AS audit_action,
    pal.table_name,
    pal.changed_by,
    admin.email AS changed_by_email,
    admin.full_name AS changed_by_name,
    pal.old_value,
    pal.new_value,
    pal.changed_at
   FROM permission_audit_log pal
     LEFT JOIN users u ON pal.user_id = u.id
     LEFT JOIN permissions p ON pal.permission_id = p.id
     LEFT JOIN users admin ON pal.changed_by = admin.id
  ORDER BY pal.changed_at DESC;;

CREATE OR REPLACE VIEW "public"."v_permission_usage_analytics" AS
 WITH perm_stats AS (
         SELECT p.id AS permission_id,
            p.name AS permission_name,
            p.resource,
            p.action,
            p.module_name,
            p.module_name AS module,
            p.is_critical,
            p.created_at AS permission_created_at,
            count(DISTINCT up.user_id) FILTER (WHERE up.granted = true AND (up.expires_at IS NULL OR up.expires_at >= now())) AS direct_grant_count,
            count(DISTINCT rp.role_id) AS role_grant_count,
            count(DISTINCT u.id) AS users_with_permission
           FROM permissions p
             LEFT JOIN user_permissions up ON up.permission_id = p.id
             LEFT JOIN role_permissions rp ON rp.permission_id = p.id
             LEFT JOIN users u ON u.role_id = rp.role_id AND u.status::text = 'active'::text
          GROUP BY p.id, p.name, p.resource, p.action, p.module_name, p.is_critical, p.created_at
        )
 SELECT permission_id,
    permission_name,
    resource,
    action,
    module_name,
    module,
    is_critical,
    permission_created_at,
    direct_grant_count,
    role_grant_count,
    users_with_permission,
        CASE
            WHEN (users_with_permission + direct_grant_count) = 0 THEN 'UNUSED'::text
            WHEN (users_with_permission + direct_grant_count) <= 2 THEN 'RARELY_USED'::text
            WHEN (users_with_permission + direct_grant_count) <= 10 THEN 'MODERATELY_USED'::text
            ELSE 'WIDELY_USED'::text
        END AS usage_category
   FROM perm_stats;;

CREATE OR REPLACE VIEW "public"."v_recent_exports" AS
 SELECT te.id,
    te.export_type,
    te.export_format,
    te.period_start,
    te.period_end,
    te.status,
    te.total_records,
    te.total_amount,
    te.file_name,
    te.file_size_bytes,
    te.requested_at,
    te.completed_at,
    te.download_count,
    u.full_name AS requested_by_name,
    EXTRACT(epoch FROM te.completed_at - te.started_at) AS processing_seconds
   FROM treasury_exports te
     LEFT JOIN users u ON u.id = te.requested_by
  WHERE te.requested_at >= (CURRENT_DATE - '30 days'::interval)
  ORDER BY te.requested_at DESC;;

CREATE OR REPLACE VIEW "public"."v_recent_verification_audit" AS
 SELECT a.id,
    a.identifier_type,
    a.operation,
    a.performed_by,
    u.email AS performed_by_email,
    a.search_found,
    a.ip_address,
    a.created_at
   FROM verified_identifiers_audit a
     LEFT JOIN users u ON a.performed_by = u.id
  WHERE a.created_at > (now() - '30 days'::interval)
  ORDER BY a.created_at DESC;;

CREATE OR REPLACE VIEW "public"."v_reconciliation_health_metrics" AS
 SELECT now() AS snapshot_time,
    ( SELECT count(*) AS count
           FROM bank_transactions
          WHERE bank_transactions.service_payment_id IS NULL AND bank_transactions.status::text = 'unreconciled'::text) AS unreconciled_transactions,
    ( SELECT count(*) AS count
           FROM bank_transactions
          WHERE bank_transactions.service_payment_id IS NOT NULL AND bank_transactions.status::text = 'reconciled'::text) AS reconciled_transactions,
    ( SELECT COALESCE(sum(bank_transactions.amount), 0::numeric) AS "coalesce"
           FROM bank_transactions
          WHERE bank_transactions.service_payment_id IS NULL AND bank_transactions.status::text = 'unreconciled'::text) AS unreconciled_amount,
    ( SELECT COALESCE(sum(bank_transactions.amount), 0::numeric) AS "coalesce"
           FROM bank_transactions
          WHERE bank_transactions.service_payment_id IS NOT NULL AND bank_transactions.status::text = 'reconciled'::text) AS reconciled_amount,
    ( SELECT count(*) AS count
           FROM service_payments
          WHERE service_payments.workflow_status = 'completed'::payment_workflow_status AND service_payments.bank_transaction_id IS NULL) AS unmatched_payments,
    ( SELECT count(*) AS count
           FROM service_payments
          WHERE service_payments.workflow_status = 'completed'::payment_workflow_status AND service_payments.bank_transaction_id IS NOT NULL) AS matched_payments,
    ( SELECT count(*) AS count
           FROM bank_transactions
          WHERE bank_transactions.service_payment_id IS NULL AND bank_transactions.status::text = 'unreconciled'::text AND EXTRACT(day FROM now() - bank_transactions.created_at) > 7::numeric) AS unreconciled_over_7_days,
    ( SELECT round(count(
                CASE
                    WHEN bank_transactions.status::text = 'reconciled'::text THEN 1
                    ELSE NULL::integer
                END)::numeric / NULLIF(count(*), 0)::numeric * 100::numeric, 2) AS round
           FROM bank_transactions
          WHERE bank_transactions.created_at >= (now() - '30 days'::interval)) AS reconciliation_rate_30d,
    ( SELECT count(*) AS count
           FROM bank_transactions
          WHERE date(bank_transactions.created_at) = CURRENT_DATE) AS transactions_today,
    ( SELECT count(*) AS count
           FROM bank_transactions
          WHERE date(bank_transactions.reconciled_at) = CURRENT_DATE) AS reconciled_today;;

CREATE OR REPLACE VIEW "public"."v_risk_analysis_trends" AS
 SELECT date(gemini_processing_logs.created_at) AS date,
    gemini_processing_logs.workflow_code,
    count(*) AS total_analyses,
    avg(gemini_processing_logs.risk_score) AS avg_risk_score,
    count(*) FILTER (WHERE gemini_processing_logs.risk_level::text = 'low'::text) AS low_risk,
    count(*) FILTER (WHERE gemini_processing_logs.risk_level::text = 'medium'::text) AS medium_risk,
    count(*) FILTER (WHERE gemini_processing_logs.risk_level::text = 'high'::text) AS high_risk,
    count(*) FILTER (WHERE gemini_processing_logs.risk_level::text = 'critical'::text) AS critical_risk,
    count(*) FILTER (WHERE gemini_processing_logs.coherence_valid = true) AS coherent_documents,
    count(*) FILTER (WHERE gemini_processing_logs.coherence_valid = false) AS incoherent_documents,
    array_agg(DISTINCT rf.factor) FILTER (WHERE rf.factor IS NOT NULL) AS common_risk_factors
   FROM gemini_processing_logs
     LEFT JOIN LATERAL ( SELECT jsonb_array_elements_text(gemini_processing_logs.risk_factors) AS factor
          WHERE gemini_processing_logs.risk_factors IS NOT NULL AND gemini_processing_logs.risk_factors <> '[]'::jsonb) rf ON true
  WHERE gemini_processing_logs.created_at >= (CURRENT_DATE - '30 days'::interval) AND gemini_processing_logs.risk_score IS NOT NULL
  GROUP BY (date(gemini_processing_logs.created_at)), gemini_processing_logs.workflow_code
  ORDER BY (date(gemini_processing_logs.created_at)) DESC;;

CREATE OR REPLACE VIEW "public"."v_role_capabilities_summary" AS
 SELECT r.id AS role_id,
    r.name AS role_name,
    r.code AS role_code,
    r.description AS role_description,
    r.entity_type,
    r.is_system,
    count(DISTINCT rp.permission_id) FILTER (WHERE rp.granted = true) AS permission_count,
    count(DISTINCT u.id) AS user_count,
    array_agg(DISTINCT p.module_name ORDER BY p.module_name) FILTER (WHERE p.module_name IS NOT NULL AND rp.granted = true) AS modules_accessed,
    r.created_at
   FROM roles r
     LEFT JOIN role_permissions rp ON r.id = rp.role_id
     LEFT JOIN permissions p ON rp.permission_id = p.id
     LEFT JOIN users u ON u.role_id = r.id AND u.status = 'active'::user_status_enum
  GROUP BY r.id, r.name, r.code, r.description, r.entity_type, r.is_system, r.created_at
  ORDER BY (count(DISTINCT rp.permission_id) FILTER (WHERE rp.granted = true)) DESC;;

CREATE OR REPLACE VIEW "public"."v_service_payments_enriched" AS
 SELECT sp.id,
    sp.service_request_id,
    sp.payment_reference,
    sp.payment_type,
    sp.payment_method::text AS payment_method,
    sp.status::text AS payment_status,
    sp.workflow_status::text AS workflow_status,
    sp.base_amount,
    sp.penalties,
    sp.discounts,
    sp.total_amount,
    sp.currency,
    sp.entity_code AS sp_entity_code,
    sp.fee_type,
    sp.collection_type,
    sp.field_inspection_id,
    sp.receipt_number,
    sp.created_at,
    sp.updated_at,
    sp.paid_at,
    sp.validated_at,
    sr.workflow_code,
    sr.reference AS sr_reference,
    sr.entity_code,
    e.name AS entity_name,
    e.workflow_codes ? 'BUNDLE_PAYMENT'::text AS is_oms,
    sr.source AS sr_source,
        CASE
            WHEN sr.source::text = ANY (ARRAY['mobile_app'::character varying, 'mobile'::character varying, 'expo'::character varying]::text[]) THEN 'mobile'::text
            WHEN sr.source::text = ANY (ARRAY['inspector_app'::character varying, 'inspector'::character varying]::text[]) THEN 'inspector'::text
            WHEN sr.source::text = ANY (ARRAY['citizen_wizard'::character varying, 'web'::character varying, 'agent_dashboard'::character varying, 'admin_dashboard'::character varying]::text[]) THEN 'web'::text
            WHEN sr.source IS NULL OR sr.source::text = ''::text THEN 'unknown'::text
            ELSE sr.source::text
        END AS channel
   FROM service_payments sp
     LEFT JOIN service_requests sr ON sr.id = sp.service_request_id
     LEFT JOIN entities e ON e.code::text = sr.entity_code::text;;

CREATE OR REPLACE VIEW "public"."v_service_request_assignments" AS
 SELECT a.id AS assignment_id,
    a.item_id AS service_request_id,
    a.item_type AS workflow_code,
    a.agent_profile_id,
    a.assigned_by_profile_id,
    a.assignment_method,
    a.status AS assignment_status,
    a.notes AS assignment_notes,
    a.priority_level AS assignment_priority,
    a.assigned_at,
    a.started_at,
    a.completed_at AS assignment_completed_at,
    a.deadline AS assignment_deadline,
    a.deadline_met,
    a.reassigned_to_profile_id,
    a.reassigned_at,
    a.reassignment_reason,
    a.quality_score,
    ap.agent_type,
    ap.is_supervisor AS agent_is_supervisor,
    ap.ministry_id AS agent_ministry_id,
    ap.entity_id AS agent_entity_id,
    ap.user_id AS agent_user_id,
    u.full_name AS agent_full_name,
    u.email AS agent_email,
    sr.reference AS service_request_reference,
    sr.user_id AS requester_user_id,
    req_user.full_name AS requester_name,
    req_user.email AS requester_email,
    sr.solicitud_type,
    sr.status AS service_request_status,
    sr.priority AS service_request_priority,
    sr.total_amount,
    sr.currency,
    sr.payment_status,
    sr.entity_code AS service_entity_code,
    sr.entity_location_id,
    sr.cita_date,
    sr.cita_time,
    sr.cita_location,
    sr.submitted_at,
    sr.validated_at,
    sr.completed_at AS service_completed_at,
    sr.notes AS service_request_notes,
    sr.rejection_reason,
    m.name_es AS agent_ministry_name,
    e.name AS agent_entity_name
   FROM assignments a
     JOIN agent_profiles ap ON a.agent_profile_id = ap.id
     JOIN users u ON ap.user_id = u.id
     JOIN service_requests sr ON a.item_id = sr.id
     JOIN users req_user ON sr.user_id = req_user.id
     LEFT JOIN ministries m ON ap.ministry_id = m.id
     LEFT JOIN entities e ON ap.entity_id = e.id;;

CREATE OR REPLACE VIEW "public"."v_service_request_notifications" AS
 SELECT nl.id,
    nl.service_request_id,
    sr.reference AS request_reference,
    nl.user_id,
    u.full_name AS user_name,
    nl.channel,
    nl.template_code,
    nl.subject,
    nl.content_preview,
    nl.status,
    nl.external_provider,
    nl.queued_at,
    nl.sent_at,
    nl.delivered_at,
    nl.opened_at,
    nl.error_message,
    nl.retry_count,
    nl.trigger_event
   FROM notification_log nl
     LEFT JOIN service_requests sr ON sr.id = nl.service_request_id
     LEFT JOIN users u ON u.id = nl.user_id
  ORDER BY nl.created_at DESC;;

CREATE OR REPLACE VIEW "public"."v_service_request_payments" AS
 SELECT sp.id,
    sp.payment_reference,
    sp.service_request_id,
    sr.reference AS request_reference,
    sr.workflow_code,
    sr.solicitud_type,
    sp.user_id,
    u.email AS user_email,
    u.full_name AS user_name,
    sp.payment_method,
    sp.base_amount,
    sp.total_amount,
    sp.currency,
    sp.status,
    sp.workflow_status,
    sp.requires_agent_validation,
    sp.assigned_agent_id AS assigned_agent_profile_id,
    sp.validated_by_agent_id AS validated_by_agent_profile_id,
    sp.validated_at,
    sp.validation_comment,
    sp.receipt_number,
    sp.receipt_url,
    sp.paid_at,
    sp.created_at,
    sp.updated_at
   FROM service_payments sp
     LEFT JOIN service_requests sr ON sp.service_request_id = sr.id
     LEFT JOIN users u ON sp.user_id = u.id
  WHERE sp.service_request_id IS NOT NULL;;

CREATE OR REPLACE VIEW "public"."v_service_requests_by_city" AS
 SELECT COALESCE(el.city, 'Non specifie'::character varying) AS city,
    COALESCE(el.region, 'Non specifie'::character varying) AS region,
    count(*) AS total_requests,
    count(*) FILTER (WHERE sr.status = 'DRAFT'::service_request_status_enum) AS draft,
    count(*) FILTER (WHERE sr.status = 'SUBMITTED'::service_request_status_enum) AS submitted,
    count(*) FILTER (WHERE sr.status = 'UNDER_REVIEW'::service_request_status_enum) AS under_review,
    count(*) FILTER (WHERE sr.status = 'DOSSIER_VALIDE'::service_request_status_enum) AS approved,
    count(*) FILTER (WHERE sr.status = 'COMPLETED'::service_request_status_enum) AS completed
   FROM service_requests sr
     LEFT JOIN entity_locations el ON sr.entity_location_id = el.id
  GROUP BY el.city, el.region;;

CREATE OR REPLACE VIEW "public"."v_service_requests_channel" AS
 SELECT sr.id,
    sr.reference,
    sr.workflow_code,
    sr.solicitud_type,
    sr.status::text AS status,
    sr.priority::text AS priority,
    sr.entity_code,
    e.id AS entity_id,
    e.name AS entity_name,
    e.workflow_codes ? 'BUNDLE_PAYMENT'::text AS is_oms,
    sr.entity_location_id,
    el.city AS location_city,
    el.region AS location_region,
    sr.user_id,
    u.email AS requester_email,
    u.full_name AS requester_name,
    sr.source,
        CASE
            WHEN sr.source::text = ANY (ARRAY['mobile_app'::character varying, 'mobile'::character varying, 'expo'::character varying]::text[]) THEN 'mobile'::text
            WHEN sr.source::text = ANY (ARRAY['inspector_app'::character varying, 'inspector'::character varying]::text[]) THEN 'inspector'::text
            WHEN sr.source::text = ANY (ARRAY['citizen_wizard'::character varying, 'web'::character varying, 'agent_dashboard'::character varying, 'admin_dashboard'::character varying]::text[]) THEN 'web'::text
            WHEN sr.source IS NULL OR sr.source::text = ''::text THEN 'unknown'::text
            ELSE sr.source::text
        END AS channel,
    sr.total_amount,
    sr.payment_status,
    sr.created_at,
    sr.updated_at,
    sr.submitted_at,
    sr.completed_at,
    sr.escalated,
    sr.bundle_id,
    sr.commercial_license_id
   FROM service_requests sr
     LEFT JOIN entities e ON e.code::text = sr.entity_code::text
     LEFT JOIN entity_locations el ON el.id = sr.entity_location_id
     LEFT JOIN users u ON u.id = sr.user_id;;

CREATE OR REPLACE VIEW "public"."v_slot_availability_by_location" AS
 SELECT el.id AS location_id,
    el.entity_code,
    el.city,
    el.region,
    el.location_name,
    count(DISTINCT sc.id) AS slot_configs,
    COALESCE(sum(sc.max_appointments_per_slot), 0::bigint) AS daily_capacity,
    count(ah.id) FILTER (WHERE ah.status = 'confirmed'::appointment_hold_status AND ah.appointment_date >= CURRENT_DATE) AS upcoming_confirmed
   FROM entity_locations el
     LEFT JOIN appointment_slot_configs sc ON el.id = sc.entity_location_id AND sc.is_active = true
     LEFT JOIN appointment_holds ah ON sc.id = ah.slot_config_id
  WHERE el.is_active = true
  GROUP BY el.id, el.entity_code, el.city, el.region, el.location_name
  ORDER BY el.entity_code, el.is_main_office DESC, el.city;;

CREATE OR REPLACE VIEW "public"."v_top_entities" AS
 SELECT entity_code,
    entity_name,
    sum(completed_count) AS transaction_count,
    sum(total_amount) AS total_amount
   FROM mv_treasury_daily_kpis
  WHERE report_date >= date_trunc('month'::text, CURRENT_DATE::timestamp with time zone) AND entity_code IS NOT NULL
  GROUP BY entity_code, entity_name
  ORDER BY (sum(total_amount)) DESC
 LIMIT 10;;

CREATE OR REPLACE VIEW "public"."v_top_payment_methods" AS
 SELECT payment_method,
    sum(completed_count) AS transaction_count,
    sum(total_amount) AS total_amount,
    round(sum(total_amount) / NULLIF(sum(sum(total_amount)) OVER (), 0::numeric) * 100::numeric, 2) AS percentage
   FROM mv_treasury_daily_kpis
  WHERE report_date >= date_trunc('month'::text, CURRENT_DATE::timestamp with time zone)
  GROUP BY payment_method
  ORDER BY (sum(total_amount)) DESC;;

CREATE OR REPLACE VIEW "public"."v_top_workflows" AS
 SELECT workflow_code,
    solicitud_type,
    sum(completed_count) AS transaction_count,
    sum(total_amount) AS total_amount,
    round(sum(total_amount) / NULLIF(sum(sum(total_amount)) OVER (), 0::numeric) * 100::numeric, 2) AS percentage
   FROM mv_treasury_daily_kpis
  WHERE report_date >= date_trunc('month'::text, CURRENT_DATE::timestamp with time zone) AND workflow_code IS NOT NULL
  GROUP BY workflow_code, solicitud_type
  ORDER BY (sum(total_amount)) DESC
 LIMIT 10;;

CREATE OR REPLACE VIEW "public"."v_treasury_payments_by_site" AS
 SELECT sp.id AS payment_id,
    sp.payment_reference,
    sp.created_at,
    sp.paid_at,
    sp.payment_type,
    sp.payment_method::text AS payment_method,
    sp.status::text AS payment_status,
    sp.total_amount,
    sp.base_amount,
    sp.penalties,
    sp.discounts,
    sp.currency,
    sp.fee_type,
    sp.collection_type,
    sp.service_request_id,
    sr.workflow_code,
    sr.solicitud_type,
    sr.reference AS sr_reference,
    COALESCE(sr.entity_code, sp.entity_code) AS entity_code,
    e.name AS entity_name,
    e.entity_type::text AS entity_type,
    e.workflow_codes ? 'BUNDLE_PAYMENT'::text AS is_oms,
    e.ministry_id,
    COALESCE(fi.entity_location_id, sr.entity_location_id, ap_collected.entity_location_id, ap_validated.entity_location_id) AS effective_location_id,
    el.city AS effective_city,
    el.region AS effective_region,
    el.location_name AS effective_location_name,
    el.is_main_office AS effective_is_main,
        CASE
            WHEN fi.entity_location_id IS NOT NULL THEN 'field_inspection'::text
            WHEN sr.entity_location_id IS NOT NULL THEN 'service_request'::text
            WHEN ap_collected.entity_location_id IS NOT NULL THEN 'agent_collected'::text
            WHEN ap_validated.entity_location_id IS NOT NULL THEN 'agent_validated'::text
            ELSE 'unassigned'::text
        END AS location_source,
        CASE
            WHEN sr.source::text = ANY (ARRAY['mobile_app'::character varying, 'mobile'::character varying, 'expo'::character varying]::text[]) THEN 'mobile'::text
            WHEN sr.source::text = ANY (ARRAY['inspector_app'::character varying, 'inspector'::character varying]::text[]) THEN 'inspector'::text
            WHEN sr.source::text = ANY (ARRAY['citizen_wizard'::character varying, 'web'::character varying, 'agent_dashboard'::character varying, 'admin_dashboard'::character varying]::text[]) THEN 'web'::text
            WHEN sr.source IS NULL OR sr.source::text = ''::text THEN 'unknown'::text
            ELSE sr.source::text
        END AS channel
   FROM service_payments sp
     LEFT JOIN service_requests sr ON sr.id = sp.service_request_id
     LEFT JOIN entities e ON e.code::text = COALESCE(sr.entity_code, sp.entity_code)::text
     LEFT JOIN field_inspections fi ON fi.id = sp.field_inspection_id
     LEFT JOIN agent_profiles ap_collected ON ap_collected.user_id = sp.collected_by
     LEFT JOIN agent_profiles ap_validated ON ap_validated.id = sp.validated_by_agent_id
     LEFT JOIN entity_locations el ON el.id = COALESCE(fi.entity_location_id, sr.entity_location_id, ap_collected.entity_location_id, ap_validated.entity_location_id);;

CREATE OR REPLACE VIEW "public"."v_user_activity_audit" AS
 SELECT al.id,
    al.user_id,
    u.email AS user_email,
    u.full_name AS user_name,
    u.role::text AS user_role,
    al.entity_type,
    al.entity_id,
    al.action,
    al.ip_address::text AS ip_address,
    al.created_at,
        CASE
            WHEN al.user_agent ~~* '%expo%'::text OR al.user_agent ~~* '%react-native%'::text OR al.user_agent ~~* '%android%'::text OR al.user_agent ~~* '%iphone%'::text OR al.user_agent ~~* '%ipad%'::text OR al.user_agent ~~* '%mobile%'::text THEN 'mobile'::text
            WHEN al.user_agent ~~* '%inspector%'::text THEN 'inspector'::text
            WHEN al.user_agent ~~* '%mozilla%'::text OR al.user_agent ~~* '%chrome%'::text OR al.user_agent ~~* '%safari%'::text OR al.user_agent ~~* '%edge%'::text THEN 'web'::text
            WHEN al.user_agent IS NULL OR al.user_agent = ''::text THEN 'unknown'::text
            ELSE 'other'::text
        END AS channel,
    al.user_agent,
        CASE
            WHEN al.action::text ~~ 'LOGIN%'::text OR al.action::text = 'LOGOUT'::text THEN 'auth'::text
            WHEN al.action::text ~~* '%PERMISSION%'::text OR al.action::text ~~* 'ROLE%'::text THEN 'rbac'::text
            WHEN al.action::text ~~ 'view_%'::text OR al.action::text ~~ 'list_%'::text THEN 'read'::text
            WHEN al.action::text ~~ 'update_%'::text OR al.action::text ~~ 'edit_%'::text THEN 'write'::text
            WHEN al.action::text ~~ 'delete_%'::text OR al.action::text ~~ 'remove_%'::text THEN 'delete'::text
            WHEN al.action::text ~~ 'dashboard.%'::text THEN 'dashboard'::text
            WHEN al.action::text ~~ 'mission.%'::text THEN 'mission'::text
            WHEN al.action::text ~~ 'service_request.%'::text THEN 'service_request'::text
            WHEN al.action::text ~~ 'payment.%'::text THEN 'payment'::text
            ELSE 'other'::text
        END AS action_category
   FROM audit_logs al
     LEFT JOIN users u ON u.id = al.user_id;;

CREATE OR REPLACE VIEW "public"."v_user_effective_permissions" AS
 WITH role_perm_counts AS (
         SELECT r.id AS role_id,
            r.code AS role_code,
            r.name AS role_name,
            count(rp.permission_id) AS role_perm_count,
            array_agg(DISTINCT p.module_name ORDER BY p.module_name) AS accessible_modules,
            count(
                CASE
                    WHEN p.is_critical THEN 1
                    ELSE NULL::integer
                END) AS critical_perm_count
           FROM roles r
             LEFT JOIN role_permissions rp ON rp.role_id = r.id
             LEFT JOIN permissions p ON p.id = rp.permission_id
          GROUP BY r.id, r.code, r.name
        ), user_override_counts AS (
         SELECT up.user_id,
            count(*) FILTER (WHERE up.granted = true AND (up.expires_at IS NULL OR up.expires_at >= now())) AS explicit_grants,
            count(*) FILTER (WHERE up.granted = false AND (up.expires_at IS NULL OR up.expires_at >= now())) AS explicit_denies,
            count(*) FILTER (WHERE up.expires_at IS NOT NULL AND up.expires_at < now()) AS expired_count
           FROM user_permissions up
          GROUP BY up.user_id
        )
 SELECT u.id AS user_id,
    u.email,
    COALESCE((u.first_name::text || ' '::text) || u.last_name::text, u.email::text) AS full_name,
    u.role::text AS role,
    u.status::text AS status,
    rpc.role_code,
    rpc.role_name,
    COALESCE(rpc.role_perm_count, 0::bigint) AS role_permissions_count,
    COALESCE(rpc.accessible_modules, ARRAY[]::character varying[]) AS accessible_modules,
    COALESCE(rpc.critical_perm_count, 0::bigint) AS critical_permissions_count,
    COALESCE(uoc.explicit_grants, 0::bigint) AS explicit_grants,
    COALESCE(uoc.explicit_denies, 0::bigint) AS explicit_denies,
    COALESCE(uoc.expired_count, 0::bigint) AS expired_overrides,
    COALESCE(rpc.role_perm_count, 0::bigint) + COALESCE(uoc.explicit_grants, 0::bigint) - COALESCE(uoc.explicit_denies, 0::bigint) AS total_effective_permissions,
        CASE
            WHEN (COALESCE(rpc.role_perm_count, 0::bigint) + COALESCE(uoc.explicit_grants, 0::bigint)) > 100 THEN 'FULL_ACCESS'::text
            WHEN (COALESCE(rpc.role_perm_count, 0::bigint) + COALESCE(uoc.explicit_grants, 0::bigint)) > 50 THEN 'ELEVATED'::text
            WHEN (COALESCE(rpc.role_perm_count, 0::bigint) + COALESCE(uoc.explicit_grants, 0::bigint)) > 20 THEN 'STANDARD'::text
            WHEN (COALESCE(rpc.role_perm_count, 0::bigint) + COALESCE(uoc.explicit_grants, 0::bigint)) > 0 THEN 'LIMITED'::text
            ELSE 'NONE'::text
        END AS capability_level,
    u.role::text = 'admin'::text AS is_admin
   FROM users u
     LEFT JOIN roles r_link ON r_link.id = u.role_id
     LEFT JOIN role_perm_counts rpc ON rpc.role_id = u.role_id
     LEFT JOIN user_override_counts uoc ON uoc.user_id = u.id
  WHERE u.status::text <> 'deactivated'::text;;

CREATE OR REPLACE VIEW "public"."v_verificacion_stats" AS
 SELECT count(*) FILTER (WHERE status::text = 'pendiente'::text) AS pendientes,
    count(*) FILTER (WHERE status::text = 'pendiente'::text AND (((verification_data -> 'validacion_cruzada'::text) ->> 'validacion_automatica_posible'::text)::boolean) = true) AS pendientes_auto_validables,
    count(*) FILTER (WHERE status::text = 'aprobado'::text) AS aprobadas,
    count(*) FILTER (WHERE status::text = 'rechazado'::text) AS rechazadas,
    count(*) AS total,
    avg(EXTRACT(epoch FROM processed_at - created_at) / 3600::numeric) FILTER (WHERE processed_at IS NOT NULL) AS avg_processing_hours,
    count(*) FILTER (WHERE verification_data ? 'nombramiento'::text) AS con_nombramiento,
    count(*) FILTER (WHERE verification_data ? 'carnet_funcionario'::text) AS con_carnet,
    count(*) FILTER (WHERE verification_data ? 'contrato_funcionario'::text) AS con_contrato
   FROM verificacion_funcionario;;

CREATE OR REPLACE VIEW "public"."v_verificaciones_pendientes" AS
 SELECT vf.id,
    vf.matricula,
    vf.created_at,
    COALESCE((((vf.verification_data -> 'dip'::text) -> 'extraction'::text) -> 'titular'::text) ->> 'apellidos'::text, ((vf.verification_data -> 'dip'::text) -> 'extraction'::text) ->> 'nombre'::text) AS nombre_dip,
    COALESCE((((vf.verification_data -> 'dip'::text) -> 'extraction'::text) -> 'documento'::text) ->> 'numero_dip'::text, ((vf.verification_data -> 'dip'::text) -> 'extraction'::text) ->> 'numero_dip'::text) AS numero_dip,
        CASE
            WHEN vf.verification_data ? 'nombramiento'::text THEN 'nombramiento'::text
            WHEN vf.verification_data ? 'carnet_funcionario'::text THEN 'carnet_funcionario'::text
            WHEN vf.verification_data ? 'contrato_funcionario'::text THEN 'contrato_funcionario'::text
            ELSE 'desconocido'::text
        END AS tipo_documento_prueba,
    COALESCE((((vf.verification_data -> 'nombramiento'::text) -> 'extraction'::text) -> 'funcionario'::text) ->> 'matricula'::text, (((vf.verification_data -> 'carnet_funcionario'::text) -> 'extraction'::text) -> 'titular'::text) ->> 'matricula'::text, (((vf.verification_data -> 'contrato_funcionario'::text) -> 'extraction'::text) -> 'empleado'::text) ->> 'matricula'::text) AS matricula_extraida,
    ((vf.verification_data -> 'validacion_cruzada'::text) ->> 'nombres_coinciden'::text)::boolean AS nombres_coinciden,
    ((vf.verification_data -> 'validacion_cruzada'::text) ->> 'matriculas_coinciden'::text)::boolean AS matriculas_coinciden,
    ((vf.verification_data -> 'validacion_cruzada'::text) ->> 'validacion_automatica_posible'::text)::boolean AS auto_validable,
    u.id AS user_id,
    u.email AS user_email,
    u.full_name AS user_full_name,
    u.phone_number AS user_phone
   FROM verificacion_funcionario vf
     JOIN users u ON vf.user_id = u.id
  WHERE vf.status::text = 'pendiente'::text
  ORDER BY (((vf.verification_data -> 'validacion_cruzada'::text) ->> 'validacion_automatica_posible'::text)::boolean) DESC NULLS LAST, vf.created_at;;

CREATE OR REPLACE VIEW "public"."v_verification_config_fields" AS
 SELECT dvc.id AS config_id,
    dvc.document_code,
    dvc.identifier_type,
    dvc.source,
    dvc.extraction_paths,
    dvc.expiration_path,
    wdr.extraction_schema_key,
    wdr.document_name_es,
        CASE
            WHEN dvc.document_code::text = 'dip'::text THEN ARRAY['numero_dip'::text, 'id_lateral'::text, 'numero_registro'::text, 'fecha_expiracion'::text, 'fecha_emision'::text]::character varying[]
            WHEN dvc.document_code::text = 'pasaporte_antiguo'::text THEN ARRAY['numero_pasaporte'::text, 'numero_dip'::text, 'fecha_expiracion'::text, 'fecha_expedicion'::text]::character varying[]
            WHEN dvc.document_code::text = 'permiso_residencia'::text THEN ARRAY['numero_nie'::text, 'numero_residencia'::text, 'fecha_expiracion'::text]::character varying[]
            ELSE ARRAY[]::character varying[]
        END AS available_fields
   FROM document_verification_config dvc
     LEFT JOIN workflow_document_requirements wdr ON wdr.document_code::text = dvc.document_code::text
  WHERE dvc.is_active = true;;

CREATE OR REPLACE VIEW "public"."v_verification_dashboard" AS
 SELECT sr.id AS request_id,
    sr.reference AS request_reference,
    sr.workflow_code,
    sr.verification_status,
    sr.verification_details,
    sr.created_at AS request_created_at,
    vq.id AS queue_id,
    vq.status AS queue_status,
    vq.retry_count,
    vq.error_message,
    vq.next_retry_at,
    u.full_name AS user_name,
    u.email AS user_email
   FROM service_requests sr
     LEFT JOIN verification_queue vq ON sr.id = vq.service_request_id
     LEFT JOIN users u ON sr.user_id = u.id
  WHERE sr.verification_status <> 'pending'::verification_status_enum OR vq.id IS NOT NULL
  ORDER BY sr.created_at DESC;;

CREATE OR REPLACE VIEW "public"."v_verification_stats" AS
 SELECT verification_status,
    count(*) AS count,
    count(*) FILTER (WHERE created_at >= (now() - '24:00:00'::interval)) AS last_24h,
    count(*) FILTER (WHERE created_at >= (now() - '7 days'::interval)) AS last_7d
   FROM service_requests
  WHERE status <> 'DRAFT'::service_request_status_enum
  GROUP BY verification_status;;

CREATE OR REPLACE VIEW "public"."v_verified_identifiers_admin" AS
 SELECT id,
    identifier_type,
    source,
    user_id,
    verified_at,
    expires_at,
    is_active,
    verified_by,
    verification_request_id,
    created_at,
    updated_at,
    length(encrypted_value) AS encrypted_value_size,
        CASE
            WHEN encrypted_metadata IS NOT NULL THEN true
            ELSE false
        END AS has_metadata
   FROM verified_identifiers;;

CREATE OR REPLACE VIEW "public"."v_verified_identifiers_stats" AS
 SELECT identifier_type,
    source,
    count(*) AS total,
    count(*) FILTER (WHERE is_active) AS active,
    count(*) FILTER (WHERE NOT is_active) AS inactive,
    count(*) FILTER (WHERE expires_at < now() AND is_active) AS expired,
    min(verified_at) AS oldest_verification,
    max(verified_at) AS newest_verification,
    count(DISTINCT user_id) AS unique_users
   FROM verified_identifiers
  GROUP BY identifier_type, source;;

CREATE OR REPLACE VIEW "public"."v_workflow_supplements" AS
 SELECT wsc.workflow_code,
    ts.code AS supplement_code,
    ts.name_es AS supplement_name,
    ts.amount AS unit_price,
    wsc.quantity_per_request,
    ts.amount * wsc.quantity_per_request::numeric AS subtotal,
    wsc.is_required,
    wsc.is_active
   FROM workflow_supplement_config wsc
     JOIN tariff_supplements ts ON ts.code::text = wsc.supplement_code::text
  WHERE wsc.is_active = true AND ts.is_active = true
  ORDER BY wsc.workflow_code, ts.name_es;;

CREATE OR REPLACE VIEW "public"."v_workflow_tariffs_summary" AS
 SELECT wt.workflow_code,
    wt.solicitud_type,
    wt.tariff_type,
    wt.amount AS base_amount,
    wt.percentage_rate,
    COALESCE(supp.supplements_total, 0::numeric) AS supplements_total,
        CASE
            WHEN wt.tariff_type::text = 'FIXED'::text THEN wt.amount + COALESCE(supp.supplements_total, 0::numeric)
            WHEN wt.tariff_type::text = 'PERCENTAGE'::text THEN COALESCE(supp.supplements_total, 0::numeric)
            ELSE COALESCE(supp.supplements_total, 0::numeric)
        END AS total_amount,
    wt.currency,
    wt.legal_reference,
    wt.effective_from,
    wt.is_active
   FROM workflow_tariffs wt
     LEFT JOIN LATERAL ( SELECT sum(ts.amount * wsc.quantity_per_request::numeric) AS supplements_total
           FROM workflow_supplement_config wsc
             JOIN tariff_supplements ts ON ts.code::text = wsc.supplement_code::text
          WHERE wsc.workflow_code::text = wt.workflow_code::text AND wsc.is_active = true AND ts.is_active = true) supp ON true
  WHERE wt.is_active = true AND (wt.effective_to IS NULL OR wt.effective_to > CURRENT_DATE)
  ORDER BY wt.workflow_code, wt.solicitud_type;;

CREATE OR REPLACE VIEW "public"."v_workflows_hierarchy" AS
 SELECT w.code,
    w.name_es,
    w.description_es,
    w.category,
    w.entity_code,
    w.workflow_type,
    w.requires_agent_validation,
    w.requires_appointment,
    w.is_generic,
    COALESCE(w.is_parent, false) AS is_parent,
    w.parent_workflow_code,
    COALESCE(w.tags, '[]'::jsonb) AS tags,
    w.sla_hours,
    w.display_order,
    w.is_active,
    pw.name_es AS parent_name_es,
    ( SELECT count(*) AS count
           FROM workflow_document_requirements
          WHERE workflow_document_requirements.workflow_code::text = w.code::text) AS documents_count,
    ( SELECT count(*) AS count
           FROM workflow_tariffs
          WHERE workflow_tariffs.workflow_code::text = w.code::text AND workflow_tariffs.is_active = true) AS tariffs_count,
    ( SELECT jsonb_agg(jsonb_build_object('solicitud_type', wt.solicitud_type, 'amount', wt.amount, 'tariff_type', wt.tariff_type, 'percentage_rate', wt.percentage_rate)) AS jsonb_agg
           FROM workflow_tariffs wt
          WHERE wt.workflow_code::text = w.code::text AND wt.is_active = true) AS tariffs
   FROM workflows w
     LEFT JOIN workflows pw ON w.parent_workflow_code::text = pw.code::text
  ORDER BY w.display_order, w.code;;

