CREATE OR REPLACE VIEW "public"."vw_agent_rbac_roles" AS
 SELECT r.id,
    r.code,
    r.name,
    r.description,
    r.entity_type,
    count(rp.permission_id) AS permission_count,
    array_agg(p.name ORDER BY p.name) FILTER (WHERE p.name IS NOT NULL) AS permissions
   FROM roles r
     LEFT JOIN role_permissions rp ON r.id = rp.role_id
     LEFT JOIN permissions p ON rp.permission_id = p.id
  WHERE r.entity_type::text = 'agent'::text AND r.is_system = true
  GROUP BY r.id, r.code, r.name, r.description, r.entity_type
  ORDER BY r.name;;

CREATE OR REPLACE VIEW "public"."vw_agents" AS
 SELECT u.id AS user_id,
    u.email,
    u.full_name,
    u.first_name,
    u.last_name,
    u.phone_number,
    u.role AS user_role,
    ap.id AS agent_profile_id,
    ap.agent_type,
    ap.is_supervisor,
    ap.entity_id,
    e.code AS entity_code,
    e.name AS entity_name,
    e.ministry_id AS entity_ministry_id,
    ap.entity_location_id,
    el.location_name,
    el.city AS location_city,
    el.region AS location_region,
    ap.ministry_id,
    m.ministry_code,
    m.name_es AS ministry_name,
        CASE
            WHEN m.ministry_code::text = 'DGI'::text THEN 'dgi'::text
            WHEN m.ministry_code::text = 'TESORO'::text THEN 'treasury'::text
            WHEN ap.agent_type::text = 'entity_agent'::text THEN 'entity'::text
            ELSE 'ministry'::text
        END AS agent_category,
    ap.can_approve_unlimited,
    ap.max_approval_amount,
    ap.can_escalate,
    ap.can_assign_tasks,
    ap.can_reassign,
    ap.specializations,
    ap.working_hours_start,
    ap.working_hours_end,
    ap.working_days,
    ap.is_active AS agent_is_active,
    ap.is_backup_agent,
    aw.id AS workload_id,
    aw.current_assignments,
    aw.max_concurrent_assignments,
    aw.capacity_percentage,
    aw.workload_status,
    aw.availability,
    aw.last_assignment_at,
    aw.last_completion_at
   FROM users u
     JOIN agent_profiles ap ON u.id = ap.user_id
     LEFT JOIN entities e ON ap.entity_id = e.id
     LEFT JOIN entity_locations el ON ap.entity_location_id = el.id
     LEFT JOIN ministries m ON ap.ministry_id = m.id
     LEFT JOIN agent_workloads aw ON ap.id = aw.agent_profile_id;;

