-- ---------- 14. Materialized views ----------
CREATE MATERIALIZED VIEW IF NOT EXISTS "public"."categories_with_services" AS
 SELECT c.id,
    c.category_code,
    c.name_es,
    c.description_es,
    c.icon,
    c.color,
    c.ministry_id,
    c.sector_id,
    m.name_es AS ministry_name,
    s.name_es AS sector_name,
    count(fs.id)::integer AS service_count,
    now() AS last_updated
   FROM categories c
     LEFT JOIN ministries m ON c.ministry_id = m.id
     LEFT JOIN sectors s ON c.sector_id = s.id
     LEFT JOIN fiscal_services fs ON fs.category_id = c.id AND fs.status = 'active'::service_status_enum
  WHERE c.is_active = true
  GROUP BY c.id, c.category_code, c.name_es, c.description_es, c.icon, c.color, c.ministry_id, c.sector_id, m.name_es, s.name_es
  ORDER BY (count(fs.id)::integer) DESC, c.name_es;
WITH NO DATA;

CREATE MATERIALIZED VIEW IF NOT EXISTS "public"."effective_permissions_mv" AS
 WITH RECURSIVE role_chain AS (
         SELECT u.id AS user_id,
            r.id AS role_id,
            r.parent_role_id
           FROM users u
             JOIN roles r ON r.id = u.role_id
          WHERE u.status <> 'deactivated'::user_status_enum
        UNION ALL
         SELECT rc.user_id,
            parent.id AS role_id,
            parent.parent_role_id
           FROM roles parent
             JOIN role_chain rc ON rc.parent_role_id = parent.id
        ), role_perms AS (
         SELECT DISTINCT rc.user_id,
            p.name AS permission_name
           FROM role_chain rc
             JOIN role_permissions rp ON rp.role_id = rc.role_id AND rp.granted = true
             JOIN permissions p ON p.id = rp.permission_id
        ), user_denies AS (
         SELECT up.user_id,
            p.name AS permission_name
           FROM user_permissions up
             JOIN permissions p ON p.id = up.permission_id
          WHERE up.granted = false AND (up.expires_at IS NULL OR up.expires_at >= now())
        ), user_grants AS (
         SELECT up.user_id,
            p.name AS permission_name
           FROM user_permissions up
             JOIN permissions p ON p.id = up.permission_id
          WHERE up.granted = true AND (up.expires_at IS NULL OR up.expires_at >= now())
        )
 SELECT role_perms.user_id,
    role_perms.permission_name
   FROM role_perms
  WHERE NOT ((role_perms.user_id, role_perms.permission_name::text) IN ( SELECT user_denies.user_id,
            user_denies.permission_name
           FROM user_denies))
UNION
 SELECT user_grants.user_id,
    user_grants.permission_name
   FROM user_grants;
WITH NO DATA;

CREATE MATERIALIZED VIEW IF NOT EXISTS "public"."homepage_stats" AS
 SELECT ( SELECT count(*)::integer AS count
           FROM fiscal_services
          WHERE fiscal_services.status = 'active'::service_status_enum) AS total_services,
    ( SELECT count(*)::integer AS count
           FROM ministries
          WHERE ministries.is_active = true) AS total_ministries,
    ( SELECT count(*)::integer AS count
           FROM categories
          WHERE categories.is_active = true) AS total_categories,
    ( SELECT count(*)::integer AS count
           FROM sectors
          WHERE sectors.is_active = true) AS total_sectors,
    now() AS last_updated;
WITH NO DATA;

CREATE MATERIALIZED VIEW IF NOT EXISTS "public"."ministries_with_stats" AS
 SELECT m.id,
    m.ministry_code,
    m.name_es,
    m.description_es,
    m.website_url,
    m.is_active,
    count(DISTINCT c.id)::integer AS categories_count,
    count(DISTINCT fs.id)::integer AS services_count,
    now() AS last_updated
   FROM ministries m
     LEFT JOIN categories c ON c.ministry_id = m.id AND c.is_active = true
     LEFT JOIN fiscal_services fs ON fs.category_id = c.id AND fs.status = 'active'::service_status_enum
  WHERE m.is_active = true
  GROUP BY m.id, m.ministry_code, m.name_es, m.description_es, m.website_url, m.is_active
  ORDER BY (count(DISTINCT fs.id)::integer) DESC, m.name_es;
WITH NO DATA;

CREATE MATERIALIZED VIEW IF NOT EXISTS "public"."mv_agent_daily_workload" AS
 SELECT pva.created_at::date AS report_date,
    pva.agent_profile_id,
    u.full_name AS agent_name,
    count(*) FILTER (WHERE pva.action = 'approve'::agent_action_type) AS approved,
    count(*) FILTER (WHERE pva.action = 'reject'::agent_action_type) AS rejected,
    count(*) AS total_actions,
    avg(pva.action_duration_seconds) FILTER (WHERE pva.action_duration_seconds IS NOT NULL) AS avg_duration_seconds,
    min(pva.action_duration_seconds) FILTER (WHERE pva.action_duration_seconds IS NOT NULL) AS min_duration_seconds,
    max(pva.action_duration_seconds) FILTER (WHERE pva.action_duration_seconds IS NOT NULL) AS max_duration_seconds,
    percentile_cont(0.5::double precision) WITHIN GROUP (ORDER BY (pva.action_duration_seconds::double precision)) FILTER (WHERE pva.action_duration_seconds IS NOT NULL) AS p50_duration_seconds
   FROM payment_validation_audit pva
     JOIN agent_profiles ap ON ap.id = pva.agent_profile_id
     JOIN users u ON u.id = ap.user_id
  WHERE pva.action = ANY (ARRAY['approve'::agent_action_type, 'reject'::agent_action_type])
  GROUP BY (pva.created_at::date), pva.agent_profile_id, u.full_name;
WITH NO DATA;

CREATE MATERIALIZED VIEW IF NOT EXISTS "public"."mv_company_analytics" AS
 SELECT 1 AS id,
    ( SELECT COALESCE(jsonb_agg(row_to_json(sub.*)::jsonb ORDER BY sub.zone_code, sub.regime), '[]'::jsonb) AS "coalesce"
           FROM ( SELECT cz.zone_code,
                    cz.name_es AS zone_name,
                    c.regimen_fiscal AS regime,
                    count(*) AS count,
                    COALESCE(sum(cl.total_amount), 0::numeric) AS total_amount,
                    COALESCE(sum(cl.amount_paid), 0::numeric) AS paid_amount,
                    COALESCE(sum(cl.total_amount - cl.amount_paid), 0::numeric) AS debt
                   FROM companies c
                     LEFT JOIN commerce_zones cz ON c.zone_id = cz.id
                     LEFT JOIN commercial_licenses cl ON cl.company_id = c.id AND cl.fiscal_year = EXTRACT(year FROM now())::integer
                  WHERE c.is_active = true
                  GROUP BY cz.zone_code, cz.name_es, c.regimen_fiscal) sub) AS by_zone_regime,
    ( SELECT COALESCE(jsonb_agg(row_to_json(sub.*)::jsonb ORDER BY sub.count DESC), '[]'::jsonb) AS "coalesce"
           FROM ( SELECT c.forma_juridica,
                    count(*) AS count,
                    count(cl.id) AS with_license,
                    COALESCE(sum(cl.total_amount), 0::numeric) AS total_amount
                   FROM companies c
                     LEFT JOIN commercial_licenses cl ON cl.company_id = c.id AND cl.fiscal_year = EXTRACT(year FROM now())::integer
                  WHERE c.is_active = true AND c.forma_juridica IS NOT NULL
                  GROUP BY c.forma_juridica) sub) AS by_forma_juridica,
    ( SELECT COALESCE(jsonb_agg(row_to_json(sub.*)::jsonb ORDER BY sub.companies DESC), '[]'::jsonb) AS "coalesce"
           FROM ( SELECT ct.name AS city_name,
                    ct.provincia,
                    cz.zone_code,
                    count(c.id) AS companies,
                    count(cl.id) AS licenses,
                    COALESCE(sum(cl.total_amount - cl.amount_paid), 0::numeric) AS debt,
                        CASE
                            WHEN COALESCE(sum(cl.total_amount), 0::numeric) > 0::numeric THEN round(sum(cl.amount_paid) * 100.0 / sum(cl.total_amount), 1)
                            ELSE 0::numeric
                        END AS recovery_pct
                   FROM companies c
                     JOIN cities ct ON c.city_id = ct.id
                     LEFT JOIN commerce_zones cz ON c.zone_id = cz.id
                     LEFT JOIN commercial_licenses cl ON cl.company_id = c.id AND cl.fiscal_year = EXTRACT(year FROM now())::integer
                  WHERE c.is_active = true
                  GROUP BY ct.name, ct.provincia, cz.zone_code) sub) AS by_city,
    ( SELECT COALESCE(jsonb_agg(row_to_json(sub.*)::jsonb ORDER BY sub.total_amount DESC), '[]'::jsonb) AS "coalesce"
           FROM ( SELECT lo.fee_type,
                    count(DISTINCT cl.company_id) AS companies,
                    count(lo.id) AS obligations,
                    COALESCE(sum(lo.amount), 0::numeric) AS total_amount,
                    COALESCE(sum(lo.amount) FILTER (WHERE lo.status::text = 'paid'::text), 0::numeric) AS paid,
                    COALESCE(sum(lo.amount) FILTER (WHERE lo.status::text = 'overdue'::text), 0::numeric) AS overdue,
                    COALESCE(sum(lo.penalty_amount), 0::numeric) AS penalties
                   FROM license_obligations lo
                     JOIN commercial_licenses cl ON lo.license_id = cl.id
                  WHERE cl.fiscal_year = EXTRACT(year FROM now())::integer
                  GROUP BY lo.fee_type) sub) AS debt_by_fee_type,
    ( SELECT COALESCE(jsonb_agg(row_to_json(sub.*)::jsonb ORDER BY sub.debt DESC), '[]'::jsonb) AS "coalesce"
           FROM ( SELECT c.id,
                    c.legal_name,
                    c.nif,
                    c.registration_number,
                    c.regimen_fiscal,
                    cz.zone_code,
                    sum(cl.total_amount - cl.amount_paid) AS debt,
                    sum(cl.total_amount) AS total_amount,
                        CASE
                            WHEN sum(cl.total_amount) > 0::numeric THEN round(sum(cl.amount_paid) * 100.0 / sum(cl.total_amount), 1)
                            ELSE 0::numeric
                        END AS recovery_pct
                   FROM companies c
                     JOIN commercial_licenses cl ON cl.company_id = c.id
                     LEFT JOIN commerce_zones cz ON c.zone_id = cz.id
                  WHERE cl.fiscal_year = EXTRACT(year FROM now())::integer AND (cl.total_amount - cl.amount_paid) > 0::numeric
                  GROUP BY c.id, c.legal_name, c.nif, c.registration_number, c.regimen_fiscal, cz.zone_code
                  ORDER BY (sum(cl.total_amount - cl.amount_paid)) DESC
                 LIMIT 10) sub) AS top_debtors,
    ( SELECT COALESCE(jsonb_agg(row_to_json(sub.*)::jsonb ORDER BY sub.month), '[]'::jsonb) AS "coalesce"
           FROM ( SELECT to_char(companies.created_at, 'YYYY-MM'::text) AS month,
                    count(*) AS created,
                    count(*) FILTER (WHERE companies.regimen_fiscal::text = 'bundle'::text) AS bundle,
                    count(*) FILTER (WHERE companies.regimen_fiscal::text = 'declarativo'::text) AS declarativo,
                    count(*) FILTER (WHERE companies.is_verified) AS verified
                   FROM companies
                  WHERE companies.created_at >= (now() - '1 year'::interval)
                  GROUP BY (to_char(companies.created_at, 'YYYY-MM'::text))) sub) AS monthly_trend,
    now() AS refreshed_at;
WITH NO DATA;

CREATE MATERIALIZED VIEW IF NOT EXISTS "public"."mv_company_global_stats" AS
 SELECT count(*) AS total_companies,
    count(*) FILTER (WHERE is_active) AS active_companies,
    count(*) FILTER (WHERE is_verified) AS verified_companies,
    count(*) FILTER (WHERE NOT is_active) AS inactive_companies,
    count(*) FILTER (WHERE regimen_fiscal::text = 'bundle'::text) AS bundle_count,
    count(*) FILTER (WHERE regimen_fiscal::text = 'declarativo'::text) AS declarativo_count,
    count(*) FILTER (WHERE regimen_fiscal::text = 'exento'::text) AS exento_count,
    count(*) FILTER (WHERE regimen_fiscal::text = 'pendiente'::text) AS pendiente_count,
    count(*) FILTER (WHERE nif IS NOT NULL) AS with_nif,
    count(*) FILTER (WHERE registration_number IS NOT NULL) AS with_reg_number,
    count(*) FILTER (WHERE zone_id IS NOT NULL) AS with_zone,
    count(*) FILTER (WHERE nif IS NULL AND registration_number IS NULL) AS missing_identifier,
    ( SELECT count(*) AS count
           FROM commercial_licenses
          WHERE commercial_licenses.status::text = ANY (ARRAY['open'::character varying, 'partial'::character varying]::text[])) AS active_licenses,
    COALESCE(( SELECT sum(commercial_licenses.total_amount) AS sum
           FROM commercial_licenses), 0::numeric) AS total_obligations_amount,
    COALESCE(( SELECT sum(commercial_licenses.amount_paid) AS sum
           FROM commercial_licenses), 0::numeric) AS total_paid_amount,
    COALESCE(( SELECT sum(commercial_licenses.total_amount - commercial_licenses.amount_paid) AS sum
           FROM commercial_licenses
          WHERE commercial_licenses.total_amount > commercial_licenses.amount_paid), 0::numeric) AS total_debt,
        CASE
            WHEN COALESCE(( SELECT sum(commercial_licenses.total_amount) AS sum
               FROM commercial_licenses), 0::numeric) > 0::numeric THEN round(COALESCE(( SELECT sum(commercial_licenses.amount_paid) AS sum
               FROM commercial_licenses), 0::numeric) * 100.0 / COALESCE(( SELECT sum(commercial_licenses.total_amount) AS sum
               FROM commercial_licenses), 1::numeric), 1)
            ELSE 0::numeric
        END AS recovery_rate_pct,
    now() AS refreshed_at
   FROM companies;
WITH NO DATA;

CREATE MATERIALIZED VIEW IF NOT EXISTS "public"."mv_company_stats_by_zone" AS
 SELECT cz.id AS zone_id,
    cz.zone_code,
    cz.zone_tier,
    cz.name_es AS zone_name,
    count(c.id) AS total_companies,
    count(c.id) FILTER (WHERE c.is_active) AS active_companies,
    count(c.id) FILTER (WHERE c.is_verified) AS verified_companies,
    count(c.id) FILTER (WHERE NOT c.is_active) AS inactive_companies,
    count(c.id) FILTER (WHERE c.is_active AND NOT c.is_verified) AS pending_verification,
    count(c.id) FILTER (WHERE c.regimen_fiscal::text = 'bundle'::text) AS bundle_count,
    count(c.id) FILTER (WHERE c.regimen_fiscal::text = 'declarativo'::text) AS declarativo_count,
    count(c.id) FILTER (WHERE c.regimen_fiscal::text = 'exento'::text) AS exento_count,
    count(c.id) FILTER (WHERE c.regimen_fiscal::text = 'pendiente'::text) AS pendiente_count,
    count(c.id) FILTER (WHERE c.nif IS NOT NULL) AS with_nif,
    count(c.id) FILTER (WHERE c.registration_number IS NOT NULL) AS with_reg_number,
    count(c.id) FILTER (WHERE c.zone_id IS NOT NULL) AS with_zone,
    count(c.id) FILTER (WHERE c.nif IS NULL AND c.registration_number IS NULL) AS missing_identifier,
    count(DISTINCT cl.id) AS active_licenses,
    COALESCE(sum(cl.total_amount), 0::numeric) AS total_obligations_amount,
    COALESCE(sum(cl.amount_paid), 0::numeric) AS total_paid_amount,
    COALESCE(sum(cl.total_amount) - sum(cl.amount_paid), 0::numeric) AS total_debt,
        CASE
            WHEN COALESCE(sum(cl.total_amount), 0::numeric) > 0::numeric THEN round(COALESCE(sum(cl.amount_paid), 0::numeric) * 100.0 / sum(cl.total_amount), 1)
            ELSE 0::numeric
        END AS recovery_rate_pct,
    now() AS refreshed_at
   FROM commerce_zones cz
     LEFT JOIN companies c ON c.zone_id = cz.id
     LEFT JOIN commercial_licenses cl ON cl.company_id = c.id
  GROUP BY cz.id, cz.zone_code, cz.zone_tier, cz.name_es;
WITH NO DATA;

CREATE MATERIALIZED VIEW IF NOT EXISTS "public"."mv_fiscal_services_catalog" AS
 SELECT fs.id,
    fs.service_code,
    fs.name_es,
    fs.description_es,
    fs.service_type,
    fs.calculation_method,
    fs.status,
    fs.tasa_expedicion,
    fs.tasa_renovacion,
    fs.processing_time_days,
    fs.priority,
    fs.complexity_level,
    fs.validity_period_months,
    fs.parent_service_id,
    fs.view_count,
    fs.calculation_count,
    fs.payment_count,
    fs.favorite_count,
    fs.created_at,
    fs.updated_at,
    c.id AS category_id,
    c.category_code,
    c.name_es AS category_name,
    s.id AS sector_id,
    s.sector_code,
    s.name_es AS sector_name,
    m.id AS ministry_id,
    m.ministry_code,
    m.name_es AS ministry_name
   FROM fiscal_services fs
     JOIN categories c ON fs.category_id = c.id
     LEFT JOIN sectors s ON c.sector_id = s.id
     LEFT JOIN ministries m ON s.ministry_id = m.id;
WITH NO DATA;

CREATE MATERIALIZED VIEW IF NOT EXISTS "public"."mv_inspection_zone_analytics" AS
 SELECT fi.entity_id,
    fi.zone_id,
    cz.zone_code,
    cz.name_es AS zone_name,
    cz.zone_tier,
    date_trunc('week'::text, fi.inspection_date::timestamp with time zone)::date AS week_start,
    count(*)::integer AS inspections,
    count(*) FILTER (WHERE fi.result::text = 'conforme'::text)::integer AS conforme,
    count(*) FILTER (WHERE fi.result::text = 'non_conforme'::text)::integer AS non_conforme,
    count(*) FILTER (WHERE fi.payment_collected = true)::integer AS collections,
    COALESCE(sum(fi.payment_amount) FILTER (WHERE fi.payment_collected = true), 0::numeric)::numeric(15,2) AS collected_amount,
    count(*) FILTER (WHERE fi.mise_en_demeure_issued = true)::integer AS med_count,
    count(*) FILTER (WHERE fi.seal_applied = true)::integer AS seal_count,
    count(DISTINCT fi.agent_id)::integer AS agents_active,
    round(avg(fi.duration_minutes) FILTER (WHERE fi.duration_minutes IS NOT NULL), 1) AS avg_duration_minutes,
        CASE
            WHEN count(*) > 0 THEN round(100.0 * count(*) FILTER (WHERE fi.result::text = 'conforme'::text)::numeric / count(*)::numeric, 1)
            ELSE 0::numeric
        END AS conformity_rate,
        CASE
            WHEN count(*) > 0 THEN round(100.0 * count(*) FILTER (WHERE fi.payment_collected = true)::numeric / count(*)::numeric, 1)
            ELSE 0::numeric
        END AS collection_rate
   FROM field_inspections fi
     LEFT JOIN commerce_zones cz ON cz.id = fi.zone_id
  WHERE fi.status::text <> 'cancelled'::text
  GROUP BY fi.entity_id, fi.zone_id, cz.zone_code, cz.name_es, cz.zone_tier, (date_trunc('week'::text, fi.inspection_date::timestamp with time zone)::date);
WITH NO DATA;

CREATE MATERIALIZED VIEW IF NOT EXISTS "public"."mv_obligation_stats_by_ministry" AS
 SELECT lo.ministry_id,
    lo.fee_type,
    cz.id AS zone_id,
    cz.zone_code,
    count(DISTINCT cl.company_id) AS companies_count,
    count(lo.id) AS obligations_count,
    count(lo.id) FILTER (WHERE lo.status::text = 'paid'::text) AS paid_count,
    count(lo.id) FILTER (WHERE lo.status::text = 'pending'::text) AS pending_count,
    count(lo.id) FILTER (WHERE lo.status::text = 'overdue'::text) AS overdue_count,
    COALESCE(sum(lo.amount), 0::numeric) AS total_amount,
    COALESCE(sum(lo.amount) FILTER (WHERE lo.status::text = 'paid'::text), 0::numeric) AS paid_amount,
    COALESCE(sum(lo.amount) FILTER (WHERE lo.status::text = 'overdue'::text), 0::numeric) AS overdue_amount,
    COALESCE(sum(lo.penalty_amount), 0::numeric) AS total_penalties,
        CASE
            WHEN COALESCE(sum(lo.amount), 0::numeric) > 0::numeric THEN round(COALESCE(sum(lo.amount) FILTER (WHERE lo.status::text = 'paid'::text), 0::numeric) * 100.0 / sum(lo.amount), 1)
            ELSE 0::numeric
        END AS recovery_rate_pct,
    now() AS refreshed_at
   FROM license_obligations lo
     JOIN commercial_licenses cl ON lo.license_id = cl.id
     JOIN companies c ON cl.company_id = c.id
     LEFT JOIN commerce_zones cz ON c.zone_id = cz.id
  WHERE cl.fiscal_year = EXTRACT(year FROM now())::integer
  GROUP BY lo.ministry_id, lo.fee_type, cz.id, cz.zone_code;
WITH NO DATA;

CREATE MATERIALIZED VIEW IF NOT EXISTS "public"."mv_reconciliation_stats" AS
 SELECT date(created_at) AS report_date,
    bank_code,
    count(*) AS total_transactions,
    count(*) FILTER (WHERE status::text = 'reconciled'::text) AS reconciled_count,
    count(*) FILTER (WHERE status::text = 'unreconciled'::text) AS unreconciled_count,
    count(*) FILTER (WHERE status::text = 'failed'::text) AS failed_count,
    sum(amount) AS total_amount,
    sum(amount) FILTER (WHERE status::text = 'reconciled'::text) AS reconciled_amount,
    sum(amount) FILTER (WHERE status::text = 'unreconciled'::text) AS unreconciled_amount,
        CASE
            WHEN count(*) > 0 THEN round(count(*) FILTER (WHERE status::text = 'reconciled'::text)::numeric / count(*)::numeric * 100::numeric, 2)
            ELSE 0::numeric
        END AS reconciliation_rate,
    avg(EXTRACT(epoch FROM reconciled_at - created_at) / 3600::numeric) FILTER (WHERE reconciled_at IS NOT NULL) AS avg_reconciliation_hours
   FROM bank_transactions bt
  WHERE created_at >= (CURRENT_DATE - '90 days'::interval)
  GROUP BY (date(created_at)), bank_code;
WITH NO DATA;

CREATE MATERIALIZED VIEW IF NOT EXISTS "public"."mv_request_telemetry_hourly" AS
 SELECT date_trunc('hour'::text, "timestamp") AS hour,
    geo_country,
    device_type,
    user_role,
    method,
    sum(100.0 / sampled_pct)::bigint AS request_count_est,
    count(*) AS request_count_raw,
    count(DISTINCT ip_address) AS unique_ips,
    count(DISTINCT user_id) FILTER (WHERE user_id IS NOT NULL) AS unique_users,
    sum((status_code >= 400)::integer) AS error_count,
    sum((status_code >= 500)::integer) AS server_error_count,
    sum(is_bot::integer) AS bot_count,
    sum(is_suspicious::integer) AS suspicious_count,
    percentile_cont(0.50::double precision) WITHIN GROUP (ORDER BY (latency_ms::double precision)) AS p50_latency_ms,
    percentile_cont(0.95::double precision) WITHIN GROUP (ORDER BY (latency_ms::double precision)) AS p95_latency_ms,
    percentile_cont(0.99::double precision) WITHIN GROUP (ORDER BY (latency_ms::double precision)) AS p99_latency_ms,
    sum(response_bytes) AS total_response_bytes
   FROM request_telemetry
  WHERE "timestamp" > (now() - '90 days'::interval)
  GROUP BY (date_trunc('hour'::text, "timestamp")), geo_country, device_type, user_role, method;
WITH NO DATA;

CREATE MATERIALIZED VIEW IF NOT EXISTS "public"."mv_services_translated" AS
 SELECT fs.id,
    fs.service_code,
    fs.name_es,
    fs.description_es,
    fs.service_type,
    fs.status,
    fs.category_id,
    fs.tasa_expedicion,
    fs.tasa_renovacion,
    fs.processing_time_days,
    fs.calculation_method,
    fs.view_count,
    fs.calculation_count,
    c.category_code,
    c.name_es AS category_name_es,
    s.sector_code,
    s.name_es AS sector_name_es,
    m.id AS ministry_id,
    m.ministry_code,
    m.name_es AS ministry_name_es,
    et_name_fr.translation_text AS name_fr,
    et_desc_fr.translation_text AS description_fr,
    et_cat_fr.translation_text AS category_name_fr,
    et_sec_fr.translation_text AS sector_name_fr,
    et_min_fr.translation_text AS ministry_name_fr,
    et_name_en.translation_text AS name_en,
    et_desc_en.translation_text AS description_en,
    et_cat_en.translation_text AS category_name_en,
    et_sec_en.translation_text AS sector_name_en,
    et_min_en.translation_text AS ministry_name_en
   FROM fiscal_services fs
     LEFT JOIN categories c ON fs.category_id = c.id
     LEFT JOIN sectors s ON c.sector_id = s.id
     LEFT JOIN ministries m ON s.ministry_id = m.id
     LEFT JOIN entity_translations et_name_fr ON et_name_fr.entity_type = 'service'::translatable_entity_type AND et_name_fr.entity_code::text = fs.service_code::text AND et_name_fr.field_name::text = 'name'::text AND et_name_fr.language_code::text = 'fr'::text
     LEFT JOIN entity_translations et_desc_fr ON et_desc_fr.entity_type = 'service'::translatable_entity_type AND et_desc_fr.entity_code::text = fs.service_code::text AND et_desc_fr.field_name::text = 'description'::text AND et_desc_fr.language_code::text = 'fr'::text
     LEFT JOIN entity_translations et_cat_fr ON et_cat_fr.entity_type = 'category'::translatable_entity_type AND et_cat_fr.entity_code::text = c.category_code::text AND et_cat_fr.field_name::text = 'name'::text AND et_cat_fr.language_code::text = 'fr'::text
     LEFT JOIN entity_translations et_sec_fr ON et_sec_fr.entity_type = 'sector'::translatable_entity_type AND et_sec_fr.entity_code::text = s.sector_code::text AND et_sec_fr.field_name::text = 'name'::text AND et_sec_fr.language_code::text = 'fr'::text
     LEFT JOIN entity_translations et_min_fr ON et_min_fr.entity_type = 'ministry'::translatable_entity_type AND et_min_fr.entity_code::text = m.ministry_code::text AND et_min_fr.field_name::text = 'name'::text AND et_min_fr.language_code::text = 'fr'::text
     LEFT JOIN entity_translations et_name_en ON et_name_en.entity_type = 'service'::translatable_entity_type AND et_name_en.entity_code::text = fs.service_code::text AND et_name_en.field_name::text = 'name'::text AND et_name_en.language_code::text = 'en'::text
     LEFT JOIN entity_translations et_desc_en ON et_desc_en.entity_type = 'service'::translatable_entity_type AND et_desc_en.entity_code::text = fs.service_code::text AND et_desc_en.field_name::text = 'description'::text AND et_desc_en.language_code::text = 'en'::text
     LEFT JOIN entity_translations et_cat_en ON et_cat_en.entity_type = 'category'::translatable_entity_type AND et_cat_en.entity_code::text = c.category_code::text AND et_cat_en.field_name::text = 'name'::text AND et_cat_en.language_code::text = 'en'::text
     LEFT JOIN entity_translations et_sec_en ON et_sec_en.entity_type = 'sector'::translatable_entity_type AND et_sec_en.entity_code::text = s.sector_code::text AND et_sec_en.field_name::text = 'name'::text AND et_sec_en.language_code::text = 'en'::text
     LEFT JOIN entity_translations et_min_en ON et_min_en.entity_type = 'ministry'::translatable_entity_type AND et_min_en.entity_code::text = m.ministry_code::text AND et_min_en.field_name::text = 'name'::text AND et_min_en.language_code::text = 'en'::text
  WHERE fs.status = 'active'::service_status_enum;
WITH NO DATA;

CREATE MATERIALIZED VIEW IF NOT EXISTS "public"."mv_treasury_daily_kpis" AS
 SELECT date(sp.created_at) AS report_date,
    sp.payment_method::text AS payment_method,
    sp.entity_code,
    e.name AS entity_name,
    e.ministry_id,
    m.name_es AS ministry_name,
    sr.workflow_code AS service_code,
    COALESCE(fs.name_es, sr.workflow_code) AS service_name,
    sr.workflow_code,
    sr.solicitud_type,
    count(*) AS payment_count,
    count(*) FILTER (WHERE sp.workflow_status = 'completed'::payment_workflow_status) AS completed_count,
    count(*) FILTER (WHERE sp.workflow_status = ANY (ARRAY['rejected_by_agent'::payment_workflow_status, 'cancelled_by_agent'::payment_workflow_status])) AS rejected_count,
    count(*) FILTER (WHERE sp.workflow_status = 'cancelled_by_user'::payment_workflow_status) AS cancelled_by_user_count,
    sum(sp.total_amount) FILTER (WHERE sp.workflow_status = 'completed'::payment_workflow_status) AS total_amount,
    avg(sp.total_amount) FILTER (WHERE sp.workflow_status = 'completed'::payment_workflow_status) AS avg_amount,
    min(sp.total_amount) FILTER (WHERE sp.workflow_status = 'completed'::payment_workflow_status) AS min_amount,
    max(sp.total_amount) FILTER (WHERE sp.workflow_status = 'completed'::payment_workflow_status) AS max_amount,
    avg(EXTRACT(epoch FROM COALESCE(sp.validated_at, sp.paid_at, now()) - sp.created_at) / 60::numeric) FILTER (WHERE (sp.workflow_status = ANY (ARRAY['completed'::payment_workflow_status, 'approved_by_agent'::payment_workflow_status])) AND sp.validated_at IS NOT NULL) AS avg_processing_minutes,
    count(*) FILTER (WHERE sp.sla_escalated = true) AS sla_breached_count,
    count(*) FILTER (WHERE sp.sla_warning_sent = true) AS sla_warning_count
   FROM service_payments sp
     LEFT JOIN entities e ON e.code::text = sp.entity_code::text
     LEFT JOIN ministries m ON m.id = e.ministry_id
     LEFT JOIN service_requests sr ON sr.id = sp.service_request_id
     LEFT JOIN fiscal_services fs ON fs.id = sr.fiscal_service_id
  WHERE sp.created_at >= (CURRENT_DATE - '365 days'::interval)
  GROUP BY (date(sp.created_at)), sp.payment_method, sp.entity_code, e.name, e.ministry_id, m.name_es, sr.workflow_code, sr.solicitud_type, fs.name_es;
WITH NO DATA;

CREATE MATERIALIZED VIEW IF NOT EXISTS "public"."sectors_with_stats" AS
 SELECT s.id,
    s.sector_code,
    s.ministry_id,
    s.name_es,
    s.description_es,
    s.is_active,
    count(DISTINCT c.id)::integer AS categories_count,
    count(DISTINCT fs.id)::integer AS services_count,
    now() AS last_updated
   FROM sectors s
     LEFT JOIN categories c ON c.sector_id = s.id AND c.is_active = true
     LEFT JOIN fiscal_services fs ON fs.category_id = c.id AND fs.status = 'active'::service_status_enum
  WHERE s.is_active = true
  GROUP BY s.id, s.sector_code, s.ministry_id, s.name_es, s.description_es, s.is_active
  ORDER BY (count(DISTINCT fs.id)::integer) DESC, s.name_es;
WITH NO DATA;

CREATE MATERIALIZED VIEW IF NOT EXISTS "public"."translations_export" AS
 SELECT category,
    key_code,
    context,
    jsonb_build_object('es', es, 'fr', fr, 'en', en) AS translations,
    updated_at
   FROM translations
  ORDER BY category, key_code;
WITH NO DATA;

CREATE MATERIALIZED VIEW IF NOT EXISTS "public"."v_amount_adjustments_audit" AS
 SELECT daa.id AS adjustment_id,
    daa.original_amount,
    daa.adjusted_amount,
    daa.difference,
    daa.percentage_change,
    daa.requires_supervisor_approval,
    daa.status AS adjustment_status,
    td.declaration_number,
    td.declaration_type::text AS declaration_type,
    td.fiscal_year,
    td.fiscal_period,
    ar.reason_code,
    ar.name_es AS reason_name,
    ar.category AS reason_category,
    daa.adjustment_reason_custom,
    u_adjusted.full_name AS adjusted_by_name,
    u_adjusted.email AS adjusted_by_email,
    u_adjusted.matricule AS adjusted_by_matricule,
    u_approved.full_name AS approved_by_name,
    u_approved.email AS approved_by_email,
    u_approved.matricule AS approved_by_matricule,
    daa.approval_notes,
    daa.created_at AS adjustment_created_at,
    daa.approved_at
   FROM declaration_amount_adjustments daa
     JOIN tax_declarations td ON daa.tax_declaration_id = td.id
     LEFT JOIN adjustment_reasons ar ON daa.adjustment_reason_id = ar.id
     JOIN users u_adjusted ON daa.adjusted_by = u_adjusted.id
     LEFT JOIN users u_approved ON daa.approved_by = u_approved.id
  ORDER BY daa.created_at DESC;
WITH NO DATA;

CREATE MATERIALIZED VIEW IF NOT EXISTS "public"."v_declarations_dashboard" AS
 SELECT td.id AS declaration_id,
    td.declaration_number,
    td.fiscal_year,
    td.fiscal_period,
    td.status AS declaration_status,
    td.declaration_nature,
    td.declaration_type::text AS declaration_type_code,
    COALESCE(iva.total_a_ingresar, irpf.total_a_ingresar, petro.total_a_ingresar, gen.final_amount, 0::numeric) AS total_amount,
    u.id AS user_id,
    u.full_name AS user_full_name,
    u.email AS user_email,
    c.id AS company_id,
    c.legal_name AS company_name,
    c.tax_id AS company_tax_id,
    td.submitted_at,
    td.processed_by,
    td.processed_at,
        CASE
            WHEN td.status = 'submitted'::declaration_status_enum AND td.submitted_at < (now() - '48:00:00'::interval) THEN 'critical'::text
            WHEN td.status = 'submitted'::declaration_status_enum AND td.submitted_at < (now() - '24:00:00'::interval) THEN 'urgent'::text
            WHEN td.status = 'rejected'::declaration_status_enum THEN 'warning'::text
            ELSE 'normal'::text
        END AS priority_status,
    EXTRACT(epoch FROM now() - td.submitted_at) / 3600::numeric AS age_hours,
        CASE
            WHEN iva.id IS NOT NULL THEN 'iva'::text
            WHEN irpf.id IS NOT NULL THEN 'irpf'::text
            WHEN petro.id IS NOT NULL THEN 'petroliferos'::text
            WHEN gen.id IS NOT NULL THEN 'generic'::text
            ELSE 'unknown'::text
        END AS data_type,
    td.created_at,
    td.updated_at
   FROM tax_declarations td
     JOIN users u ON td.user_id = u.id
     LEFT JOIN companies c ON td.company_id = c.id
     LEFT JOIN declaration_iva_details iva ON td.id = iva.tax_declaration_id
     LEFT JOIN declaration_irpf_data irpf ON td.id = irpf.tax_declaration_id
     LEFT JOIN declaration_petroliferos_details petro ON td.id = petro.tax_declaration_id
     LEFT JOIN declaration_other_details gen ON td.id = gen.tax_declaration_id
  WHERE td.status = ANY (ARRAY['draft'::declaration_status_enum, 'submitted'::declaration_status_enum, 'processing'::declaration_status_enum, 'rejected'::declaration_status_enum, 'accepted'::declaration_status_enum])
  ORDER BY (
        CASE td.status
            WHEN 'rejected'::declaration_status_enum THEN 1
            WHEN 'submitted'::declaration_status_enum THEN 2
            WHEN 'processing'::declaration_status_enum THEN 3
            WHEN 'accepted'::declaration_status_enum THEN 4
            ELSE 5
        END), td.submitted_at DESC;
WITH NO DATA;

CREATE MATERIALIZED VIEW IF NOT EXISTS "public"."v_declarations_stats" AS
 SELECT td.declaration_type,
    count(DISTINCT td.id) AS declarations_count,
    count(DISTINCT p.id) AS payments_count,
    sum(p.amount) AS total_amount,
    avg(p.amount) AS avg_amount,
    min(td.created_at) AS first_declaration,
    max(td.created_at) AS last_declaration,
    count(DISTINCT td.user_id) AS unique_users,
    count(DISTINCT td.company_id) AS unique_companies
   FROM tax_declarations td
     LEFT JOIN payments p ON p.tax_declaration_id = td.id
  GROUP BY td.declaration_type;
WITH NO DATA;

CREATE MATERIALIZED VIEW IF NOT EXISTS "public"."v_declarations_stats_by_type" AS
 SELECT td.declaration_type::text AS declaration_type_code,
    count(td.id) AS total_declarations,
    count(td.id) FILTER (WHERE td.status = 'draft'::declaration_status_enum) AS count_draft,
    count(td.id) FILTER (WHERE td.status = 'submitted'::declaration_status_enum) AS count_submitted,
    count(td.id) FILTER (WHERE td.status = 'processing'::declaration_status_enum) AS count_processing,
    count(td.id) FILTER (WHERE td.status = 'accepted'::declaration_status_enum) AS count_accepted,
    count(td.id) FILTER (WHERE td.status = 'rejected'::declaration_status_enum) AS count_rejected,
    sum(COALESCE(iva.total_a_ingresar, irpf.total_a_ingresar, petro.total_a_ingresar, gen.final_amount, 0::numeric)) AS total_amount_sum,
    avg(COALESCE(iva.total_a_ingresar, irpf.total_a_ingresar, petro.total_a_ingresar, gen.final_amount, 0::numeric)) AS average_amount,
    max(COALESCE(iva.total_a_ingresar, irpf.total_a_ingresar, petro.total_a_ingresar, gen.final_amount, 0::numeric)) AS max_amount,
    avg(EXTRACT(epoch FROM td.processed_at - td.submitted_at) / 3600::numeric) FILTER (WHERE td.processed_at IS NOT NULL) AS avg_processing_hours,
    round(100.0 * count(td.id) FILTER (WHERE td.status = 'accepted'::declaration_status_enum)::numeric / NULLIF(count(td.id) FILTER (WHERE td.status = ANY (ARRAY['accepted'::declaration_status_enum, 'rejected'::declaration_status_enum])), 0)::numeric, 2) AS approval_rate_percentage,
    max(td.updated_at) AS last_updated
   FROM tax_declarations td
     LEFT JOIN declaration_iva_details iva ON td.id = iva.tax_declaration_id
     LEFT JOIN declaration_irpf_data irpf ON td.id = irpf.tax_declaration_id
     LEFT JOIN declaration_petroliferos_details petro ON td.id = petro.tax_declaration_id
     LEFT JOIN declaration_other_details gen ON td.id = gen.tax_declaration_id
  GROUP BY td.declaration_type
  ORDER BY (sum(COALESCE(iva.total_a_ingresar, irpf.total_a_ingresar, petro.total_a_ingresar, gen.final_amount, 0::numeric))) DESC NULLS LAST;
WITH NO DATA;

CREATE MATERIALIZED VIEW IF NOT EXISTS "public"."v_document_templates_stats" AS
 SELECT dt.template_code,
    dt.document_name_es,
    dt.category,
    dt.validity_duration_months,
    count(DISTINCT sda.fiscal_service_id) AS services_count,
    count(DISTINCT
        CASE
            WHEN sda.is_required_expedition THEN sda.id
            ELSE NULL::integer
        END) AS required_expedition_count,
    count(DISTINCT
        CASE
            WHEN sda.is_required_renewal THEN sda.id
            ELSE NULL::integer
        END) AS required_renewal_count,
    jsonb_agg(DISTINCT fs.service_code ORDER BY fs.service_code) AS service_codes
   FROM document_templates dt
     LEFT JOIN service_document_assignments sda ON sda.document_template_id = dt.id
     LEFT JOIN fiscal_services fs ON fs.id = sda.fiscal_service_id
  GROUP BY dt.template_code, dt.document_name_es, dt.category, dt.validity_duration_months;
WITH NO DATA;

CREATE MATERIALIZED VIEW IF NOT EXISTS "public"."v_import_batches_summary" AS
 SELECT ib.id AS batch_id,
    ib.file_name,
    ib.import_type,
    ib.status AS batch_status,
    ib.total_rows,
    ib.rows_processed,
    ib.rows_success,
    ib.rows_failed,
    round(100.0 * ib.rows_success::numeric / NULLIF(ib.total_rows, 0)::numeric, 2) AS success_rate_percentage,
    u.full_name AS uploaded_by_name,
    u.email AS uploaded_by_email,
    EXTRACT(epoch FROM ib.completed_at - ib.started_at) AS processing_duration_seconds,
    ( SELECT jsonb_agg(jsonb_build_object('error', errors.validation_errors, 'count', errors.error_count)) AS jsonb_agg
           FROM ( SELECT ibi.validation_errors,
                    count(*) AS error_count
                   FROM import_batch_items ibi
                  WHERE ibi.batch_id = ib.id AND (ibi.status::text = ANY (ARRAY['invalid'::character varying, 'failed'::character varying]::text[])) AND ibi.validation_errors IS NOT NULL
                  GROUP BY ibi.validation_errors
                  ORDER BY (count(*)) DESC
                 LIMIT 3) errors) AS top_errors,
    ib.created_at,
    ib.started_at,
    ib.completed_at
   FROM import_batches ib
     JOIN users u ON ib.uploaded_by = u.id
  ORDER BY ib.created_at DESC;
WITH NO DATA;

CREATE MATERIALIZED VIEW IF NOT EXISTS "public"."v_ocr_extraction_stats" AS
 SELECT date_trunc('day'::text, oer.created_at) AS extraction_date,
    ft.template_code,
    ft.name_es AS template_name,
    ft.template_category,
    count(oer.id) AS total_extractions,
    count(oer.id) FILTER (WHERE oer.status::text = 'validated'::text) AS count_validated,
    count(oer.id) FILTER (WHERE oer.status::text = 'rejected'::text) AS count_rejected,
    count(oer.id) FILTER (WHERE oer.status::text = 'corrected'::text) AS count_corrected,
    round(100.0 * count(oer.id) FILTER (WHERE oer.status::text = 'validated'::text)::numeric / NULLIF(count(oer.id), 0)::numeric, 2) AS success_rate_percentage,
    avg(oer.confidence_score) AS avg_confidence_score,
    min(oer.confidence_score) AS min_confidence_score,
    max(oer.confidence_score) AS max_confidence_score,
    avg(oer.processing_time_ms) AS avg_processing_time_ms,
    max(oer.processing_time_ms) AS max_processing_time_ms,
    mode() WITHIN GROUP (ORDER BY oer.language_used) AS most_used_language
   FROM ocr_extraction_results oer
     LEFT JOIN uploaded_files uf ON oer.uploaded_file_id = uf.id
     LEFT JOIN tax_declarations td ON uf.tax_declaration_id = td.id
     LEFT JOIN form_templates ft ON ft.declaration_type = td.declaration_type
  WHERE oer.ocr_engine = 'tesseract'::ocr_engine_enum
  GROUP BY (date_trunc('day'::text, oer.created_at)), ft.template_code, ft.name_es, ft.template_category
  ORDER BY (date_trunc('day'::text, oer.created_at)) DESC, (count(oer.id)) DESC;
WITH NO DATA;

CREATE MATERIALIZED VIEW IF NOT EXISTS "public"."v_payment_plans_monitoring" AS
 SELECT pp.id AS payment_plan_id,
    pp.total_amount,
    pp.total_paid,
    pp.remaining_balance,
    pp.number_of_installments,
    pp.status AS plan_status,
    td.declaration_number,
    td.declaration_type::text AS declaration_type,
    u.id AS user_id,
    u.full_name AS user_full_name,
    u.email AS user_email,
    count(pi.id) AS total_installments,
    count(pi.id) FILTER (WHERE pi.status::text = 'paid'::text) AS installments_paid,
    count(pi.id) FILTER (WHERE pi.status::text = 'overdue'::text) AS installments_overdue,
    count(pi.id) FILTER (WHERE pi.status::text = 'pending'::text) AS installments_pending,
    sum(pi.amount_due) AS total_due,
    sum(pi.amount_paid) AS total_paid_installments,
    sum(pi.late_fee) AS total_late_fees,
    min(pi.due_date) FILTER (WHERE pi.status::text = 'pending'::text) AS next_due_date,
    min(pi.amount_due) FILTER (WHERE pi.status::text = 'pending'::text) AS next_amount_due,
        CASE
            WHEN count(pi.id) FILTER (WHERE pi.status::text = 'overdue'::text) > 0 THEN 'has_overdue'::text
            WHEN min(pi.due_date) FILTER (WHERE pi.status::text = 'pending'::text) < (CURRENT_DATE + '7 days'::interval) THEN 'due_soon'::text
            ELSE 'ok'::text
        END AS alert_status,
    pp.created_at,
    pp.updated_at
   FROM payment_plans pp
     JOIN tax_declarations td ON pp.tax_declaration_id = td.id
     JOIN users u ON td.user_id = u.id
     LEFT JOIN payment_installments pi ON pp.id = pi.payment_plan_id
  WHERE pp.status::text = ANY (ARRAY['active'::character varying, 'defaulted'::character varying]::text[])
  GROUP BY pp.id, td.declaration_number, td.declaration_type, u.id, u.full_name, u.email
  ORDER BY (
        CASE
            WHEN count(pi.id) FILTER (WHERE pi.status::text = 'overdue'::text) > 0 THEN 1
            WHEN min(pi.due_date) FILTER (WHERE pi.status::text = 'pending'::text) < (CURRENT_DATE + '7 days'::interval) THEN 2
            ELSE 3
        END), pp.created_at DESC;
WITH NO DATA;

CREATE MATERIALIZED VIEW IF NOT EXISTS "public"."v_payments_dashboard" AS
 SELECT p.id AS payment_id,
    p.amount,
    p.currency,
    p.payment_type,
    p.status AS payment_status,
    p.payment_method,
    p.bank_reference,
        CASE
            WHEN p.fiscal_service_id IS NOT NULL THEN 'fiscal_service'::text
            WHEN p.tax_declaration_id IS NOT NULL THEN 'tax_declaration'::text
            ELSE 'unknown'::text
        END AS payment_source_type,
    p.fiscal_service_id,
    p.tax_declaration_id,
    fs.service_code,
    fs.name_es AS service_name,
    td.declaration_number,
    td.declaration_type::text AS declaration_type,
    u.id AS user_id,
    u.full_name AS user_full_name,
    u.email AS user_email,
    pp.id AS payment_plan_id,
    pp.total_amount AS plan_total_amount,
    pp.remaining_balance AS plan_remaining_balance,
    pi.installment_number,
    pi.due_date AS installment_due_date,
    bt.bank_code,
    bt.bank_transaction_date,
    bt.status AS bank_transaction_status,
        CASE
            WHEN p.status = 'pending'::payment_status_enum AND p.created_at < (now() - '72:00:00'::interval) THEN 'critical'::text
            WHEN p.status = 'processing'::payment_status_enum AND p.created_at < (now() - '48:00:00'::interval) THEN 'urgent'::text
            WHEN p.status = 'failed'::payment_status_enum THEN 'warning'::text
            ELSE 'normal'::text
        END AS priority_status,
    p.created_at,
    p.updated_at,
    p.paid_at
   FROM payments p
     JOIN users u ON p.user_id = u.id
     LEFT JOIN fiscal_services fs ON p.fiscal_service_id = fs.id
     LEFT JOIN tax_declarations td ON p.tax_declaration_id = td.id
     LEFT JOIN payment_plans pp ON p.payment_plan_id = pp.id
     LEFT JOIN payment_installments pi ON p.installment_id = pi.id
     LEFT JOIN bank_transactions bt ON p.bank_transaction_id = bt.id
  WHERE p.status = ANY (ARRAY['pending'::payment_status_enum, 'processing'::payment_status_enum, 'completed'::payment_status_enum, 'failed'::payment_status_enum])
  ORDER BY (
        CASE p.status
            WHEN 'failed'::payment_status_enum THEN 1
            WHEN 'processing'::payment_status_enum THEN 2
            WHEN 'pending'::payment_status_enum THEN 3
            WHEN 'completed'::payment_status_enum THEN 4
            ELSE 5
        END), p.created_at DESC;
WITH NO DATA;

CREATE MATERIALIZED VIEW IF NOT EXISTS "public"."v_service_procedures_denormalized" AS
 SELECT fs.service_code,
    fs.name_es,
    pt.template_code,
    jsonb_agg(jsonb_build_object('step_number', pts.step_number, 'description_es', pts.description_es, 'instructions_es', pts.instructions_es, 'estimated_duration_minutes', pts.estimated_duration_minutes, 'requires_appointment', pts.requires_appointment) ORDER BY pts.step_number) AS procedures_json
   FROM fiscal_services fs
     JOIN service_procedure_assignments spa ON spa.fiscal_service_id = fs.id
     JOIN procedure_templates pt ON pt.id = spa.template_id
     JOIN procedure_template_steps pts ON pts.template_id = pt.id
  WHERE fs.status = 'active'::service_status_enum
  GROUP BY fs.service_code, fs.name_es, pt.template_code;
WITH NO DATA;

CREATE MATERIALIZED VIEW IF NOT EXISTS "public"."v_services_by_ministry" AS
 SELECT m.ministry_code,
    m.name_es AS ministry_name,
    count(DISTINCT fs.id) AS services_count,
    count(DISTINCT
        CASE
            WHEN fs.status = 'active'::service_status_enum THEN fs.id
            ELSE NULL::integer
        END) AS active_services,
    count(DISTINCT spa.template_id) AS procedure_templates_used,
    count(DISTINCT sda.document_template_id) AS document_templates_used,
    jsonb_agg(jsonb_build_object('service_code', fs.service_code, 'name', fs.name_es, 'status', fs.status) ORDER BY fs.service_code) FILTER (WHERE fs.status = 'active'::service_status_enum) AS active_services_list
   FROM ministries m
     LEFT JOIN sectors s ON s.ministry_id = m.id
     LEFT JOIN categories c ON c.sector_id = s.id
     LEFT JOIN fiscal_services fs ON fs.category_id = c.id
     LEFT JOIN service_procedure_assignments spa ON spa.fiscal_service_id = fs.id
     LEFT JOIN service_document_assignments sda ON sda.fiscal_service_id = fs.id
  GROUP BY m.ministry_code, m.name_es;
WITH NO DATA;

CREATE MATERIALIZED VIEW IF NOT EXISTS "public"."v_services_with_preview" AS
 SELECT service_code,
    name_es,
    description_es,
    ( SELECT pts.description_es
           FROM service_procedure_assignments spa
             JOIN procedure_template_steps pts ON pts.template_id = spa.template_id
          WHERE spa.fiscal_service_id = fs.id AND pts.step_number = 1
          ORDER BY spa.display_order
         LIMIT 1) AS instructions_preview
   FROM fiscal_services fs
  WHERE status = 'active'::service_status_enum;
WITH NO DATA;

CREATE MATERIALIZED VIEW IF NOT EXISTS "public"."v_templates_usage_stats" AS
 SELECT pt.template_code,
    pt.name_es AS template_name,
    pt.category,
    count(DISTINCT spa.fiscal_service_id) AS services_count,
    count(DISTINCT pts.id) AS steps_count,
    jsonb_agg(DISTINCT fs.service_code ORDER BY fs.service_code) AS service_codes
   FROM procedure_templates pt
     LEFT JOIN procedure_template_steps pts ON pts.template_id = pt.id
     LEFT JOIN service_procedure_assignments spa ON spa.template_id = pt.id
     LEFT JOIN fiscal_services fs ON fs.id = spa.fiscal_service_id
  GROUP BY pt.template_code, pt.name_es, pt.category;
WITH NO DATA;

CREATE MATERIALIZED VIEW IF NOT EXISTS "public"."v_translations_coverage" AS
 SELECT entity_type,
    language_code,
    count(DISTINCT entity_code) AS entities_count,
    count(*) AS translations_count,
    count(DISTINCT field_name) AS fields_translated,
    avg(translation_quality) AS avg_quality,
    min(created_at) AS first_translation,
    max(created_at) AS last_translation
   FROM entity_translations
  GROUP BY entity_type, language_code;
WITH NO DATA;

